INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e3d5ee-5291-49b6-87b8-e34259d02eaf', '和周繇見嘲', '和周繇见嘲', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["才甘魚目並，藝怯馬蹄間。","王謝初飛蓋，姬姜盡下山。","縛雞方角逐，射雉豈開顏。","亂翠移林色，狂紅照座殷。","防梭齒雖在，乞帽鬢慙斑。","儻恕相如瘦，應容累騎還。"]', '["才甘鱼目並，藝怯马蹄间。","王謝初飞蓋，姬姜尽下山。","縛雞方角逐，射雉豈开顏。","亂翠移林色，狂紅照座殷。","防梭齒雖在，乞帽鬢慙斑。","儻恕相如瘦，應容累騎還。"]', '诗', 'shi', '', NULL, '和周繇見嘲 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c845b275-f883-4f4c-b91f-a2592325c268', '和張希復詠宣律和尚袈裟', '和張希复詠宣律和尚袈裟', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["南山披時寒夜中，一角不動毗嵐風。","何人見此生慙媿，斷續猶應護得龍。"]', '["南山披时寒夜中，一角不动毗嵐风。","何人见此生慙媿，斷續猶應護得龙。"]', '诗', 'shi', '', NULL, '和張希復詠宣律和尚袈裟 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd8d1f57-5922-4c88-8d7b-859f871d39c7', '句', '句', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["高談敬風鑒，古貌怯冰稜。","虱暴妨歸夢，蟲喧徹曙更。","夢裏思甘露，言中惜惠燈。","新破毗曇義，相期卜夜論。","隨樵劫猨藏，隈石覷熊緣。","[捽]胡雲彩落，疻面月痕消。","擲履仙鳧起，撦衣蝴蝶飄。","羞中含薄怒，顰裏帶餘嬌。","醒後猶攘臂，歸時更折腰。","狂夫自纓絕，眉勢倩人描。","不願石郎戴笠，難甘玉女披衣。"]', '["高談敬风鑒，古貌怯冰稜。","虱暴妨归梦，蟲喧徹曙更。","梦裏思甘露，言中惜惠灯。","新破毗曇義，相期卜夜論。","隨樵劫猨藏，隈石覷熊緣。","[捽]胡云彩落，疻面月痕消。","擲履仙鳧起，撦衣蝴蝶飄。","羞中含薄怒，顰裏带餘嬌。","醒後猶攘臂，归时更折腰。","狂夫自纓絕，眉勢倩人描。","不願石郎戴笠，难甘玉女披衣。"]', '诗', 'shi', '', NULL, '句 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc0d549b-88a1-41eb-b24a-5e93327ceb9d', '皎皎詞', '皎皎词', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["皎皎復皎皎，逢時即爲好。","高秋亦有花，不及當春草。","班姬入後宮，飛燕舞東風。","青娥中夜起，長歎月明裏。"]', '["皎皎复皎皎，逢时即爲好。","高秋亦有花，不及當春草。","班姬入後宮，飞燕舞东风。","青娥中夜起，长歎月明裏。"]', '诗', 'shi', '', NULL, '皎皎詞 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e05b13b-fff6-47d7-ad13-1c95995b019c', '長安旅舍紓情投先達', '长安旅舍紓情投先達', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["岐路不在地，馬蹄徒苦辛。","上國聞姓名，不如山中人。","大宅滿六街，此身入誰門。","愁心日散亂，有似空中塵。","白露下長安，百蟲鳴草根。","方當秋賦日，却憶歸山村。","靜女頭欲白，良媒況我鄰。","無令苦長歎，長歎銷人魂。"]', '["岐路不在地，马蹄徒苦辛。","上国闻姓名，不如山中人。","大宅满六街，此身入誰门。","愁心日散亂，有似空中塵。","白露下长安，百蟲鳴草根。","方當秋賦日，却憶归山村。","静女头欲白，良媒況我鄰。","無令苦长歎，长歎銷人魂。"]', '诗', 'shi', '', NULL, '長安旅舍紓情投先達 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a94e5511-ebc4-4777-8f91-e5026e6154bf', '送友下第遊鴈門', '送友下第游鴈门', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["相別灞水湄，夾水柳依依。","我願醉如死，不見君去時。","所詣星斗北，直行到猶遲。","況復挈空囊，求人悲路岐。","北門記室賢，愛我學古詩。","待君如待我，此事固不疑。","鴈門春色外，四月鴈未歸。","主人拂金臺，延客夜開扉。","舒君鬱鬱懷，飲彼白玉巵。","若不化女子，功名豈無期。"]', '["相別灞水湄，夾水柳依依。","我願醉如死，不见君去时。","所詣星斗北，直行到猶遲。","況复挈空囊，求人悲路岐。","北门記室賢，愛我学古诗。","待君如待我，此事固不疑。","鴈门春色外，四月鴈未归。","主人拂金台，延客夜开扉。","舒君鬱鬱懷，饮彼白玉巵。","若不化女子，功名豈無期。"]', '诗', 'shi', '', NULL, '送友下第遊鴈門 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('156ffb02-1b3a-4184-bda4-63b082c75a2f', '讀史', '读史', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["平地見天涯，登高天更遠。","功名及所望，岐路又滿眼。","萬金買園林，千金修池館。","他人厭遊覽，身獨戀軒冕。","唯有漢二疎，應覺還家晚。"]', '["平地见天涯，登高天更远。","功名及所望，岐路又满眼。","万金買园林，千金修池館。","他人厭游覽，身独戀軒冕。","唯有漢二疎，應覺還家晚。"]', '诗', 'shi', '', NULL, '讀史 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bed8b8f-b8b1-4613-b6b3-de5db26baf51', '反賈客樂', '反賈客乐', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["無言賈客樂，賈客多無墓。","行舟觸風浪，盡入魚腹去。","農夫更苦辛，所以羨爾身。"]', '["無言賈客乐，賈客多無墓。","行舟觸风浪，尽入鱼腹去。","農夫更苦辛，所以羨爾身。"]', '诗', 'shi', '', NULL, '反賈客樂 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('954e88e0-4739-4b63-9e78-f03e3642d795', '送李垣先輩歸嵩少舊居', '送李垣先輩归嵩少旧居', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["高秋灞滻路，游子多慘戚。","君於此地行，獨以尋春色。","文章滿人口，高第非苟得。","要路在長安，歸山却爲客。","□□□□□，狂歌罷歎息。","我豈無故山，千里同外國。"]', '["高秋灞滻路，游子多慘戚。","君於此地行，独以尋春色。","文章满人口，高第非苟得。","要路在长安，归山却爲客。","□□□□□，狂歌罷歎息。","我豈無故山，千里同外国。"]', '诗', 'shi', '', NULL, '送李垣先輩歸嵩少舊居 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e077249a-264b-4f01-97dc-c37c03b1d204', '苦寒吟', '苦寒吟', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["百泉凍皆咽，我吟寒更切。","半夜倚喬松，不覺滿衣雪。","竹竿有甘苦，我愛抱苦節。","鳥聲有悲歡，我愛口流血。","潘生若解吟，更早生白髮。"]', '["百泉凍皆咽，我吟寒更切。","半夜倚喬松，不覺满衣雪。","竹竿有甘苦，我愛抱苦節。","鸟声有悲歡，我愛口流血。","潘生若解吟，更早生白髮。"]', '诗', 'shi', '', NULL, '苦寒吟 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35d2be2-cf3a-4fa7-91a6-0760c20e17b8', '上巳日', '上巳日', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["上巳曲江濱，喧於市朝路。","相尋不見者，此地皆相遇。","日光去此遠，翠幕張如霧。","何事歡娛中，易覺春城暮。","物情重此節，不是愛芳樹。","明日花更多，何人肯回顧。"]', '["上巳曲江濱，喧於市朝路。","相尋不见者，此地皆相遇。","日光去此远，翠幕張如霧。","何事歡娛中，易覺春城暮。","物情重此節，不是愛芳樹。","明日花更多，何人肯回顧。"]', '诗', 'shi', '', NULL, '上巳日 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51cd23e-b029-4192-903d-4fa04135cd85', '春臺', '春台', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["臺上樹陰合，臺前流水多。","青春不出門，坐見野田花。","誰能學公子，走馬逐香車。","六街塵滿衣，鼓絕方還家。"]', '["台上樹陰合，台前流水多。","青春不出门，坐见野田花。","誰能学公子，走马逐香车。","六街塵满衣，鼓絕方還家。"]', '诗', 'shi', '', NULL, '春臺 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba168742-b63d-4440-9f72-cf9dcbb809e6', '釣臺懷古', '釣台懷古', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["澄流可濯纓，嚴子但垂綸。","孤坐九層石，遠笑清渭濱。","潛龍飛上天，四海豈無雲。","清氣不零雨，安使洗塵氛。","我來吟高風，髣髴見斯人。","江月尚皎皎，江石亦磷磷。","如何臺下路，明日又迷津。"]', '["澄流可濯纓，嚴子但垂綸。","孤坐九層石，远笑清渭濱。","潛龙飞上天，四海豈無云。","清氣不零雨，安使洗塵氛。","我来吟高风，髣髴见斯人。","江月尚皎皎，江石亦磷磷。","如何台下路，明日又迷津。"]', '诗', 'shi', '', NULL, '釣臺懷古 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa3dec00-8c3a-4be8-896e-a0c1124e2dcc', '勵志', '勵志', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["白髮豈有情，貴賤同日生。","二輪不暫駐，似趂長安程。","前堂吹參差，不作緱山聲。","後園植木槿，月照無餘英。","及時立功德，身後猶光明。","仲尼亦爲土，魯人焉敢耕。"]', '["白髮豈有情，貴賤同日生。","二輪不暫駐，似趂长安程。","前堂吹參差，不作緱山声。","後园植木槿，月照無餘英。","及时立功德，身後猶光明。","仲尼亦爲土，魯人焉敢耕。"]', '诗', 'shi', '', NULL, '勵志 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51f0299f-1343-44c2-8f6f-3d519c61d185', '桑婦', '桑婦', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["牆下桑葉盡，春蠶半未老。","城南路迢迢，今日起更早。","四鄰無去伴，醉臥青樓曉。","妾顏不如誰，所貴守婦道。","一春常在樹，自覺身如鳥。","歸來見小姑，新妝弄百草。"]', '["牆下桑葉尽，春蠶半未老。","城南路迢迢，今日起更早。","四鄰無去伴，醉臥青楼晓。","妾顏不如誰，所貴守婦道。","一春常在樹，自覺身如鸟。","归来见小姑，新妝弄百草。"]', '诗', 'shi', '', NULL, '桑婦 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3887e3-3028-4fbb-a233-2ff210636962', '上馬歎', '上马歎', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["羸馬行遲遲，頑童去我遠。","時時一回顧，不覺白日晚。","路傍豪家宅，樓上紅妝滿。","十月庭花開，花前吹玉管。","君當未貴日，豈不常屯蹇。","如何見布衣，忽若塵入眼。","布衣豈常賤，世事車輪轉。"]', '["羸马行遲遲，頑童去我远。","时时一回顧，不覺白日晚。","路傍豪家宅，楼上紅妝满。","十月庭花开，花前吹玉管。","君當未貴日，豈不常屯蹇。","如何见布衣，忽若塵入眼。","布衣豈常賤，世事车輪轉。"]', '诗', 'shi', '', NULL, '上馬歎 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0089d274-23b7-4a71-a726-ae49f69b8f9f', '唐樂府十首 送征夫', '唐乐府十首 送征夫', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["昔送征夫苦，今送征夫樂。","寒衣縱攜去，應向歸時着。","天子待功成，別造凌煙閣。"]', '["昔送征夫苦，今送征夫乐。","寒衣縱携去，應向归时着。","天子待功成，別造凌煙閣。"]', '诗', 'shi', '', NULL, '唐樂府十首 送征夫 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b63a225-2308-43dd-93ae-f056d80f2ff5', '唐樂府十首 輪者謳', '唐乐府十首 輪者謳', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["輓粟上高山，高山若平地。","力盡心不怨，同我家私事。","去者不遑寧，歸者唱歌行。","相逢古城下，立語天未明。","一身遠出塞，十口無稅征。"]', '["輓粟上高山，高山若平地。","力尽心不怨，同我家私事。","去者不遑寧，归者唱歌行。","相逢古城下，立語天未明。","一身远出塞，十口無稅征。"]', '诗', 'shi', '', NULL, '唐樂府十首 輪者謳 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ccc1a01-4f06-4f88-adb1-0371a15a34a8', '唐樂府十首 弔西人', '唐乐府十首 弔西人', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["河湟父老地，盡知歸明主。","將軍入空城，城下弔黃土。","所願邊人耕，歲歲生禾黍。"]', '["河湟父老地，尽知归明主。","將軍入空城，城下弔黄土。","所願邊人耕，歲歲生禾黍。"]', '诗', 'shi', '', NULL, '唐樂府十首 弔西人 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be05b79f-3303-406d-a678-a9763ae812b5', '唐樂府十首 邊軍過', '唐乐府十首 邊軍過', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["城前兵馬過，城裏人高臥。","官家自供給，畏我田產破。","健兒食肥肉，戰馬食新穀。","食飽物有餘，所恨無兩腹。","草青見軍過，草白見軍回。","軍回人更多，盡繫西戎來。"]', '["城前兵马過，城裏人高臥。","官家自供給，畏我田產破。","健兒食肥肉，戰马食新穀。","食飽物有餘，所恨無兩腹。","草青见軍過，草白见軍回。","軍回人更多，尽繫西戎来。"]', '诗', 'shi', '', NULL, '唐樂府十首 邊軍過 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16447587-81e6-483c-93a1-35b82e434ffb', '唐樂府十首 望歸馬', '唐乐府十首 望归马', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["東人望歸馬，馬歸蓮峰下。","蓮峰與地平，亦不更徵兵。"]', '["东人望归马，马归蓮峰下。","蓮峰與地平，亦不更徵兵。"]', '诗', 'shi', '', NULL, '唐樂府十首 望歸馬 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed953411-b9ca-4f27-805b-cbd5e2f7e66a', '唐樂府十首 祝河水', '唐乐府十首 祝河水', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["河水清瀰瀰，照見遠樹枝。","征人不飲馬，再拜祝馮夷。","從今億萬歲，不見河濁時。"]', '["河水清瀰瀰，照见远樹枝。","征人不饮马，再拜祝馮夷。","從今億万歲，不见河濁时。"]', '诗', 'shi', '', NULL, '唐樂府十首 祝河水 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc3cca75-f9f7-432f-bd1a-0e2ac34e56ff', '唐樂府十首 田西邊', '唐乐府十首 田西邊', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["刀劒作鋤犂，耕田古城下。","高秋禾黍多，無地放羊馬。"]', '["刀劒作鋤犂，耕田古城下。","高秋禾黍多，無地放羊马。"]', '诗', 'shi', '', NULL, '唐樂府十首 田西邊 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('364236ad-83bb-4964-b861-ceaa54971cec', '唐樂府十首 崑山', '唐乐府十首 崑山', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["昔時玉爲寶，崑山過不得。","今時玉爲塵，崑山入中國。","白玉尚如塵，誰肯愛金銀。"]', '["昔时玉爲寶，崑山過不得。","今时玉爲塵，崑山入中国。","白玉尚如塵，誰肯愛金銀。"]', '诗', 'shi', '', NULL, '唐樂府十首 崑山 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2ee4014-fbfd-4fff-a2ad-98cf6d1321fb', '唐樂府十首 樂邊人', '唐乐府十首 乐邊人', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["在鄉身亦勞，在邊腹亦飽。","父兄若一處，任向邊頭老。"]', '["在乡身亦勞，在邊腹亦飽。","父兄若一处，任向邊头老。"]', '诗', 'shi', '', NULL, '唐樂府十首 樂邊人 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc248344-300a-490d-b356-9dffbb8ed849', '唐樂府十首 獻賀觴', '唐乐府十首 獻賀觴', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["莫但取河湟，河湟非邊疆。","願今日入處，亦似天中央。","天子壽萬歲，再拜獻此觴。"]', '["莫但取河湟，河湟非邊疆。","願今日入处，亦似天中央。","天子壽万歲，再拜獻此觴。"]', '诗', 'shi', '', NULL, '唐樂府十首 獻賀觴 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d01b612-00ec-4686-b8a2-7efa3794f537', '且可憐行', '且可怜行', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["園中花自早，不信外無花。","良人未朝去，先出登香車。","□□五□輪，滿城聞嘔啞。","侍兒衣各別，頭上金雀多。","祗是一家人，路人疑千家。","過後香滿陌，直到春日斜。","今朝且可憐，莫問久如何。"]', '["园中花自早，不信外無花。","良人未朝去，先出登香车。","□□五□輪，满城闻嘔啞。","侍兒衣各別，头上金雀多。","祗是一家人，路人疑千家。","過後香满陌，直到春日斜。","今朝且可怜，莫问久如何。"]', '诗', 'shi', '', NULL, '且可憐行 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed2dd093-0504-4491-acb5-501395364dc6', '築臺詞', '築台词', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["前杵與後杵，築城聲不住。","我願築更高，得見秦皇墓。"]', '["前杵與後杵，築城声不住。","我願築更高，得见秦皇墓。"]', '诗', 'shi', '', NULL, '築臺詞 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00416097-77a2-452f-ba7e-f91aaea0dc48', '鄰女', '鄰女', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["君嫌鄰女醜，取婦他鄉縣。","料嫁與君人，亦爲鄰所賤。","菖蒲花可貴，只爲人難見。"]', '["君嫌鄰女醜，取婦他乡縣。","料嫁與君人，亦爲鄰所賤。","菖蒲花可貴，只爲人难见。"]', '诗', 'shi', '', NULL, '鄰女 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8312c504-7643-4308-b0ce-c19f5d58acd9', '山中夜坐', '山中夜坐', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["半夜山雨過，起來滿山月。","落盡醉處花，荒溝水決決。","愴然惜春去，似與故人別。","誰遣我多情，壯年無鬢髮。"]', '["半夜山雨過，起来满山月。","落尽醉处花，荒溝水決決。","愴然惜春去，似與故人別。","誰遣我多情，壯年無鬢髮。"]', '诗', 'shi', '', NULL, '山中夜坐 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ded5d1c-1c65-40fd-beec-40d42aa245d8', '秦娥', '秦娥', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["秦娥十四五，面白於指爪。","羞人夜採桑，驚起戴勝鳥。"]', '["秦娥十四五，面白於指爪。","羞人夜採桑，驚起戴勝鸟。"]', '诗', 'shi', '', NULL, '秦娥 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abef521e-2091-4bca-a199-52e0f82e7d98', '牧童', '牧童', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["牧童見客拜，山果懷中落。","晝日驅牛歸，前溪風雨惡。"]', '["牧童见客拜，山果懷中落。","晝日驱牛归，前溪风雨惡。"]', '诗', 'shi', '', NULL, '牧童 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1fdbe86-813d-4601-9df0-bd7e13d755de', '古出塞', '古出塞', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["胡風不開花，四氣多作雪。","北人尚凍死，況我本南越。","古來犬羊地，巡狩無遺轍。","九土耕不盡，武皇猶征伐。","中天有高閣，圖畫何時歇？","坐恐塞上山，低於沙中骨。"]', '["胡风不开花，四氣多作雪。","北人尚凍死，況我本南越。","古来犬羊地，巡狩無遺轍。","九土耕不尽，武皇猶征伐。","中天有高閣，圖畫何时歇？","坐恐塞上山，低於沙中骨。"]', '诗', 'shi', '', NULL, '古出塞 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('076e612c-0bcc-49d5-9b98-d5a0e26eb291', '寄遠', '寄远', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["雪花豈結子，徒滿連理枝。","嫁作征人妻，不得長相隨。","去年君點行，賤妾是新姬。","別早見未熟，入夢無定姿。","悄悄空閨中，蛩聲遶羅幃。","得書喜猶甚，況復見君時。"]', '["雪花豈結子，徒满連理枝。","嫁作征人妻，不得长相隨。","去年君点行，賤妾是新姬。","別早见未熟，入梦無定姿。","悄悄空閨中，蛩声遶羅幃。","得书喜猶甚，況复见君时。"]', '诗', 'shi', '', NULL, '寄遠 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27b64d41-4d4f-4be8-8f3d-8b84398e9536', '下第後屏居長安書懷寄太原從事', '下第後屏居长安书懷寄太原從事', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["刖足豈更長，良工隔千里。","故山彭蠡上，歸夢向汾水。","低摧神氣盡，僮僕心亦恥。","未達誰不然，達者心思此。","行年忽已壯，去老年更幾。","功名生不彰，身歿豈爲鬼。","纔看芳草歇，即歎涼風起。","匹馬未來期，嘶聲尚在耳。"]', '["刖足豈更长，良工隔千里。","故山彭蠡上，归梦向汾水。","低摧神氣尽，僮僕心亦恥。","未達誰不然，達者心思此。","行年忽已壯，去老年更幾。","功名生不彰，身歿豈爲鬼。","纔看芳草歇，即歎涼风起。","匹马未来期，嘶声尚在耳。"]', '诗', 'shi', '', NULL, '下第後屏居長安書懷寄太原從事 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('843b886c-6f77-414f-8525-656bb69edb4d', '早行', '早行', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["馬上續殘夢，馬嘶時復驚。","心孤多所虞，僮僕近我行。","棲禽未分散，落月照古城。","莫羨居者閑，冢邊人已耕。"]', '["马上續殘梦，马嘶时复驚。","心孤多所虞，僮僕近我行。","棲禽未分散，落月照古城。","莫羨居者闲，冢邊人已耕。"]', '诗', 'shi', '', NULL, '早行 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d75bf967-9c3d-49c2-a517-8635e8dabf6c', '青門路', '青门路', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["青門有歸路，坦坦高槐下。","貧賤自恥歸，此地誰留我。","門開送客去，落日嬾回馬。","旅食帝城中，不如遠遊者。","舟成於陸地，風水終相假。","吾道諒如斯，立身無苟且。"]', '["青门有归路，坦坦高槐下。","貧賤自恥归，此地誰留我。","门开送客去，落日嬾回马。","旅食帝城中，不如远游者。","舟成於陸地，风水終相假。","吾道諒如斯，立身無苟且。"]', '诗', 'shi', '', NULL, '青門路 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28af0461-760c-4a64-a79d-7f386cac8285', '效古', '效古', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["融融芳景和，杳杳春日斜。","嬌嬈不自持，清唱嚬雙蛾。","終曲翻成泣，新人下香車。","新人且莫喜，故人曾如此。","燕趙猶生女，郎豈有終始。"]', '["融融芳景和，杳杳春日斜。","嬌嬈不自持，清唱嚬雙蛾。","終曲翻成泣，新人下香车。","新人且莫喜，故人曾如此。","燕趙猶生女，郎豈有終始。"]', '诗', 'shi', '', NULL, '效古 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00b45f00-ba00-4cd8-99cc-ffe31d9109e4', '戰城南', '戰城南', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["城南征戰多，城北無飢鴉。","白骨馬蹄下，誰言皆有家。","城前水聲苦，倏忽流萬古。","莫爭城外城，城裏終閑土。"]', '["城南征戰多，城北無飢鴉。","白骨马蹄下，誰言皆有家。","城前水声苦，倏忽流万古。","莫爭城外城，城裏終闲土。"]', '诗', 'shi', '', NULL, '戰城南 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfdd5cad-a727-4f8c-a46c-fe3881ce075a', '曲江春霽', '曲江春霽', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["宿雨洗秦樹，舊花如新開。","池邊草未乾，日照人馬來。","馬蹄踏流水，漸漸成塵埃。","鴛鴦不敢下，飛繞岸東西。","此地喧仍舊，歸人亦滿街。"]', '["宿雨洗秦樹，旧花如新开。","池邊草未乾，日照人马来。","马蹄踏流水，漸漸成塵埃。","鴛鴦不敢下，飞繞岸东西。","此地喧仍旧，归人亦满街。"]', '诗', 'shi', '', NULL, '曲江春霽 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bab027f-bda8-4df8-a30b-b7ff8fa33e96', '贈先達', '贈先達', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["終南蒼翠好，未必如故山。","心期在榮名，三載居長安。","昔蒙大雅匠，勉我工五言。","業成時不重，辛苦只自憐。","皎皎機上絲，盡作秦箏弦。","貧女皆罷織，富人豈不寒。","驚風起長波，浩浩何時還？","待君當要路，一指王化源。"]', '["終南蒼翠好，未必如故山。","心期在榮名，三載居长安。","昔蒙大雅匠，勉我工五言。","業成时不重，辛苦只自怜。","皎皎機上絲，尽作秦箏弦。","貧女皆罷织，富人豈不寒。","驚风起长波，浩浩何时還？","待君當要路，一指王化源。"]', '诗', 'shi', '', NULL, '贈先達 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25778403-ff66-475e-b638-951267d6bb28', '有感', '有感', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["弓劒不自行，難引河湟思。","將軍半夜飲，十里聞歌飲。","高門幾世宅，舞袖仍新賜。","誰遣一書來，燈前問邊事。"]', '["弓劒不自行，难引河湟思。","將軍半夜饮，十里闻歌饮。","高门幾世宅，舞袖仍新賜。","誰遣一书来，灯前问邊事。"]', '诗', 'shi', '', NULL, '有感 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b4737d-01db-4c85-a19c-0c6ed5169031', '姑蘇臺', '姑蘇台', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["勾踐飲膽日，吳酒正滿杯。","笙歌入海雲，聲自姑蘇來。","西施舞初罷，侍兒整金釵。","衆女不敢妒，自比泉下泥。","越鼓聲騰騰，吳天隔塵埃。","難將甬東地，更學會稽棲。","霸跡一朝盡，草中棠梨開。"]', '["勾踐饮膽日，吳酒正满杯。","笙歌入海云，声自姑蘇来。","西施舞初罷，侍兒整金釵。","衆女不敢妒，自比泉下泥。","越鼓声腾腾，吳天隔塵埃。","难將甬东地，更学會稽棲。","霸跡一朝尽，草中棠梨开。"]', '诗', 'shi', '', NULL, '姑蘇臺 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('521c2831-e1a0-4d81-93d4-1e878caf6a3d', '豪家', '豪家', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["九陌槐葉盡，青春在豪家。","嬌鶯不出城，長宿庭上花。","高樓登夜半，已見南山多。","恩深勢自然，不是愛驕奢。"]', '["九陌槐葉尽，青春在豪家。","嬌鶯不出城，长宿庭上花。","高楼登夜半，已见南山多。","恩深勢自然，不是愛驕奢。"]', '诗', 'shi', '', NULL, '豪家 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bd746d9-90a9-4ab5-9947-494d7d9ea21b', '山中有招', '山中有招', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["朗朗山月出，塵中事由生。","人心雖不閑，九陌夜無行。","學古以求聞，有如石上耕。","齊姜早作婦，豈識閨中情。","何如此幽居，地僻人不爭。","嘉樹自昔有，茅屋因我成。","取薪不出門，采藥於前庭。","春花雖無種，枕席芙蓉馨。","君來食葵藿，天爵豈不榮。"]', '["朗朗山月出，塵中事由生。","人心雖不闲，九陌夜無行。","学古以求闻，有如石上耕。","齊姜早作婦，豈識閨中情。","何如此幽居，地僻人不爭。","嘉樹自昔有，茅屋因我成。","取薪不出门，采藥於前庭。","春花雖無種，枕席芙蓉馨。","君来食葵藿，天爵豈不榮。"]', '诗', 'shi', '', NULL, '山中有招 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deccb9c2-e5a9-4905-91aa-698ed6fe419d', '空城雀', '空城雀', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["飢啄空城上，莫近太倉粟。","一粒未充腸，却入公子腹。","且弔城上骨，幾曾害爾族。","不聞莊辛語，今日寒蕪綠。"]', '["飢啄空城上，莫近太倉粟。","一粒未充腸，却入公子腹。","且弔城上骨，幾曾害爾族。","不闻莊辛語，今日寒蕪綠。"]', '诗', 'shi', '', NULL, '空城雀 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad7b285-b722-49e7-9b21-0f3cd4f1375f', '馮叟居', '馮叟居', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["天作馮叟居，山僧尚嫌僻。","開門因兩樹，結宇倚翠壁。","溪南有微徑，時遇採芝客。","往往白雲生，對面千里隔。","機忘若僮僕，常與猨鳥劇。","曬藥上小峰，庭深無日色。","自忘歸鄉里，不見新舊戚。","纍纍子孫墓，秋風吹古柏。"]', '["天作馮叟居，山僧尚嫌僻。","开门因兩樹，結宇倚翠壁。","溪南有微徑，时遇採芝客。","往往白云生，对面千里隔。","機忘若僮僕，常與猨鸟劇。","曬藥上小峰，庭深無日色。","自忘归乡里，不见新旧戚。","纍纍子孫墓，秋风吹古柏。"]', '诗', 'shi', '', NULL, '馮叟居 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36790537-76ac-4af5-9395-2886e67ece02', '醒後', '醒後', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["醉臥芳草間，酒醒日落後。","壺觴半傾覆，客去應已久。","不記折花時，何得花在手。"]', '["醉臥芳草间，酒醒日落後。","壺觴半傾覆，客去應已久。","不記折花时，何得花在手。"]', '诗', 'shi', '', NULL, '醒後 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('305a88a0-311c-42b3-b51b-7617699d54a9', '棄婦', '棄婦', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["回車在門前，欲上心更悲。","路傍見花發，似妾初嫁時。","養蠶已成繭，織素猶在機。","新人應笑此，何如畫蛾眉。","昨日惜紅顏，今日畏老遲。","良媒去不遠，此恨今告誰。"]', '["回车在门前，欲上心更悲。","路傍见花發，似妾初嫁时。","養蠶已成繭，织素猶在機。","新人應笑此，何如畫蛾眉。","昨日惜紅顏，今日畏老遲。","良媒去不远，此恨今告誰。"]', '诗', 'shi', '', NULL, '棄婦 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad765a79-3c31-49ca-9e63-6bebc466ecd3', '送李殷遊邊', '送李殷游邊', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["十年夢相識，一覯俄遠別。","征駕在我傍，草草意難說。","君居洞庭日，詩句滿魏闕。","如何萬里來，青桂看人折。","行裝不及備，西去偶然訣。","孟夏出都門，紅塵客衣熱。","荒城見羊馬，野館具薇蕨。","邊境漸無虞，旅宿常待月。","西園置酒地，日夕簪裾列。","壯志安可留，槐花樽前發。"]', '["十年梦相識，一覯俄远別。","征駕在我傍，草草意难说。","君居洞庭日，诗句满魏闕。","如何万里来，青桂看人折。","行裝不及備，西去偶然訣。","孟夏出都门，紅塵客衣熱。","荒城见羊马，野館具薇蕨。","邊境漸無虞，旅宿常待月。","西园置酒地，日夕簪裾列。","壯志安可留，槐花樽前發。"]', '诗', 'shi', '', NULL, '送李殷遊邊 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3988b32b-df07-4052-b346-ea6d92828eda', '江村', '江村', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["江水灌稻田，饑年稻亦熟。","舟中愛桑麻，日午因成宿。","相承幾十代，居止連茅屋。","四鄰不相離，安肯去骨肉。","書生說太苦，客路常在目。","縱使富貴還，交親幾墳綠。"]', '["江水灌稻田，饑年稻亦熟。","舟中愛桑麻，日午因成宿。","相承幾十代，居止連茅屋。","四鄰不相離，安肯去骨肉。","书生说太苦，客路常在目。","縱使富貴還，交親幾墳綠。"]', '诗', 'shi', '', NULL, '江村 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5baaa588-8ec1-4b18-8dbd-efa7f18a4d88', '出門', '出门', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["出門羨他人，奔走如得塗。","翻思他人意，與我或不殊。","以茲聊自安，默默行九衢。","生計逐羸馬，每出似移居。","客從我鄉來，但得鄰里書。","田園幾換主，夢歸猶荷鋤。","進猶希萬一，退復何所如。","況今闢公道，安得不躊躇。"]', '["出门羨他人，奔走如得塗。","翻思他人意，與我或不殊。","以茲聊自安，默默行九衢。","生計逐羸马，每出似移居。","客從我乡来，但得鄰里书。","田园幾換主，梦归猶荷鋤。","進猶希万一，退复何所如。","況今闢公道，安得不躊躇。"]', '诗', 'shi', '', NULL, '出門 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c392f188-f3c9-4464-b0c9-d3415f222f45', '別道者', '別道者', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["自君入城市，北邙無新墳。","始信壺中藥，不落白楊根。","如何忽告歸，蕣華還笑人。","玉笙無遺音，悵望緱嶺雲。"]', '["自君入城市，北邙無新墳。","始信壺中藥，不落白楊根。","如何忽告归，蕣华還笑人。","玉笙無遺音，悵望緱嶺云。"]', '诗', 'shi', '', NULL, '別道者 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb4c785a-b7c0-4e1a-9cdc-ca738ba95795', '蘭昌宮', '蘭昌宮', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["宮蘭非瑤草，安得春長在。","迴首春又歸，翠華不能待。","悲風生輦路，山川寂已晦。","邊恨在行人，行人無盡歲。"]', '["宮蘭非瑤草，安得春长在。","迴首春又归，翠华不能待。","悲风生輦路，山川寂已晦。","邊恨在行人，行人無尽歲。"]', '诗', 'shi', '', NULL, '蘭昌宮 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed79dc3e-b396-4b0c-8ce7-aaf690058093', '送友人擢第東歸', '送友人擢第东归', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["同家楚天南，相識秦雲西。","古來懸弧義，豈顧子與妻。","攜手踐名場，正遇公道開。","君榮我雖黜，感恩同所懷。","有馬不復羸，有奴不復飢。","灞岸秋草綠，却是還家時。","青門一瓢空，分手去遲遲。","期君轍未平，我車繼東歸。"]', '["同家楚天南，相識秦云西。","古来懸弧義，豈顧子與妻。","携手踐名場，正遇公道开。","君榮我雖黜，感恩同所懷。","有马不复羸，有奴不复飢。","灞岸秋草綠，却是還家时。","青门一瓢空，分手去遲遲。","期君轍未平，我车繼东归。"]', '诗', 'shi', '', NULL, '送友人擢第東歸 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ddbd2f-b723-473a-9fce-8579256ee59a', '久客', '久客', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["久客心易足，主人有餘力。","如何昨宵夢，到曉家山色。","南音入誰耳，曲盡頭自白。"]', '["久客心易足，主人有餘力。","如何昨宵梦，到晓家山色。","南音入誰耳，曲尽头自白。"]', '诗', 'shi', '', NULL, '久客 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32846028-5b49-405f-a951-2acd67709f3b', '秋夕', '秋夕', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["促織燈下吟，燈光冷於水。","鄉魂坐中去，倚壁身如死。","求名爲骨肉，骨肉萬餘里。","富貴在何時，離別今如此。","出門長歎息，月白西風起。"]', '["促织灯下吟，灯光冷於水。","乡魂坐中去，倚壁身如死。","求名爲骨肉，骨肉万餘里。","富貴在何时，離別今如此。","出门长歎息，月白西风起。"]', '诗', 'shi', '', NULL, '秋夕 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfc36dd0-031e-46ed-bbe1-06645f7fcf58', '效陶', '效陶', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["兩曜無停馭，蓬壺應有墓。","何況北邙山，只近市朝路。","大恢生死網，飛走無逃處。","白髮忽已新，紅顏豈如故。","我有杯中物，可以消萬慮。","醉舞日婆娑，誰能記朝暮。","如求神仙藥，階下亦種黍。","但使長兀然，始見天地祖。"]', '["兩曜無停馭，蓬壺應有墓。","何況北邙山，只近市朝路。","大恢生死網，飞走無逃处。","白髮忽已新，紅顏豈如故。","我有杯中物，可以消万慮。","醉舞日婆娑，誰能記朝暮。","如求神仙藥，階下亦種黍。","但使长兀然，始见天地祖。"]', '诗', 'shi', '', NULL, '效陶 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b05c52b8-40ce-494b-b274-f807755a312f', '長門怨', '长门怨', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["御泉長繞鳳皇[樓]，只是恩波別處流。","閑揲舞衣歸未得，夜來砧杵六宮秋。"]', '["御泉长繞鳳皇[楼]，只是恩波別处流。","闲揲舞衣归未得，夜来砧杵六宮秋。"]', '诗', 'shi', '', NULL, '長門怨 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65f473e2-2545-4732-8a4a-56a784f93382', '苦寒行', '苦寒行', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["嚴寒動八荒，刺刺無休時。","陽烏不自暖，雪壓扶桑枝。","歲暮寒益壯，青春安得歸。","朔鴈到南海，越禽何處飛。","誰言貧士歎，不爲身無衣。"]', '["嚴寒动八荒，刺刺無休时。","陽烏不自暖，雪壓扶桑枝。","歲暮寒益壯，青春安得归。","朔鴈到南海，越禽何处飞。","誰言貧士歎，不爲身無衣。"]', '诗', 'shi', '', NULL, '苦寒行 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d844560a-e0a4-4e09-8653-6de66366283d', '琪樹下因吟六韻呈先達者', '琪樹下因吟六韻呈先達者', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["舉世愛嘉樹，此樹何人識。","清秋遠山意，偶向亭際得。","奇柯交若鬬，珍葉密如織。","塵中尚青蔥，更想塵外色。","所宜巢三鳥，影入瑤池碧。","移根豈無時，一問紫煙客。"]', '["舉世愛嘉樹，此樹何人識。","清秋远山意，偶向亭際得。","奇柯交若鬬，珍葉密如织。","塵中尚青蔥，更想塵外色。","所宜巢三鸟，影入瑤池碧。","移根豈無时，一问紫煙客。"]', '诗', 'shi', '', NULL, '琪樹下因吟六韻呈先達者 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2a87e64-3c43-4b01-a56a-02241ec5526a', '送人登第東歸', '送人登第东归', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["學古既到古，反求鑒者難。","見詩未識君，疑生建安前。","海畔豈無家，終難成故山。","得失雖由命，世途多險艱。","我皇追古風，文柄付大賢。","此時如爲君，果在甲科間。","晚達多早貴，舉世咸爲然。","一夕顏却少，雖病心且安。","所居似清明，冷竈起新煙。","高情懶行樂，花盛僕馬前。","歸程不淹留，指期到田園。","香醪四鄰熟，霜橘千株繁。","肯憶長安夜，論詩風雪寒。"]', '["学古既到古，反求鑒者难。","见诗未識君，疑生建安前。","海畔豈無家，終难成故山。","得失雖由命，世途多險艱。","我皇追古风，文柄付大賢。","此时如爲君，果在甲科间。","晚達多早貴，舉世咸爲然。","一夕顏却少，雖病心且安。","所居似清明，冷竈起新煙。","高情懶行乐，花盛僕马前。","归程不淹留，指期到田园。","香醪四鄰熟，霜橘千株繁。","肯憶长安夜，論诗风雪寒。"]', '诗', 'shi', '', NULL, '送人登第東歸 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58b20ce9-14eb-44a2-b124-1ec78cd4302a', '賈客詞', '賈客词', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["賈客燈下起，猶言發已遲。","高山有疾路，暗行終不疑。","寇盜伏其路，猛獸來相追。","金玉四散去，空囊委路岐。","揚州有大宅，白骨無地歸。","少婦當此日，對鏡弄花枝。"]', '["賈客灯下起，猶言發已遲。","高山有疾路，暗行終不疑。","寇盜伏其路，猛獸来相追。","金玉四散去，空囊委路岐。","揚州有大宅，白骨無地归。","少婦當此日，对镜弄花枝。"]', '诗', 'shi', '', NULL, '賈客詞 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0416de29-dfaf-4909-8c21-db7ff37416ee', '塞下曲', '塞下曲', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["勒兵遼水邊，風急卷旌旃。","絕塞陰無草，平沙去盡天。","下營看斗建，傳號信狼煙。","聖代書青史，當時破虜年。"]', '["勒兵遼水邊，风急卷旌旃。","絕塞陰無草，平沙去尽天。","下營看斗建，傳號信狼煙。","聖代书青史，當时破虜年。"]', '诗', 'shi', '', NULL, '塞下曲 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8ec33b3-10ec-4424-b073-88380cf5223b', '春夜二首 一', '春夜二首 一', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["一別杜陵歸未期，祗憑魂夢接親知。","近來欲睡兼難睡，夜夜夜深聞子規。"]', '["一別杜陵归未期，祗憑魂梦接親知。","近来欲睡兼难睡，夜夜夜深闻子規。"]', '诗', 'shi', '', NULL, '春夜二首 一 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ede444-7994-4793-ad18-26d961b2c0ee', '春夜二首 二', '春夜二首 二', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["幾歲干戈阻路岐，憶山心切與心違。","時難何處披衷抱，日日日斜空醉歸。"]', '["幾歲干戈阻路岐，憶山心切與心違。","时难何处披衷抱，日日日斜空醉归。"]', '诗', 'shi', '', NULL, '春夜二首 二 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a198d72-ace4-4025-9d6d-88b1d069f4d0', '郪中感懷', '郪中感懷', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["頃年曾住此中來，今日重遊事可哀。","憶得幾家歡宴處，家家家業盡成灰。"]', '["頃年曾住此中来，今日重游事可哀。","憶得幾家歡宴处，家家家業尽成灰。"]', '诗', 'shi', '', NULL, '郪中感懷 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2ad3d6f-9735-4c14-ad89-1b5bfd8a12d1', '曉登迎春閣', '晓登迎春閣', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["未櫛凭欄眺錦城，煙籠萬井二江明。","香風滿閣花滿樹，樹樹樹梢啼曉鶯。"]', '["未櫛凭欄眺錦城，煙籠万井二江明。","香风满閣花满樹，樹樹樹梢啼晓鶯。"]', '诗', 'shi', '', NULL, '曉登迎春閣 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8bb4188-232d-49fc-9cc2-c201d4e8733b', '白髭', '白髭', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["到處逢人求至藥，幾回染了又成絲。","素絲易染髭難染，墨翟當年合泣髭。"]', '["到处逢人求至藥，幾回染了又成絲。","素絲易染髭难染，墨翟當年合泣髭。"]', '诗', 'shi', '', NULL, '白髭 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16397e7d-cf17-436c-92fa-a006f1fc0f67', '送盧使君赴夔州', '送盧使君赴夔州', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["鐃管隨征斾，高秋上遠巴。","白波連霧雨，青壁斷蒹葭。","凭几雙瞳靜，登樓萬井斜。","政成知俗變，當應畫輪車。"]', '["鐃管隨征斾，高秋上远巴。","白波連霧雨，青壁斷蒹葭。","凭几雙瞳静，登楼万井斜。","政成知俗变，當應畫輪车。"]', '诗', 'shi', '', NULL, '送盧使君赴夔州 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c024508d-e680-411f-9b92-4c67ae03d540', '望月', '望月', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["清秋新霽與君同，江上高樓倚碧空。","酒盡露零賓客散，更更更漏月明中。"]', '["清秋新霽與君同，江上高楼倚碧空。","酒尽露零賓客散，更更更漏月明中。"]', '诗', 'shi', '', NULL, '望月 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('800a029c-f786-4810-b92e-93d23bab524b', '古意', '古意', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["蒲帆出浦去，但見浦邊樹。","不如馬行郎，馬跡猶在路。","大舟不相載，買宅令委住。","莫道留金多，本非愛郎富。"]', '["蒲帆出浦去，但见浦邊樹。","不如马行郎，马跡猶在路。","大舟不相載，買宅令委住。","莫道留金多，本非愛郎富。"]', '诗', 'shi', '', NULL, '古意 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d95da435-feba-473a-946a-60375ca8d581', '長洲懷古', '长洲懷古', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["野燒原空盡荻灰，吳王此地有樓臺。","千年事往人何在，半夜月明潮自來。","白鳥影從江樹沒，清猨聲入楚雲哀。","停車日晚薦蘋藻，風靜寒塘花正開。"]', '["野燒原空尽荻灰，吳王此地有楼台。","千年事往人何在，半夜月明潮自来。","白鸟影從江樹沒，清猨声入楚云哀。","停车日晚薦蘋藻，风静寒塘花正开。"]', '诗', 'shi', '', NULL, '長洲懷古 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edb91824-6e13-4d57-b427-807cd4dda923', '經煬帝行宮', '經煬帝行宮', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["此地曾經翠輦過，浮雲流水竟如何。","香銷南國美人盡，怨入東風芳草多。","殘柳宮前空露葉，夕陽川上浩煙波。","行人遙起廣陵思，古渡月明聞棹歌。"]', '["此地曾經翠輦過，浮云流水竟如何。","香銷南国美人尽，怨入东风芳草多。","殘柳宮前空露葉，夕陽川上浩煙波。","行人遙起廣陵思，古渡月明闻棹歌。"]', '诗', 'shi', '', NULL, '經煬帝行宮 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16637f37-8453-4a11-8bcf-035d20c838b0', '春日遊嘉陵江', '春日游嘉陵江', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["獨泛扁舟映綠楊，嘉陵江水色蒼蒼。","行看芳草故鄉遠，坐對落花春日長。","曲岸危檣移渡影，暮天栖鳥入山光。","今來誰識東歸意，把酒閑吟思洛陽。"]', '["独泛扁舟映綠楊，嘉陵江水色蒼蒼。","行看芳草故乡远，坐对落花春日长。","曲岸危檣移渡影，暮天栖鸟入山光。","今来誰識东归意，把酒闲吟思洛陽。"]', '诗', 'shi', '', NULL, '春日遊嘉陵江 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('663a6285-6551-46c9-ad13-df3f5669e092', '秋日山齋書懷', '秋日山斋书懷', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["啓戶清風枕簟幽，蟲絲吹落挂簾鉤。","蟬吟高樹雨初霽，人憶故鄉山正秋。","浩渺蒹葭連夕照，蕭疎楊柳隔沙洲。","空將方寸荷知己，身寄煙蘿恩未酬。"]', '["啓戶清风枕簟幽，蟲絲吹落挂簾鉤。","蟬吟高樹雨初霽，人憶故乡山正秋。","浩渺蒹葭連夕照，蕭疎楊柳隔沙洲。","空將方寸荷知己，身寄煙蘿恩未酬。"]', '诗', 'shi', '', NULL, '秋日山齋書懷 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17b1eba6-0e49-4d50-9eb0-9bcafe5da674', '晚秋洛陽客舍', '晚秋洛陽客舍', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["清洛平分兩岸沙，沙邊水色近人家。","隋朝古陌銅駝柳，石氏荒原金谷花。","庭葉霜濃悲遠客，宮城日晚度寒鵶。","未成歸計關河阻，空望白雲鄉路賒。"]', '["清洛平分兩岸沙，沙邊水色近人家。","隋朝古陌銅駝柳，石氏荒原金谷花。","庭葉霜濃悲远客，宮城日晚度寒鵶。","未成归計关河阻，空望白云乡路賒。"]', '诗', 'shi', '', NULL, '晚秋洛陽客舍 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea69288-0580-4068-8749-7197124700bc', '深愁喜友人至', '深愁喜友人至', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["不避驅羸道路長，青山同喜惜年光。","燈前話舊堦草夜，月下醉吟谿樹霜。","落葉已經寒燒盡，衡門猶對古城荒。","此身未遂歸休計，一半生涯寄岳陽。"]', '["不避驱羸道路长，青山同喜惜年光。","灯前話旧堦草夜，月下醉吟谿樹霜。","落葉已經寒燒尽，衡门猶对古城荒。","此身未遂归休計，一半生涯寄岳陽。"]', '诗', 'shi', '', NULL, '深愁喜友人至 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f059d478-99e8-47de-b28d-8f0630a3b33a', '秋日望西陽', '秋日望西陽', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["古木蒼苔墜幾層，行人一望旅情增。","太行山下黃河水，銅雀臺西武帝陵。","風入蒹葭秋色動，雨餘楊柳暮煙凝。","野花似泣紅妝淚，寒露滿枝枝不勝。"]', '["古木蒼苔墜幾層，行人一望旅情增。","太行山下黄河水，銅雀台西武帝陵。","风入蒹葭秋色动，雨餘楊柳暮煙凝。","野花似泣紅妝泪，寒露满枝枝不勝。"]', '诗', 'shi', '', NULL, '秋日望西陽 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a84b261-440a-4fae-905d-42f970090fde', '鄴都懷古', '鄴都懷古', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["昔時霸業何蕭索，古木唯多鳥雀聲。","芳草自生宮殿處，牧童誰識帝王城。","殘春楊柳長川迥，落日蒹葭遠水平。","一望青山便惆悵，西陵無主月空明。"]', '["昔时霸業何蕭索，古木唯多鸟雀声。","芳草自生宮殿处，牧童誰識帝王城。","殘春楊柳长川迥，落日蒹葭远水平。","一望青山便惆悵，西陵無主月空明。"]', '诗', 'shi', '', NULL, '鄴都懷古 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e17dca08-9b9a-42b4-ba1c-5e1378a6bf8b', '題龍門僧房', '題龙门僧房', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["靜室遙臨伊水東，寂寥誰與此身同。","禹門山色度寒磬，蕭寺竹聲來晚風。","僧宿石龕殘雪在，鴈歸沙渚夕陽空。","偶將心地問高士，坐指浮生一夢中。"]', '["静室遙臨伊水东，寂寥誰與此身同。","禹门山色度寒磬，蕭寺竹声来晚风。","僧宿石龕殘雪在，鴈归沙渚夕陽空。","偶將心地问高士，坐指浮生一梦中。"]', '诗', 'shi', '', NULL, '題龍門僧房 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f9d7a4f-c1f5-44d4-8ee1-7c03a35d1602', '秋夕山齋即事', '秋夕山斋即事', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["衡門無事閉蒼苔，籬下蕭疎野菊開。","半夜秋風江色動，滿山寒葉雨聲來。","鴈飛關塞霜初落，書寄鄉閭人未迴。","獨坐高窗此時節，一彈瑤瑟自成哀。"]', '["衡门無事閉蒼苔，籬下蕭疎野菊开。","半夜秋风江色动，满山寒葉雨声来。","鴈飞关塞霜初落，书寄乡閭人未迴。","独坐高窗此时節，一彈瑤瑟自成哀。"]', '诗', 'shi', '', NULL, '秋夕山齋即事 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b115bf0-783b-4795-bd92-323f987a26c4', '江行書事', '江行书事', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["遠渚蒹葭覆綠苔，姑蘇南望思裴徊。","空江獨樹楚山背，暮雨一舟吳苑來。","人度深秋風葉落，鳥飛殘照水煙開。","寒潮欲上泛萍藻，寄薦三閭情自哀。"]', '["远渚蒹葭覆綠苔，姑蘇南望思裴徊。","空江独樹楚山背，暮雨一舟吳苑来。","人度深秋风葉落，鸟飞殘照水煙开。","寒潮欲上泛萍藻，寄薦三閭情自哀。"]', '诗', 'shi', '', NULL, '江行書事 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9007b412-5f1b-4f41-9c4b-6b4fa8653447', '過鑄鼎原', '過鑄鼎原', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["黃帝修真萬國朝，鼎成龍駕上丹霄。","天風乍起鶴聲遠，海霧漸深龍節遙。","仙界日長青鳥度，御衣香散紫霞飄。","唯留古跡寒原在，碧水蒼蒼空寂寥。"]', '["黄帝修真万国朝，鼎成龙駕上丹霄。","天风乍起鹤声远，海霧漸深龙節遙。","仙界日长青鸟度，御衣香散紫霞飄。","唯留古跡寒原在，碧水蒼蒼空寂寥。"]', '诗', 'shi', '', NULL, '過鑄鼎原 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('895de138-a7aa-422f-bb58-e0ea4c8b2822', '秋日寓懷', '秋日寓懷', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["海上生涯一釣舟，偶因名利事淹留。","旅塗誰見客青眼，故國幾多人白頭。","霽色滿川明水驛，蟬聲落日隱城樓。","如何未盡此行役，西入潼關雲木秋。"]', '["海上生涯一釣舟，偶因名利事淹留。","旅塗誰见客青眼，故国幾多人白头。","霽色满川明水驛，蟬声落日隐城楼。","如何未尽此行役，西入潼关云木秋。"]', '诗', 'shi', '', NULL, '秋日寓懷 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('916788ba-8281-40c5-ab97-d738857f24fe', '江城晚望', '江城晚望', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["一望江城思有餘，遙分野逕入樵漁。","青山經雨菊花盡，白鳥下灘蘆葉疎。","靜聽潮聲寒木杪，遠看風色暮帆舒。","秋期又涉潼關路，不得年年向此居。"]', '["一望江城思有餘，遙分野逕入樵漁。","青山經雨菊花尽，白鸟下灘蘆葉疎。","静听潮声寒木杪，远看风色暮帆舒。","秋期又涉潼关路，不得年年向此居。"]', '诗', 'shi', '', NULL, '江城晚望 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9c217d8-518d-47bb-b6c5-85a0875312e3', '宿蒼谿館', '宿蒼谿館', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["孤館門開對碧岑，竹窗燈下聽猨吟。","巴山夜雨別離夢，秦塞舊山迢遰心。","滿地莓苔生近水，幾株楊柳自成陰。","空思知己隔雲嶺，鄉路獨歸春草深。"]', '["孤館门开对碧岑，竹窗灯下听猨吟。","巴山夜雨別離梦，秦塞旧山迢遰心。","满地莓苔生近水，幾株楊柳自成陰。","空思知己隔云嶺，乡路独归春草深。"]', '诗', 'shi', '', NULL, '宿蒼谿館 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('886c363d-9afd-4be4-9fc3-d33348dd98a2', '題王母廟', '題王母廟', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["寂寥珠翠想遺聲，門掩煙微水殿清。","拂曙紫霞生古壁，何年絳節下層城。","鶴歸遼海春光晚，花落閑堦夕雨晴。","武帝無名在仙籍，玉壇星月夜空明。"]', '["寂寥珠翠想遺声，门掩煙微水殿清。","拂曙紫霞生古壁，何年絳節下層城。","鹤归遼海春光晚，花落闲堦夕雨晴。","武帝無名在仙籍，玉壇星月夜空明。"]', '诗', 'shi', '', NULL, '題王母廟 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b49902b2-4f1f-49cb-86df-deb575a3cf6a', '留別復本修古二上人', '留別复本修古二上人', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["二遠相知是昔年，此身長寄禮香煙。","綠蕪風晚水邊寺，清磬月高林下禪。","臺殿虛窗山翠入，梧桐疎葉露光懸。","西峰話別又須去，終日關山在馬前。"]', '["二远相知是昔年，此身长寄禮香煙。","綠蕪风晚水邊寺，清磬月高林下禪。","台殿虛窗山翠入，梧桐疎葉露光懸。","西峰話別又須去，終日关山在马前。"]', '诗', 'shi', '', NULL, '留別復本修古二上人 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48d27ed5-36bd-4a1b-aef6-6f71469a3d20', '邊思', '邊思', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["漢將邊方背轆轤，受降城北是單于。","黃河晚凍雪風急，野火遠燒山木枯。","偷號甲兵衝塞色，銜枚戰馬踏寒蕪。","蛾眉一沒空留怨，青塚月明啼夜烏。"]', '["漢將邊方背轆轤，受降城北是單于。","黄河晚凍雪风急，野火远燒山木枯。","偷號甲兵衝塞色，銜枚戰马踏寒蕪。","蛾眉一沒空留怨，青塚月明啼夜烏。"]', '诗', 'shi', '', NULL, '邊思 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7cf0c86-b7c0-4158-9ccb-86949f401661', '登龍門敬善寺閣', '登龙门敬善寺閣', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["獨步危梯入杳冥，天風瀟灑拂簷楹。","禹門煙樹正春色，少室雲屏向晚晴。","花落院深清禁閉，水分川闊綠蕪平。","瑣窗朱檻同仙界，半夜緱山有鶴聲。"]', '["独步危梯入杳冥，天风瀟灑拂簷楹。","禹门煙樹正春色，少室云屏向晚晴。","花落院深清禁閉，水分川闊綠蕪平。","瑣窗朱檻同仙界，半夜緱山有鹤声。"]', '诗', 'shi', '', NULL, '登龍門敬善寺閣 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a72b51f2-6bbf-493d-881f-9c1e3fe72638', '題王校書山齋', '題王校书山斋', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["猨鳥無聲晝掩扉，寒原隔水到人稀。","雲晴古木月初上，雪滿空庭鶴未歸。","藥囿地連山色近，樵家路入樹煙微。","栖遲慣得滄浪思，雲閣還應夢釣磯。"]', '["猨鸟無声晝掩扉，寒原隔水到人稀。","云晴古木月初上，雪满空庭鹤未归。","藥囿地連山色近，樵家路入樹煙微。","栖遲慣得滄浪思，云閣還應梦釣磯。"]', '诗', 'shi', '', NULL, '題王校書山齋 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75cc1819-60f3-4570-aa63-2eccd4250d72', '浙江晚渡懷古', '浙江晚渡懷古', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["蟬噪秋風滿古隄，荻花寒渡思萋萋。","潮聲歸海鳥初下，草色連江人自迷。","碧落晴分平楚外，青山晚出穆陵西。","此來一見垂綸者，卻憶舊居明月溪。"]', '["蟬噪秋风满古隄，荻花寒渡思萋萋。","潮声归海鸟初下，草色連江人自迷。","碧落晴分平楚外，青山晚出穆陵西。","此来一见垂綸者，卻憶旧居明月溪。"]', '诗', 'shi', '', NULL, '浙江晚渡懷古 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58209009-f49f-4511-baad-0ead7cfa8e94', '及第後宴曲江', '及第後宴曲江', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["及第新春選勝遊，杏園初宴曲江頭。","紫毫粉壁題仙籍，柳色簫聲拂御樓。","霽景露光明遠岸，晚空山翠墜芳洲。","歸時不省花間醉，綺陌香車似水流。"]', '["及第新春選勝游，杏园初宴曲江头。","紫毫粉壁題仙籍，柳色簫声拂御楼。","霽景露光明远岸，晚空山翠墜芳洲。","归时不省花间醉，綺陌香车似水流。"]', '诗', 'shi', '', NULL, '及第後宴曲江 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4919cee-b309-43f0-a6fc-7be936c8f532', '秋日山寺懷友人', '秋日山寺懷友人', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["蕭寺樓臺對夕陰，淡煙疎磬散空林。","風生寒渚白蘋動，霜落秋山黃葉深。","雲盡獨看晴塞鴈，月明遙聽遠村砧。","相思不見又經歲，坐向松窗彈玉琴。"]', '["蕭寺楼台对夕陰，淡煙疎磬散空林。","风生寒渚白蘋动，霜落秋山黄葉深。","云尽独看晴塞鴈，月明遙听远村砧。","相思不见又經歲，坐向松窗彈玉琴。"]', '诗', 'shi', '', NULL, '秋日山寺懷友人 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('637deb68-191b-4899-89ff-8c229c0bb9b8', '八月十五日夜玩月', '八月十五日夜玩月', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["中秋朗月靜天河，烏鵲南飛客恨多。","寒色滿窗明枕簟，清光凝露拂煙蘿。","桂枝斜漢流靈魄，蘋葉微風動細波。","此夜空亭聞木落，蒹葭霜磧鴈初過。"]', '["中秋朗月静天河，烏鵲南飞客恨多。","寒色满窗明枕簟，清光凝露拂煙蘿。","桂枝斜漢流靈魄，蘋葉微风动細波。","此夜空亭闻木落，蒹葭霜磧鴈初過。"]', '诗', 'shi', '', NULL, '八月十五日夜玩月 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cf0bbbe-bf85-4faa-8513-b7b8481b8d8a', '晚春宿僧院', '晚春宿僧院', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["蕭寺春風正落花，淹留數宿惠休家。","碧空雲盡磬聲遠，清夜月高窗影斜。","白日閑吟爲道侶，青山遙指是生涯。","微微一點寒燈在，鄉夢不成聞曙鵶。"]', '["蕭寺春风正落花，淹留數宿惠休家。","碧空云尽磬声远，清夜月高窗影斜。","白日闲吟爲道侶，青山遙指是生涯。","微微一点寒灯在，乡梦不成闻曙鵶。"]', '诗', 'shi', '', NULL, '晚春宿僧院 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d855ec3-c8f5-489e-a562-1047a415e3b9', '懷汶陽兄弟', '懷汶陽兄弟', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["回看雲嶺思茫茫，幾處關河隔汶陽。","書信經年鄉國遠，弟兄無力海田荒。","天高霜月砧聲苦，風滿寒林木葉黃。","終日路岐歸未得，秋來空羨鴈成行。"]', '["回看云嶺思茫茫，幾处关河隔汶陽。","书信經年乡国远，弟兄無力海田荒。","天高霜月砧声苦，风满寒林木葉黄。","終日路岐归未得，秋来空羨鴈成行。"]', '诗', 'shi', '', NULL, '懷汶陽兄弟 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c679c442-919c-43b0-91c7-025fdbc5c189', '題天宮寺閣', '題天宮寺閣', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["丹闕侵霄壯復危，排空霞影動簷扉。","城連伊水禹門近，煙隔上陽宮樹微。","天歛暮雲殘雨歇，路穿春草一僧歸。","此來閑望更何有，無限清風生客衣。"]', '["丹闕侵霄壯复危，排空霞影动簷扉。","城連伊水禹门近，煙隔上陽宮樹微。","天歛暮云殘雨歇，路穿春草一僧归。","此来闲望更何有，無限清风生客衣。"]', '诗', 'shi', '', NULL, '題天宮寺閣 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9609f167-73e7-4c6a-94b2-d73c6e90f919', '遊上方石窟寺', '游上方石窟寺', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["苔徑縈迴景漸分，翛然空界靜埃氛。","一聲疎磬過寒水，半壁危樓隱白雲。","雪下石龕僧在定，日西山木鳥成羣。","幾來吟嘯立朱檻，風起天香處處聞。"]', '["苔徑縈迴景漸分，翛然空界静埃氛。","一声疎磬過寒水，半壁危楼隐白云。","雪下石龕僧在定，日西山木鸟成羣。","幾来吟嘯立朱檻，风起天香处处闻。"]', '诗', 'shi', '', NULL, '遊上方石窟寺 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c2deaec-0853-40d9-9183-bd2556facb38', '懷江南友人', '懷江南友人', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["久絕音書隔塞塵，路岐誰與子相親。","愁中獨坐秦城夜，別後幾經吳苑春。","湘岸風來吹綠綺，海門潮上沒青蘋。","空勞兩地望明月，多感斷蓬千里身。"]', '["久絕音书隔塞塵，路岐誰與子相親。","愁中独坐秦城夜，別後幾經吳苑春。","湘岸风来吹綠綺，海门潮上沒青蘋。","空勞兩地望明月，多感斷蓬千里身。"]', '诗', 'shi', '', NULL, '懷江南友人 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('538bb982-362a-4714-a1ed-acd5e5f6d8e9', '題敬亭山廟', '題敬亭山廟', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["森森古木列巖隈，迥壓寒原霽色開。","雲雨只從山上起，風雷多向廟中來。","三江入海聲長在，雙鶴啼天影未迴。","花落空庭春晝晚，石牀松殿滿青苔。"]', '["森森古木列巖隈，迥壓寒原霽色开。","云雨只從山上起，风雷多向廟中来。","三江入海声长在，雙鹤啼天影未迴。","花落空庭春晝晚，石牀松殿满青苔。"]', '诗', 'shi', '', NULL, '題敬亭山廟 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b5bb571-59a6-4af0-96a6-fbde62938f02', '經麻姑山', '經麻姑山', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["麻姑此地鍊神丹，寂寞煙霞古竈殘。","一自仙娥歸碧落，幾年春雨洗紅蘭。","帆飛震澤秋江遠，雨過陵陽晚樹寒。","山頂白雲千萬片，時聞鸞鶴下仙壇。"]', '["麻姑此地鍊神丹，寂寞煙霞古竈殘。","一自仙娥归碧落，幾年春雨洗紅蘭。","帆飞震澤秋江远，雨過陵陽晚樹寒。","山頂白云千万片，时闻鸾鹤下仙壇。"]', '诗', 'shi', '', NULL, '經麻姑山 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee292b05-f9de-4ade-bce9-48cffb729015', '對殘春', '对殘春', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["楊花漠漠暗長隄，春盡人愁鳥又啼。","鬢髪近來生處白，家園幾向夢中迷。","霏微遠樹荒郊外，牢落空城夕照西。","唯有年光堪自惜，不勝煙草日萋萋。"]', '["楊花漠漠暗长隄，春尽人愁鸟又啼。","鬢髪近来生处白，家园幾向梦中迷。","霏微远樹荒郊外，牢落空城夕照西。","唯有年光堪自惜，不勝煙草日萋萋。"]', '诗', 'shi', '', NULL, '對殘春 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88981c0f-7080-4470-a582-20b3e4c85cc5', '過滄浪峽', '過滄浪峽', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["山疊雲重一徑幽，蒼苔古石瀨清流。","出巖樹色見來靜，落澗泉聲長自秋。","遠入虛明思白帝，寒生浩景想滄洲。","如何地近東西路，馬足車輪不暫留。"]', '["山叠云重一徑幽，蒼苔古石瀨清流。","出巖樹色见来静，落澗泉声长自秋。","远入虛明思白帝，寒生浩景想滄洲。","如何地近东西路，马足车輪不暫留。"]', '诗', 'shi', '', NULL, '過滄浪峽 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('084b2a05-68f6-427e-9b76-cea456694c6b', '經過建業', '經過建業', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["六代興衰曾此地，西風露泣白蘋花。","煙波浩渺空亡國，楊柳蕭條有幾家。","楚塞秋光晴入樹，浙江殘雨晚生霞。","淒涼處處漁樵路，鳥去人歸山影斜。"]', '["六代兴衰曾此地，西风露泣白蘋花。","煙波浩渺空亡国，楊柳蕭條有幾家。","楚塞秋光晴入樹，浙江殘雨晚生霞。","淒涼处处漁樵路，鸟去人归山影斜。"]', '诗', 'shi', '', NULL, '經過建業 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcdfb30a-59fe-4ea0-8bcb-40f14425007a', '贈道者', '贈道者', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["真趣淡然居物外，忘機多是隱天台。","停燈深夜看仙籙，拂石高秋坐釣臺。","賣藥故人湘水別，入簷栖鳥舊山來。","無因朝市知名姓，地僻衡門對嶽開。"]', '["真趣淡然居物外，忘機多是隐天台。","停灯深夜看仙籙，拂石高秋坐釣台。","賣藥故人湘水別，入簷栖鸟旧山来。","無因朝市知名姓，地僻衡门对嶽开。"]', '诗', 'shi', '', NULL, '贈道者 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c3de870-4a08-4259-a0f0-8a4b393b112e', '題馬太尉華山莊', '題马太尉华山莊', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["別開池館背山陰，近得幽奇物外心。","竹色拂雲連嶽寺，泉聲帶雨出谿林。","一庭楊柳春光暖，三逕煙蘿晚翠深。","自是功成閑劒履，西齋長臥對瑤琴。"]', '["別开池館背山陰，近得幽奇物外心。","竹色拂云連嶽寺，泉声带雨出谿林。","一庭楊柳春光暖，三逕煙蘿晚翠深。","自是功成闲劒履，西斋长臥对瑤琴。"]', '诗', 'shi', '', NULL, '題馬太尉華山莊 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61c10046-5c6e-4655-8338-f9802d9700ef', '秋日夜懷', '秋日夜懷', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["砧杵寥寥秋色長，遶枝寒鵲客情傷。","關山雲盡九秋月，門柳葉凋三徑霜。","近日每思歸少室，故人遙憶隔瀟湘。","如何節候變容髪，明鏡一看愁異常。"]', '["砧杵寥寥秋色长，遶枝寒鵲客情傷。","关山云尽九秋月，门柳葉凋三徑霜。","近日每思归少室，故人遙憶隔瀟湘。","如何節候变容髪，明镜一看愁異常。"]', '诗', 'shi', '', NULL, '秋日夜懷 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85926f2d-6a22-4850-8ef7-b3f4e4739f5f', '題巫山廟', '題巫山廟', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["十二嵐峯挂夕暉，廟門深閉霧煙微。","天高木落楚人思，山迥月殘神女歸。","觸石晴雲凝翠鬢，度江寒雨濕羅衣。","嬋娟似恨襄王夢，猨呌斷岩秋蘚稀。"]', '["十二嵐峯挂夕暉，廟门深閉霧煙微。","天高木落楚人思，山迥月殘神女归。","觸石晴云凝翠鬢，度江寒雨濕羅衣。","嬋娟似恨襄王梦，猨呌斷岩秋蘚稀。"]', '诗', 'shi', '', NULL, '題巫山廟 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ed023a1-51d2-4005-b56a-7f03c6d8fbf8', '題吳宮苑', '題吳宮苑', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["吳苑荒涼故國名，吳山月上照江明。","殘春碧樹自留影，半夜子規何處聲。","蘆葉長侵洲渚暗，蘋花開盡水煙平。","經過此地千年恨，荏苒東風露色清。"]', '["吳苑荒涼故国名，吳山月上照江明。","殘春碧樹自留影，半夜子規何处声。","蘆葉长侵洲渚暗，蘋花开尽水煙平。","經過此地千年恨，荏苒东风露色清。"]', '诗', 'shi', '', NULL, '題吳宮苑 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d95041f-98b9-4f24-bdf1-83ee361a3c0a', '旅館書懷', '旅館书懷', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["秋看庭樹換風煙，兄弟飄零寄海邊。","客計倦行分陝路，家貧休種汶陽田。","雲低遠塞鳴寒鴈，雨歇空山噪暮蟬。","落葉蟲絲滿窗戶，秋堂獨坐思悠然。"]', '["秋看庭樹換风煙，兄弟飄零寄海邊。","客計倦行分陝路，家貧休種汶陽田。","云低远塞鳴寒鴈，雨歇空山噪暮蟬。","落葉蟲絲满窗戶，秋堂独坐思悠然。"]', '诗', 'shi', '', NULL, '旅館書懷 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1f09741-40df-4fe9-861c-1334238e791d', '贈天台隱者', '贈天台隐者', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["靜者多依猨鳥叢，衡門野色四郊通。","天開宿霧海生日，水泛落花山有風。","迴望一巢懸木末，獨尋危石坐巖中。","看書飲酒餘無事，自樂樵漁狎釣翁。"]', '["静者多依猨鸟叢，衡门野色四郊通。","天开宿霧海生日，水泛落花山有风。","迴望一巢懸木末，独尋危石坐巖中。","看书饮酒餘無事，自乐樵漁狎釣翁。"]', '诗', 'shi', '', NULL, '贈天台隱者 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d0f2059-8fe4-40e9-9a50-5d098b82f449', '洛陽月夜書懷', '洛陽月夜书懷', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["疎柳高槐古巷通，月明西照上陽宮。","一聲邊鴈塞門雪，幾處遠砧河漢風。","獨榻閑眠移嶽影，寒窗幽思度煙空。","孤吟此夕驚秋晚，落葉殘花樹色中。"]', '["疎柳高槐古巷通，月明西照上陽宮。","一声邊鴈塞门雪，幾处远砧河漢风。","独榻闲眠移嶽影，寒窗幽思度煙空。","孤吟此夕驚秋晚，落葉殘花樹色中。"]', '诗', 'shi', '', NULL, '洛陽月夜書懷 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9b17191-0309-4b6b-ac99-e19b55b1facb', '江行夜泊', '江行夜泊', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["白浪連空極渺漫，孤舟此夜泊中灘。","岳陽秋霽寺鐘遠，渡口月明漁火殘。","綠綺韵高湘女怨，青葭色映水禽寒。","鄉遙楚國生歸思，欲曙山光上木蘭。"]', '["白浪連空極渺漫，孤舟此夜泊中灘。","岳陽秋霽寺鐘远，渡口月明漁火殘。","綠綺韵高湘女怨，青葭色映水禽寒。","乡遙楚国生归思，欲曙山光上木蘭。"]', '诗', 'shi', '', NULL, '江行夜泊 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b56c1b5c-e2c6-4afc-8a38-682213b77b27', '贈顓頊山人', '贈顓頊山人', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["浩氣含真玉片輝，著書精義入玄微。","洛陽紫陌幾曾醉，少室白雲時一歸。","松雪月高唯鶴宿，煙嵐秋霽到人稀。","知君濟世有長策，莫問滄浪隱釣磯。"]', '["浩氣含真玉片輝，著书精義入玄微。","洛陽紫陌幾曾醉，少室白云时一归。","松雪月高唯鹤宿，煙嵐秋霽到人稀。","知君濟世有长策，莫问滄浪隐釣磯。"]', '诗', 'shi', '', NULL, '贈顓頊山人 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b669ace-ad1c-47fe-8293-be7fb630a044', '長安冬夜書情', '长安冬夜书情', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["上國棲遲歲欲終，此情多寄寂寥中。","鐘傳半夜旅人館，鵶呌一聲疎樹風。","古巷月高山色靜，寒蕪霜落灞原空。","今來唯問心期事，獨望青雲路未通。"]', '["上国棲遲歲欲終，此情多寄寂寥中。","鐘傳半夜旅人館，鵶呌一声疎樹风。","古巷月高山色静，寒蕪霜落灞原空。","今来唯问心期事，独望青云路未通。"]', '诗', 'shi', '', NULL, '長安冬夜書情 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('898dc273-91c0-44ea-bb89-ba1505e6bdc9', '經古行宮', '經古行宮', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["玉輦西歸已至今，古原風景自沈沈。","御溝流水長芳草，宮樹落花空夕陰。","胡蝶翅翻殘露滴，子規聲盡野煙深。","路人不記當年事，臺殿寂寥山影侵。"]', '["玉輦西归已至今，古原风景自沈沈。","御溝流水长芳草，宮樹落花空夕陰。","胡蝶翅翻殘露滴，子規声尽野煙深。","路人不記當年事，台殿寂寥山影侵。"]', '诗', 'shi', '', NULL, '經古行宮 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a9bf12-0c1e-45b3-8387-ea9c4918ca31', '秋日登醴泉縣樓', '秋日登醴泉縣楼', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["閑上高樓時一望，綠蕪寒野靜中分。","人行直路入秦樹，鴈截斜陽背塞雲。","渭水自流汀島色，漢陵空長石苔紋。","秋風高柳出危葉，獨聽蟬聲日欲曛。"]', '["闲上高楼时一望，綠蕪寒野静中分。","人行直路入秦樹，鴈截斜陽背塞云。","渭水自流汀島色，漢陵空长石苔紋。","秋风高柳出危葉，独听蟬声日欲曛。"]', '诗', 'shi', '', NULL, '秋日登醴泉縣樓 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4111405-815a-4142-ac0d-233452564c5a', '春日旅遊', '春日旅游', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["玄髪辭家事遠遊，春風歸鴈一聲愁。","花開忽憶故山樹，月上自登臨水樓。","浩浩晴原人獨去，依依春草水分流。","秦川楚塞煙波隔，怨別路岐何日休。"]', '["玄髪辞家事远游，春风归鴈一声愁。","花开忽憶故山樹，月上自登臨水楼。","浩浩晴原人独去，依依春草水分流。","秦川楚塞煙波隔，怨別路岐何日休。"]', '诗', 'shi', '', NULL, '春日旅遊 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('665ed260-133e-4dc8-a221-b20b6b2e4649', '送友人下第歸吳', '送友人下第归吳', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["共惜年華未立名，路岐終日軫羈情。","青春半是往來盡，白髮多因離別生。","楚岸帆開雲樹映，吳門月上水煙清。","東歸自有故山約，花落石牀苔蘚平。"]', '["共惜年华未立名，路岐終日軫羈情。","青春半是往来尽，白髮多因離別生。","楚岸帆开云樹映，吳门月上水煙清。","东归自有故山約，花落石牀苔蘚平。"]', '诗', 'shi', '', NULL, '送友人下第歸吳 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1398615a-7dff-4349-bbed-1b8d5e878838', '訪友人郊居', '訪友人郊居', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["登原過水訪相如，竹塢莎庭似故居。","空塞山當清晝晚，古槐人繼綠陰餘。","休彈瑟韻傷離思，已有蟬聲報夏初。","醉唱勞歌翻自歎，釣船漁浦夢難疎。"]', '["登原過水訪相如，竹塢莎庭似故居。","空塞山當清晝晚，古槐人繼綠陰餘。","休彈瑟韻傷離思，已有蟬声報夏初。","醉唱勞歌翻自歎，釣船漁浦梦难疎。"]', '诗', 'shi', '', NULL, '訪友人郊居 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7207a46c-d68a-4d68-86a2-53ac50240c13', '匡城尋薛閔秀才不遇', '匡城尋薛閔秀才不遇', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["音容一別近三年，往事空思意浩然。","匹馬東西何處客，孤城楊柳晚來蟬。","路長草色秋山綠，川闊晴光遠水連。","不見故人勞夢寐，獨吟風月過南燕。"]', '["音容一別近三年，往事空思意浩然。","匹马东西何处客，孤城楊柳晚来蟬。","路长草色秋山綠，川闊晴光远水連。","不见故人勞梦寐，独吟风月過南燕。"]', '诗', 'shi', '', NULL, '匡城尋薛閔秀才不遇 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79f76c9d-00ae-47f6-8cd3-634f3381a1ac', '與僧話舊', '與僧話旧', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["巾舃同時下翠微，舊遊因話事多違。","南朝古寺幾僧在，西嶺空林唯鳥歸。","莎徑晚煙凝竹塢，石池春色染苔衣。","此時相見又相別，即是關河朔鴈飛。"]', '["巾舃同时下翠微，旧游因話事多違。","南朝古寺幾僧在，西嶺空林唯鸟归。","莎徑晚煙凝竹塢，石池春色染苔衣。","此时相见又相別，即是关河朔鴈飞。"]', '诗', 'shi', '', NULL, '與僧話舊 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce81977-0e77-4ae7-8659-037eea137ce5', '寄遠', '寄远', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["西園楊柳暗驚秋，寶瑟朱弦結遠愁。","霜落鴈聲來紫塞，月明人夢在青樓。","蕙心迢遰湘雲暮，蘭思縈迴楚水流。","錦字織成添別恨，關河萬里路悠悠。"]', '["西园楊柳暗驚秋，寶瑟朱弦結远愁。","霜落鴈声来紫塞，月明人梦在青楼。","蕙心迢遰湘云暮，蘭思縈迴楚水流。","錦字织成添別恨，关河万里路悠悠。"]', '诗', 'shi', '', NULL, '寄遠 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('494cfc5f-f5f4-4ca7-8542-b7cc557fe58a', '長安逢友人', '长安逢友人', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["上國相逢塵滿襟，傾杯一話昔年心。","荒臺共望秋山立，古寺多同雪夜吟。","風度重城宮漏盡，月明高柳禁煙深。","終期白日青雲路，休感鬢毛霜雪侵。"]', '["上国相逢塵满襟，傾杯一話昔年心。","荒台共望秋山立，古寺多同雪夜吟。","风度重城宮漏尽，月明高柳禁煙深。","終期白日青云路，休感鬢毛霜雪侵。"]', '诗', 'shi', '', NULL, '長安逢友人 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cea7b6f-c0e3-4df2-8b86-ce4778e87e1c', '下第東歸途中書事', '下第东归途中书事', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["峽路誰知倦此情，往來多是半年程。","孤吟洛苑逢春盡，幾向秦城見月明。","高柳斷煙侵嶽影，古隄斜日背灘聲。","東歸海上有餘業，牢落田園荒草平。"]', '["峽路誰知倦此情，往来多是半年程。","孤吟洛苑逢春尽，幾向秦城见月明。","高柳斷煙侵嶽影，古隄斜日背灘声。","东归海上有餘業，牢落田园荒草平。"]', '诗', 'shi', '', NULL, '下第東歸途中書事 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1f4e0d8-2b67-4b9d-b3f2-58616a3c0758', '經龍門廢寺', '經龙门廢寺', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["因思人事事無窮，幾度經過感此中。","山色不移樓殿盡，石臺依舊水雲空。","唯餘芳草滴春露，時有殘花落晚風。","楊柳覆灘清瀨響，暮天沙鳥自西東。"]', '["因思人事事無窮，幾度經過感此中。","山色不移楼殿尽，石台依旧水云空。","唯餘芳草滴春露，时有殘花落晚风。","楊柳覆灘清瀨响，暮天沙鸟自西东。"]', '诗', 'shi', '', NULL, '經龍門廢寺 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4204559c-c474-431e-b737-3fea237e3ef2', '下第後懷舊居', '下第後懷旧居', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["幾到青門未立名，芳時多負故鄉情。","雨餘秦苑綠蕪合，春盡灞原白髮生。","每見山泉長屬意，終期身事在歸耕。","蘋花覆水曲谿暮，獨坐釣舟歌月明。"]', '["幾到青门未立名，芳时多負故乡情。","雨餘秦苑綠蕪合，春尽灞原白髮生。","每见山泉长屬意，終期身事在归耕。","蘋花覆水曲谿暮，独坐釣舟歌月明。"]', '诗', 'shi', '', NULL, '下第後懷舊居 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e69984-b494-433a-9f79-46ad3bf9c2aa', '經無可舊居兼傷賈島', '經無可旧居兼傷賈島', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["塵室寒窗我獨看，別來人事幾凋殘。","晝空蕭寺一僧去，雪滿巴山孤客寒。","落葉墮巢禽自出，蒼苔封砌竹成竿。","碧雲迢遰長江遠，向夕苦吟歸思難。"]', '["塵室寒窗我独看，別来人事幾凋殘。","晝空蕭寺一僧去，雪满巴山孤客寒。","落葉墮巢禽自出，蒼苔封砌竹成竿。","碧云迢遰长江远，向夕苦吟归思难。"]', '诗', 'shi', '', NULL, '經無可舊居兼傷賈島 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ff9a51-19f8-452f-ac7a-fd5d32aec8a4', '贈隱者', '贈隐者', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["何時止此幽棲處，獨掩衡門長綠苔。","臨水靜聞靈鶴語，隔原時有至人來。","五湖仙島幾年別，九轉藥爐深夜開。","誰識無機養真性，醉眠松石枕空杯。"]', '["何时止此幽棲处，独掩衡门长綠苔。","臨水静闻靈鹤語，隔原时有至人来。","五湖仙島幾年別，九轉藥爐深夜开。","誰識無機養真性，醉眠松石枕空杯。"]', '诗', 'shi', '', NULL, '贈隱者 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7e5aa4f-2e88-4348-85cf-b3a9d7fa989f', '題書齋', '題书斋', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["一日不曾離此處，風吹疎牖夕雲晴。","氣凌霜色劒光動，吟對雪華詩韻清。","高木宿禽來遠嶽，古原殘雨隔重城。","西齋瑤瑟自爲侶，門掩半春苔蘚生。"]', '["一日不曾離此处，风吹疎牖夕云晴。","氣凌霜色劒光动，吟对雪华诗韻清。","高木宿禽来远嶽，古原殘雨隔重城。","西斋瑤瑟自爲侶，门掩半春苔蘚生。"]', '诗', 'shi', '', NULL, '題書齋 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b336e5f6-4a05-491b-b65d-c19ba6edabcc', '題秦女樓', '題秦女楼', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["珠翠香銷鴛瓦墮，神仙曾向此中遊。","青樓月色桂花冷，碧落簫聲雲葉愁。","杳杳蓬萊人不見，蒼蒼苔蘚路空留。","一從鳳去千年後，迢遰岐山水石秋。"]', '["珠翠香銷鴛瓦墮，神仙曾向此中游。","青楼月色桂花冷，碧落簫声云葉愁。","杳杳蓬萊人不见，蒼蒼苔蘚路空留。","一從鳳去千年後，迢遰岐山水石秋。"]', '诗', 'shi', '', NULL, '題秦女樓 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34825610-0702-4650-88fc-342f3e5f6e61', '題桃源處士山居留寄', '題桃源处士山居留寄', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["白雲深處葺茅廬，退隱衡門與俗疎。","一洞曉煙留水上，滿庭春露落花初。","閑看竹嶼吟新月，特酌山醪讀古書。","窮達盡爲身外事，浩然元氣樂樵漁。"]', '["白云深处葺茅廬，退隐衡门與俗疎。","一洞晓煙留水上，满庭春露落花初。","闲看竹嶼吟新月，特酌山醪读古书。","窮達尽爲身外事，浩然元氣乐樵漁。"]', '诗', 'shi', '', NULL, '題桃源處士山居留寄 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5773b54-5774-4eef-9805-2676268a4c9f', '宿題天壇觀', '宿題天壇观', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["沐髪清齋宿洞宮，桂花松韻滿巖風。","紫霞曉色秋山霽，碧落寒光霜月空。","華表鶴聲天外迥，蓬萊仙界海門通。","冥心一悟虛無理，寂寞玄珠象罔中。"]', '["沐髪清斋宿洞宮，桂花松韻满巖风。","紫霞晓色秋山霽，碧落寒光霜月空。","华表鹤声天外迥，蓬萊仙界海门通。","冥心一悟虛無理，寂寞玄珠象罔中。"]', '诗', 'shi', '', NULL, '宿題天壇觀 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4f40e7c-829d-4c6c-ba00-58e65119b8b4', '洛神怨', '洛神怨', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["子建東歸恨思長，飄颻神女步池塘。","雲鬟高動水宮影，珠翠乍搖沙露光。","心寄碧沈空婉戀，夢殘春色自悠揚。","停車綺陌傍楊柳，片月青樓落未央。"]', '["子建东归恨思长，飄颻神女步池塘。","云鬟高动水宮影，珠翠乍搖沙露光。","心寄碧沈空婉戀，梦殘春色自悠揚。","停车綺陌傍楊柳，片月青楼落未央。"]', '诗', 'shi', '', NULL, '洛神怨 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aead4684-9422-4a53-ad7a-0a38396be3ff', '龍門留別道友', '龙门留別道友', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["一顧恩深荷道安，獨垂雙淚下層巒。","飛鳴北鴈塞雲暮，搖落西風關樹寒。","春谷終期吹羽翼，萍身不定逐波瀾。","裴徊偏起舊枝戀，半夜獨吟孤燭殘。"]', '["一顧恩深荷道安，独垂雙泪下層巒。","飞鳴北鴈塞云暮，搖落西风关樹寒。","春谷終期吹羽翼，萍身不定逐波瀾。","裴徊偏起旧枝戀，半夜独吟孤燭殘。"]', '诗', 'shi', '', NULL, '龍門留別道友 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('163af2c9-5dda-4fbe-896d-555e25b1dcf8', '題四皓廟', '題四皓廟', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["石壁蒼苔翠靄濃，驅車商洛想遺踪。","天高猨呌向山月，露下鶴聲來廟松。","葉墮陰巖疎薜荔，池經秋雨老芙蓉。","雪髯仙侶何深隱，千古寂寥雲水重。"]', '["石壁蒼苔翠靄濃，驱车商洛想遺踪。","天高猨呌向山月，露下鹤声来廟松。","葉墮陰巖疎薜荔，池經秋雨老芙蓉。","雪髯仙侶何深隐，千古寂寥云水重。"]', '诗', 'shi', '', NULL, '題四皓廟 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5543119-58a6-4428-abbe-44f98c9c67cb', '望未央宮', '望未央宮', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["西上秦原見未央，山嵐川色晚蒼蒼。","雲樓欲動入清渭，鴛瓦如飛出綠楊。","舞席歌塵空歲月，宮花春草滿池塘。","香風吹落天人語，綵鳳五雲朝漢皇。"]', '["西上秦原见未央，山嵐川色晚蒼蒼。","云楼欲动入清渭，鴛瓦如飞出綠楊。","舞席歌塵空歲月，宮花春草满池塘。","香风吹落天人語，綵鳳五云朝漢皇。"]', '诗', 'shi', '', NULL, '望未央宮 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09537476-48f1-40e8-9f16-833c6e1a70ec', '秋日過昭陵', '秋日過昭陵', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["寢廟徒悲劒與冠，翠華龍馭杳漫漫。","原分山勢入空塞，地匝松陰出晚寒。","上界鼎成雲縹緲，西陵舞罷淚闌干。","那堪獨立斜陽裏，碧落秋光煙樹殘。"]', '["寢廟徒悲劒與冠，翠华龙馭杳漫漫。","原分山勢入空塞，地匝松陰出晚寒。","上界鼎成云縹緲，西陵舞罷泪闌干。","那堪独立斜陽裏，碧落秋光煙樹殘。"]', '诗', 'shi', '', NULL, '秋日過昭陵 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c59a047f-2ea1-4b49-94c1-3e1dcf264ae9', '夏日登慈恩寺', '夏日登慈恩寺', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["金界時來一訪僧，天香飄翠瑣窗凝。","碧池靜照寒松影，清晝深懸古殿燈。","晚景風蟬催節候，高空雲鳥度軒層。","塵機消盡話玄理，暮磬出林疎韻澄。"]', '["金界时来一訪僧，天香飄翠瑣窗凝。","碧池静照寒松影，清晝深懸古殿灯。","晚景风蟬催節候，高空云鸟度軒層。","塵機消尽話玄理，暮磬出林疎韻澄。"]', '诗', 'shi', '', NULL, '夏日登慈恩寺 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('998d04e8-1ada-4bd5-88a8-b50a88f6de8c', '宿題金山寺', '宿題金山寺', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["一點青山翠色危，雲岩不掩與星期。","海門煙樹潮歸後，江面山樓月照時。","獨鶴唳空秋露下，高僧入定夜猨知。","蕭疎水木清鐘梵，顥氣寒光動石池。"]', '["一点青山翠色危，云岩不掩與星期。","海门煙樹潮归後，江面山楼月照时。","独鹤唳空秋露下，高僧入定夜猨知。","蕭疎水木清鐘梵，顥氣寒光动石池。"]', '诗', 'shi', '', NULL, '宿題金山寺 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6600f7c6-0427-48fe-98d2-00c36cb5896e', '送友人遊蜀', '送友人游蜀', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["北去西遊春未半，蜀山雲雪入詩情。","青蘿拂水花流影，翠靄隔巖猨有聲。","日出空江分遠浪，鳥歸高木認孤城。","心期萬里無勞倦，古石蒼苔峽路清。"]', '["北去西游春未半，蜀山云雪入诗情。","青蘿拂水花流影，翠靄隔巖猨有声。","日出空江分远浪，鸟归高木認孤城。","心期万里無勞倦，古石蒼苔峽路清。"]', '诗', 'shi', '', NULL, '送友人遊蜀 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c531003-97bb-4399-b548-67583cae0daa', '題鄭中丞東溪', '題鄭中丞东溪', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["一境新開雉堞西，綠苔微徑露淒淒。","高軒夜靜竹聲遠，曲岸春深楊柳低。","山霽月明常此醉，草芳花暗省曾迷。","即隨鳳詔歸清列，幾憶風花夢小溪。"]', '["一境新开雉堞西，綠苔微徑露淒淒。","高軒夜静竹声远，曲岸春深楊柳低。","山霽月明常此醉，草芳花暗省曾迷。","即隨鳳詔归清列，幾憶风花梦小溪。"]', '诗', 'shi', '', NULL, '題鄭中丞東溪 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51511e2d-c8da-4892-82a1-c98c70bcb78e', '代友人悼姬', '代友人悼姬', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["羅帳香微冷錦裀，歌聲永絕想梁塵。","蕭郎獨宿落花夜，謝女不歸明月春。","青鳥罷傳相寄字，碧江無復採蓮人。","滿庭芳草坐成恨，迢遰蓬萊入夢頻。"]', '["羅帳香微冷錦裀，歌声永絕想梁塵。","蕭郎独宿落花夜，謝女不归明月春。","青鸟罷傳相寄字，碧江無复採蓮人。","满庭芳草坐成恨，迢遰蓬萊入梦頻。"]', '诗', 'shi', '', NULL, '代友人悼姬 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d27db0e-2c51-4b39-a9f1-94c9235388ea', '夏日登西林白上人樓', '夏日登西林白上人楼', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["幾到西林清淨境，層臺高視有無間。","寒光遠動天邊水，碧影出空煙外山。","苔點落花微萼在，葉藏幽鳥碎聲閑。","曠然多慊登樓意，永日重門深掩關。"]', '["幾到西林清淨境，層台高視有無间。","寒光远动天邊水，碧影出空煙外山。","苔点落花微萼在，葉藏幽鸟碎声闲。","曠然多慊登楼意，永日重门深掩关。"]', '诗', 'shi', '', NULL, '夏日登西林白上人樓 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc639bfd-b8ab-4fd6-8dd3-8b0c838187b6', '江樓月夜聞笛', '江楼月夜闻笛', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["南浦蒹葭疎雨後，寂寥橫笛怨江樓。","思飄明月浪花白，聲入碧雲楓葉秋。","河漢夜闌孤鴈度，瀟湘水闊二妃愁。","髪寒衣濕曲初罷，露色河光生釣舟。"]', '["南浦蒹葭疎雨後，寂寥橫笛怨江楼。","思飄明月浪花白，声入碧云楓葉秋。","河漢夜闌孤鴈度，瀟湘水闊二妃愁。","髪寒衣濕曲初罷，露色河光生釣舟。"]', '诗', 'shi', '', NULL, '江樓月夜聞笛 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfca5cb4-24f2-464d-8d60-b60a5a46a27d', '送友人下第東歸', '送友人下第东归', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["漠漠楊花灞岸飛，幾迴傾酒話東歸。","九衢春盡生鄉夢，千里塵多滿客衣。","流水雨餘芳草合，空山月晚白雲微。","金門自有西來約，莫待螢光照竹扉。"]', '["漠漠楊花灞岸飞，幾迴傾酒話东归。","九衢春尽生乡梦，千里塵多满客衣。","流水雨餘芳草合，空山月晚白云微。","金门自有西来約，莫待螢光照竹扉。"]', '诗', 'shi', '', NULL, '送友人下第東歸 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5372dae-746b-411b-b3c5-2aa051e056ef', '從鄭郎中高州遊東潭', '從鄭郎中高州游东潭', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["煙嵐晚入濕旌旗，高檻風清醉未歸。","夾路野花迎馬首，出林山鳥向人飛。","一谿寒水涵清淺，幾處晴雲度翠微。","自是謝公心近得，登樓望月思依依。"]', '["煙嵐晚入濕旌旗，高檻风清醉未归。","夾路野花迎马首，出林山鸟向人飞。","一谿寒水涵清淺，幾处晴云度翠微。","自是謝公心近得，登楼望月思依依。"]', '诗', 'shi', '', NULL, '從鄭郎中高州遊東潭 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('121e3c69-0905-4115-b2fa-31800bd25a8a', '罷華原尉上座主尚書', '罷华原尉上座主尚书', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["自憐生計事悠悠，浩渺滄浪一釣舟。","千里夢歸清洛近，三年官罷杜陵秋。","山連絕塞渾無色，水到平沙幾處流。","白露黃花歲時晚，不堪霜鬢鏡前愁。"]', '["自怜生計事悠悠，浩渺滄浪一釣舟。","千里梦归清洛近，三年官罷杜陵秋。","山連絕塞渾無色，水到平沙幾处流。","白露黄花歲时晚，不堪霜鬢镜前愁。"]', '诗', 'shi', '', NULL, '罷華原尉上座主尚書 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff92816-b977-4868-98d3-7cd7155303d6', '雨後遊南門寺', '雨後游南门寺', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["郭南山寺雨初晴，上界尋僧竹裏行。","半壁樓臺秋月過，一川煙水夕陽平。","苔封石室雲含潤，露滴松枝鶴有聲。","木葉蕭蕭動歸思，西風畫角漢東城。"]', '["郭南山寺雨初晴，上界尋僧竹裏行。","半壁楼台秋月過，一川煙水夕陽平。","苔封石室云含潤，露滴松枝鹤有声。","木葉蕭蕭动归思，西风畫角漢东城。"]', '诗', 'shi', '', NULL, '雨後遊南門寺 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81005274-f922-4b13-b433-0def4cff5683', '題古寺', '題古寺', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["古寺蕭條偶宿期，更深霜壓竹枝低。","長天月影高窗過，疎樹寒鵶半夜啼。","池水竭來龍已去，老松枯處鶴猶棲。","傷心可惜從前事，寥落朱廊墮粉泥。"]', '["古寺蕭條偶宿期，更深霜壓竹枝低。","长天月影高窗過，疎樹寒鵶半夜啼。","池水竭来龙已去，老松枯处鹤猶棲。","傷心可惜從前事，寥落朱廊墮粉泥。"]', '诗', 'shi', '', NULL, '題古寺 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7268a30-87c5-438f-bf5f-82e3b4398a58', '晚秋野望', '晚秋野望', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["秋盡郊原情自哀，菊花寂寞晚仍開。","高風疎葉帶霜落，一鴈寒聲背水來。","荒壘幾年經戰後，故山終日望書回。","歸途休問從前事，獨唱勞歌醉數杯。"]', '["秋尽郊原情自哀，菊花寂寞晚仍开。","高风疎葉带霜落，一鴈寒声背水来。","荒壘幾年經戰後，故山終日望书回。","归途休问從前事，独唱勞歌醉數杯。"]', '诗', 'shi', '', NULL, '晚秋野望 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ba120c3-a9c0-4044-a0fc-cb319764ebc5', '秋月望上陽宮', '秋月望上陽宮', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["苔色輕塵鎖洞房，亂鴉羣鴿集殘陽。","青山空出禁城日，黃葉自飛宮樹霜。","御路幾年香輦去，天津終日水聲長。","此時獨立意難盡，正值西風砧杵涼。"]', '["苔色轻塵鎖洞房，亂鴉羣鴿集殘陽。","青山空出禁城日，黄葉自飞宮樹霜。","御路幾年香輦去，天津終日水声长。","此时独立意难尽，正值西风砧杵涼。"]', '诗', 'shi', '', NULL, '秋月望上陽宮 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88904708-e986-43e3-95b1-1b291fa17576', '入關留別主人', '入关留別主人', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["此來多愧食魚心，東閣將辭強一吟。","羸馬客程秋草合，晚蟬關樹古槐深。","風生野渡河聲急，鴈過寒原嶽勢侵。","對酒相看自無語，幾多離思入瑤琴。"]', '["此来多愧食鱼心，东閣將辞強一吟。","羸马客程秋草合，晚蟬关樹古槐深。","风生野渡河声急，鴈過寒原嶽勢侵。","对酒相看自無語，幾多離思入瑤琴。"]', '诗', 'shi', '', NULL, '入關留別主人 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeae8a38-837d-458a-8e8a-8f9018f6e4cb', '留別山中友人', '留別山中友人', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["欲辭松月戀知音，去住多同羈鳥心。","秋盡書窗驚白髮，晚衝霜葉下青岑。","大河風急寒聲遠，高嶺雲開夕影深。","別後寂寥無限意，野花門路草蟲吟。"]', '["欲辞松月戀知音，去住多同羈鸟心。","秋尽书窗驚白髮，晚衝霜葉下青岑。","大河风急寒声远，高嶺云开夕影深。","別後寂寥無限意，野花门路草蟲吟。"]', '诗', 'shi', '', NULL, '留別山中友人 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57186daf-df8b-40c3-b3c1-6b2205e92a2a', '春晚旅次有懷', '春晚旅次有懷', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["晚出關河綠野平，依依雲樹動鄉情。","殘春花盡黃鶯語，遠客愁多白髮生。","野水亂流臨古驛，斷煙凝處近孤城。","東西未遂歸田計，海上青山久廢耕。"]', '["晚出关河綠野平，依依云樹动乡情。","殘春花尽黄鶯語，远客愁多白髮生。","野水亂流臨古驛，斷煙凝处近孤城。","东西未遂归田計，海上青山久廢耕。"]', '诗', 'shi', '', NULL, '春晚旅次有懷 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1117acb4-7846-488b-a201-38ca471d2fad', '與重幽上人話舊', '與重幽上人話旧', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["雲飛天末水空流，省與師同別異州。","庭樹蟬聲初入夏，石牀苔色幾經秋。","燈微靜室生鄉思，月上嚴城話旅遊。","自喜他年接巾舃，滄浪地近虎溪頭。"]', '["云飞天末水空流，省與師同別異州。","庭樹蟬声初入夏，石牀苔色幾經秋。","灯微静室生乡思，月上嚴城話旅游。","自喜他年接巾舃，滄浪地近虎溪头。"]', '诗', 'shi', '', NULL, '與重幽上人話舊 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f99648a9-f80a-4b31-b900-e0b9c43a5613', '月夜聞鶴唳', '月夜闻鹤唳', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["碧落風微月正明，霜毛似怨有離情。","莓苔石冷想孤立，楊柳葉疎聞轉清。","空夜露殘驚墮羽，遼天秋晚憶歸程。","鳳凰樓閣知猶戀，終逐煙霞上玉京。"]', '["碧落风微月正明，霜毛似怨有離情。","莓苔石冷想孤立，楊柳葉疎闻轉清。","空夜露殘驚墮羽，遼天秋晚憶归程。","鳳凰楼閣知猶戀，終逐煙霞上玉京。"]', '诗', 'shi', '', NULL, '月夜聞鶴唳 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('249a5e40-ec0e-491f-af74-c6de16382e0f', '過北邙山', '過北邙山', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["散漫黃埃滿北原，折碑橫路碾苔痕。","空山夜月來松影，荒塚春風變木根。","漠漠兔絲羅古廟，翩翩丹旐過孤村。","白楊落日悲風起，蕭索寒巢鳥獨奔。"]', '["散漫黄埃满北原，折碑橫路碾苔痕。","空山夜月来松影，荒塚春风变木根。","漠漠兔絲羅古廟，翩翩丹旐過孤村。","白楊落日悲风起，蕭索寒巢鸟独奔。"]', '诗', 'shi', '', NULL, '過北邙山 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b25131-75e4-4f7e-9209-8ca5b63ef5ab', '咸陽懷古', '咸陽懷古', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["經過此地無窮事，一望淒然感廢興。","渭水故都秦二世，咸原秋草漢諸陵。","天空絕塞聞邊鴈，葉盡孤村見夜燈。","風景蒼蒼多少恨，寒山半出白雲層。"]', '["經過此地無窮事，一望淒然感廢兴。","渭水故都秦二世，咸原秋草漢諸陵。","天空絕塞闻邊鴈，葉尽孤村见夜灯。","风景蒼蒼多少恨，寒山半出白云層。"]', '诗', 'shi', '', NULL, '咸陽懷古 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('103eece3-d83c-4a1c-a630-e8b916f0e1ab', '送友人罷舉赴薊門從事', '送友人罷舉赴薊门從事', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["人生行止在知己，遠佐諸侯重所依。","綠綬便當身是貴，青霄休怨志相違。","晚雲遼水疎殘雨，寒角邊城怨落暉。","此去黃金臺上客，相思應羨鴈南歸。"]', '["人生行止在知己，远佐諸侯重所依。","綠綬便當身是貴，青霄休怨志相違。","晚云遼水疎殘雨，寒角邊城怨落暉。","此去黄金台上客，相思應羨鴈南归。"]', '诗', 'shi', '', NULL, '送友人罷舉赴薊門從事 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25de53a4-270d-47e9-ac8f-805ee7fc637c', '看牓日', '看牓日', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["禁漏初停蘭省開，列仙名目上清來。","飛鳴曉日鶯聲遠，變化春風鶴影回。","廣陌萬人生喜色，曲江千樹發寒梅。","青雲已是酬恩處，莫惜芳時醉酒杯。"]', '["禁漏初停蘭省开，列仙名目上清来。","飞鳴晓日鶯声远，变化春风鹤影回。","廣陌万人生喜色，曲江千樹發寒梅。","青云已是酬恩处，莫惜芳时醉酒杯。"]', '诗', 'shi', '', NULL, '看牓日 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8171fc9a-76cb-4661-af55-f70b20420d73', '送李休秀才歸嶺中', '送李休秀才归嶺中', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["南泛孤舟景自饒，蒹葭汀浦晚蕭蕭。","秋風漢水旅愁起，寒木楚山歸思遙。","獨夜猨聲和落葉，晴江月色帶回潮。","故園新過重陽節，黃菊滿籬應未凋。"]', '["南泛孤舟景自饒，蒹葭汀浦晚蕭蕭。","秋风漢水旅愁起，寒木楚山归思遙。","独夜猨声和落葉，晴江月色带回潮。","故园新過重陽節，黄菊满籬應未凋。"]', '诗', 'shi', '', NULL, '送李休秀才歸嶺中 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40da7dc5-52b1-4987-9844-5573281b0b01', '寓居寄友人', '寓居寄友人', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["雨餘虛館竹陰清，獨坐書窗軫旅情。","芳草衡門無馬跡，古槐深巷有蟬聲。","夕陽雲盡嵩峰出，遠岸煙消洛水平。","今夜南原賞佳景，月高風定苦吟生。"]', '["雨餘虛館竹陰清，独坐书窗軫旅情。","芳草衡门無马跡，古槐深巷有蟬声。","夕陽云尽嵩峰出，远岸煙消洛水平。","今夜南原賞佳景，月高风定苦吟生。"]', '诗', 'shi', '', NULL, '寓居寄友人 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58446644-2460-4083-bc83-aa75de4acc4f', '經曲阜城', '經曲阜城', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["行經闕里自堪傷，曾歎東流逝水長。","蘿蔓幾凋荒隴樹，莓苔多處古宮牆。","三千弟子標青史，萬代先生號素王。","蕭索風高洙泗上，秋山明月夜蒼蒼。"]', '["行經闕里自堪傷，曾歎东流逝水长。","蘿蔓幾凋荒隴樹，莓苔多处古宮牆。","三千弟子標青史，万代先生號素王。","蕭索风高洙泗上，秋山明月夜蒼蒼。"]', '诗', 'shi', '', NULL, '經曲阜城 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42369471-2c85-4478-bd4b-f5dc3b8ad7ed', '汶陽客舍', '汶陽客舍', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["年光自感益蹉跎，岐路東西竟若何。","窗外雨來山色近，海邊秋至鴈聲多。","思鄉每讀登樓賦，對月空吟叩角歌。","迢遰舊山伊水畔，破齋荒徑閉煙蘿。"]', '["年光自感益蹉跎，岐路东西竟若何。","窗外雨来山色近，海邊秋至鴈声多。","思乡每读登楼賦，对月空吟叩角歌。","迢遰旧山伊水畔，破斋荒徑閉煙蘿。"]', '诗', 'shi', '', NULL, '汶陽客舍 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38fb89ea-cc8c-4de7-9767-fc353f9ca121', '留別崔澣秀才昆仲', '留別崔澣秀才昆仲', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["汶陽離思水無窮，去住情深夢寐中。","歲晚蟲鳴寒露草，日西蟬噪古槐風。","川分遠岳秋光靜，雲盡遙天霽色空。","對酒不能傷此別，尺書憑鴈往來通。"]', '["汶陽離思水無窮，去住情深梦寐中。","歲晚蟲鳴寒露草，日西蟬噪古槐风。","川分远岳秋光静，云尽遙天霽色空。","对酒不能傷此別，尺书憑鴈往来通。"]', '诗', 'shi', '', NULL, '留別崔澣秀才昆仲 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e12693a4-5d53-4192-9184-6df4a81f82a8', '和友人憶洞庭舊居', '和友人憶洞庭旧居', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["客舍經時益苦吟，洞庭猶憶在前林。","青山殘月有歸夢，碧落片雲生遠心。","谿路煙開江月出，草堂門掩海濤深。","因君話舊起愁思，隔水數聲何處砧。"]', '["客舍經时益苦吟，洞庭猶憶在前林。","青山殘月有归梦，碧落片云生远心。","谿路煙开江月出，草堂门掩海濤深。","因君話旧起愁思，隔水數声何处砧。"]', '诗', 'shi', '', NULL, '和友人憶洞庭舊居 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('720d3b21-625c-4afc-a1e2-0c562d710854', '晚歸山居', '晚归山居', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["寥落霜空木葉稀，初行郊野思依依。","秋深頻憶故鄉事，日暮獨尋荒徑歸。","山影暗隨雲水動，鐘聲潛入遠煙微。","娟娟唯有西林月，不惜清光照竹扉。"]', '["寥落霜空木葉稀，初行郊野思依依。","秋深頻憶故乡事，日暮独尋荒徑归。","山影暗隨云水动，鐘声潛入远煙微。","娟娟唯有西林月，不惜清光照竹扉。"]', '诗', 'shi', '', NULL, '晚歸山居 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed0d2f36-a9ab-4c52-8e29-9683e928980b', '送元敘上人歸上黨', '送元敘上人归上黨', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["太行關路戰塵收，白日思鄉別沃州。","薄暮焚香臨野燒，清晨漱齒涉寒流。","谿邊殘壘空雲木，山上孤城對驛樓。","此去寂寥尋舊跡，蒼苔滿徑竹齋秋。"]', '["太行关路戰塵收，白日思乡別沃州。","薄暮焚香臨野燒，清晨漱齒涉寒流。","谿邊殘壘空云木，山上孤城对驛楼。","此去寂寥尋旧跡，蒼苔满徑竹斋秋。"]', '诗', 'shi', '', NULL, '送元敘上人歸上黨 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d2c1fd7-dc84-4917-9635-ab4db4e69925', '秋日旅途即事', '秋日旅途即事', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["驅羸多自感，煙草遠郊平。","鄉路幾時盡，旅人終日行。","渡邊寒水驛，山下夕陽城。","蕭索更何有，秋風兩鬢生。"]', '["驱羸多自感，煙草远郊平。","乡路幾时尽，旅人終日行。","渡邊寒水驛，山下夕陽城。","蕭索更何有，秋风兩鬢生。"]', '诗', 'shi', '', NULL, '秋日旅途即事 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56af8c09-9fa9-472c-a0a3-7ba139c6f41f', '早行', '早行', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["旅途乘早景，策馬獨淒淒。","殘影郡樓月，一聲關樹雞。","聽鐘煙柳外，問渡水雲西。","當自勉行役，終期功業齊。"]', '["旅途乘早景，策马独淒淒。","殘影郡楼月，一声关樹雞。","听鐘煙柳外，问渡水云西。","當自勉行役，終期功業齊。"]', '诗', 'shi', '', NULL, '早行 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9c843c3-038b-4067-94f7-f3a4762b06c7', '句', '句', '22083c4c-18a5-4b5d-b1dd-24388e695526', '唐', '["海曙雲浮日，江遙水合天。"]', '["海曙云浮日，江遙水合天。"]', '诗', 'shi', '', NULL, '句 劉滄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04bd7671-1369-41bc-be49-19218e7875c1', '湘口送友人', '湘口送友人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["中流欲暮見湘煙，葦岸無窮接楚田。","去雁遠衝雲夢雪，離人獨上洞庭船。","風波盡日依山轉，星漢通霄向水連。","零落梅花過殘臘，故園歸醉及新年。"]', '["中流欲暮见湘煙，葦岸無窮接楚田。","去雁远衝云梦雪，離人独上洞庭船。","风波尽日依山轉，星漢通霄向水連。","零落梅花過殘臘，故园归醉及新年。"]', '诗', 'shi', '', NULL, '湘口送友人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24338aa9-e2dd-4f66-88c7-a428b439f972', '鄂州頭陀寺上方', '鄂州头陀寺上方', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["高寺上方無不見，天涯行客思迢迢。","西江帆挂東風急，夏口城銜楚塞遙。","沙渚漁歸多濕網，桑林蠶後盡空條。","感時歎物尋僧話，惟向禪心得寂寥。"]', '["高寺上方無不见，天涯行客思迢迢。","西江帆挂东风急，夏口城銜楚塞遙。","沙渚漁归多濕網，桑林蠶後尽空條。","感时歎物尋僧話，惟向禪心得寂寥。"]', '诗', 'shi', '', NULL, '鄂州頭陀寺上方 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efe9c2e2-8557-4eb4-921d-09fa4a85b844', '寄遠', '寄远', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["槐欲成陰分袂時，君期十日復金扉。","槐今落葉已將盡，君向遠鄉猶未歸。","化石早曾聞節婦，沈湘何必獨靈妃。","須知此意同生死，不學他人空寄衣。"]', '["槐欲成陰分袂时，君期十日复金扉。","槐今落葉已將尽，君向远乡猶未归。","化石早曾闻節婦，沈湘何必独靈妃。","須知此意同生死，不学他人空寄衣。"]', '诗', 'shi', '', NULL, '寄遠 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3264e30-132f-4092-9865-ed5b41177101', '題張司馬別墅', '題張司马別墅', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["庭前樹盡手中栽，先後花分幾番開。","巢鳥戀雛驚不起，野人思酒去還來。","自拋官與青山近，誰訝身爲白髮催。","門外尋常行樂處，重重履跡在莓苔。"]', '["庭前樹尽手中栽，先後花分幾番开。","巢鸟戀雛驚不起，野人思酒去還来。","自拋官與青山近，誰訝身爲白髮催。","门外尋常行乐处，重重履跡在莓苔。"]', '诗', 'shi', '', NULL, '題張司馬別墅 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d79017c4-a642-4a8c-9530-f5154251f186', '長安即事', '长安即事', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["長遇豪家不敢過，此身誰與取高科。","故園久絕書來後，南國空看雁去多。","中夜永懷聽疊漏，先秋歸夢涉層波。","愁人白髮自生早，我獨少年能幾何。"]', '["长遇豪家不敢過，此身誰與取高科。","故园久絕书来後，南国空看雁去多。","中夜永懷听叠漏，先秋归梦涉層波。","愁人白髮自生早，我独少年能幾何。"]', '诗', 'shi', '', NULL, '長安即事 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4652d3-11ae-4259-a197-3c067c6ea45d', '漢上逢同年崔八', '漢上逢同年崔八', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["去歲曾遊帝里春，杏花開過各離秦。","偶先託質逢知己，獨未還家作旅人。","世上路岐何繚繞，空中光景自逡巡。","一回相見一回別，能得幾時年少身。"]', '["去歲曾游帝里春，杏花开過各離秦。","偶先託質逢知己，独未還家作旅人。","世上路岐何繚繞，空中光景自逡巡。","一回相见一回別，能得幾时年少身。"]', '诗', 'shi', '', NULL, '漢上逢同年崔八 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d62506eb-9ad7-459b-8530-d67e98c4ec6f', '五月一日蒙替本官不得隨例入關感懷獻送相公', '五月一日蒙替本官不得隨例入关感懷獻送相公', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["五月傾朝謁紫宸，一朝無分在清塵。","含香已去星郎位，衣錦惟思婺女隣。","折獄也曾爲俗吏，勸農元本是耕人。","知將何事酬公道，只養生靈似養身。"]', '["五月傾朝謁紫宸，一朝無分在清塵。","含香已去星郎位，衣錦惟思婺女隣。","折獄也曾爲俗吏，勸農元本是耕人。","知將何事酬公道，只養生靈似養身。"]', '诗', 'shi', '', NULL, '五月一日蒙替本官不得隨例入關感懷獻送相公 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67525be2-4a58-43e0-89f7-82233e656e0d', '春閨怨', '春閨怨', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["紅妝女兒燈下羞，畫眉夫壻隴西頭。","自怨愁容長照鏡，悔教征戍覓封侯。"]', '["紅妝女兒灯下羞，畫眉夫壻隴西头。","自怨愁容长照镜，悔教征戍覓封侯。"]', '诗', 'shi', '', NULL, '春閨怨 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fadacf88-90f0-4646-9fe1-24a5375b4695', '送邊將', '送邊將', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["防秋戎馬恐來奔，詔發將軍出雁門。","遙領短兵登隴首，獨橫長劒向河源。","悠揚落日黃雲動，蒼莽陰風白草翻。","若縱干戈更深入，應聞收得到崑崙。"]', '["防秋戎马恐来奔，詔發將軍出雁门。","遙領短兵登隴首，独橫长劒向河源。","悠揚落日黄云动，蒼莽陰风白草翻。","若縱干戈更深入，應闻收得到崑崙。"]', '诗', 'shi', '', NULL, '送邊將 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05e62bae-2725-4214-b748-0c1d2a95b35a', '太和公主還宮', '太和公主還宮', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["天驕發使犯邊塵，漢將推功遂奪親。","離亂應無初去貌，死生難有却回身。","禁花半老曾攀樹，宮女多非舊識人。","重上鳳樓追故事，幾多愁思向青春。"]', '["天驕發使犯邊塵，漢將推功遂奪親。","離亂應無初去貌，死生难有却回身。","禁花半老曾攀樹，宮女多非旧識人。","重上鳳楼追故事，幾多愁思向青春。"]', '诗', 'shi', '', NULL, '太和公主還宮 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('213d56b8-731e-457b-86a0-8028e4b5b296', '將赴黔州先寄本府中丞', '將赴黔州先寄本府中丞', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["八月瞿塘到底翻，孤舟上得已銷魂。","幕中職罷猶趨府，闕下官成未謝恩。","丹嶂聳空無過鳥，青林覆水有垂猿。","感知肺腑終難說，從此辭歸便掃門。"]', '["八月瞿塘到底翻，孤舟上得已銷魂。","幕中職罷猶趨府，闕下官成未謝恩。","丹嶂聳空無過鸟，青林覆水有垂猿。","感知肺腑終难说，從此辞归便掃门。"]', '诗', 'shi', '', NULL, '將赴黔州先寄本府中丞 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('728a6ee3-4675-4f41-9241-869bab7b7378', '和友人下第北遊感懷', '和友人下第北游感懷', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["聖代爲儒可致身，誰知又別五陵春。","青門獨出空歸鳥，紫陌相逢盡醉人。","江島去尋垂釣遠，塞山來見舉頭頻。","且須共漉邊城酒，何必陶家有白綸。"]', '["聖代爲儒可致身，誰知又別五陵春。","青门独出空归鸟，紫陌相逢尽醉人。","江島去尋垂釣远，塞山来见舉头頻。","且須共漉邊城酒，何必陶家有白綸。"]', '诗', 'shi', '', NULL, '和友人下第北遊感懷 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855d07f6-c3dd-4db9-8826-8f4c52ae78ae', '樂遊原春望', '乐游原春望', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["五陵佳氣晚氛氳，霸業雄圖勢自分。","秦地山河連楚塞，漢家宮殿入青雲。","未央樹色春中見，長樂鐘聲月下聞。","無那楊華起愁思，滿天飄落雪紛紛。"]', '["五陵佳氣晚氛氳，霸業雄圖勢自分。","秦地山河連楚塞，漢家宮殿入青云。","未央樹色春中见，长乐鐘声月下闻。","無那楊华起愁思，满天飄落雪紛紛。"]', '诗', 'shi', '', NULL, '樂遊原春望 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b9a0b2-efa7-4f59-9fb8-d1eb9a6ac491', '黃雀行', '黄雀行', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["欲竊高倉集御河，翩翩疑渡畏秋波。","朱宮晚樹侵鶯語，畫閣香簾奪燕窠。","疎影暗棲寒露重，空城飢噪暮煙多。","誰令不解高飛去，破宅荒庭有網羅。"]', '["欲竊高倉集御河，翩翩疑渡畏秋波。","朱宮晚樹侵鶯語，畫閣香簾奪燕窠。","疎影暗棲寒露重，空城飢噪暮煙多。","誰令不解高飞去，破宅荒庭有網羅。"]', '诗', 'shi', '', NULL, '黃雀行 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e362f7-6a68-4246-973c-5a42917ce8a6', '長安寓居寄柏侍郎', '长安寓居寄柏侍郎', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["霜輕兩鬢欲相侵，愁緒無端不可尋。","秦女紅妝空覓伴，郢郎白雪少知音。","長亭古木春光老，太華青煙晚更深。","獨向灞陵東北望，一封書寄萬重心。"]', '["霜轻兩鬢欲相侵，愁緒無端不可尋。","秦女紅妝空覓伴，郢郎白雪少知音。","长亭古木春光老，太华青煙晚更深。","独向灞陵东北望，一封书寄万重心。"]', '诗', 'shi', '', NULL, '長安寓居寄柏侍郎 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1365c1c9-e864-4920-ba10-d3815a59f6b7', '春日思歸', '春日思归', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["春情不斷若連環，一夕思歸鬢欲斑。","壯志未酬三尺劒，故鄉空隔萬重山。","音書斷絕干戈後，親友相逢夢寐間。","却羨浮雲與飛鳥，因風吹去又吹還。"]', '["春情不斷若連环，一夕思归鬢欲斑。","壯志未酬三尺劒，故乡空隔万重山。","音书斷絕干戈後，親友相逢梦寐间。","却羨浮云與飞鸟，因风吹去又吹還。"]', '诗', 'shi', '', NULL, '春日思歸 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d811f847-2b34-492a-bcd5-4c7fce32d655', '朔中即事', '朔中即事', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["關門南北雜戎夷，草木秋來即出師。","落日風沙長暝早，窮冬雨雪轉春遲。","山頭堠火孤明後，星外行人四絕時。","自古邊功何不立，漢家中外自相疑。"]', '["关门南北杂戎夷，草木秋来即出師。","落日风沙长暝早，窮冬雨雪轉春遲。","山头堠火孤明後，星外行人四絕时。","自古邊功何不立，漢家中外自相疑。"]', '诗', 'shi', '', NULL, '朔中即事 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfcd053a-1279-4ec4-a5f0-660acdc4be20', '感懷獻門下相公', '感懷獻门下相公', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["誰云郎選不由詩，上相憐才積有時。","却是龍鍾到門晚，終非稽古致身遲。","謀將郡印歸難遂，讀著家書坐欲癡。","日望南宮看列宿，迢迢婺女與鄉比。"]', '["誰云郎選不由诗，上相怜才積有时。","却是龙鍾到门晚，終非稽古致身遲。","謀將郡印归难遂，读著家书坐欲癡。","日望南宮看列宿，迢迢婺女與乡比。"]', '诗', 'shi', '', NULL, '感懷獻門下相公 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d00b15a6-0ff1-41f2-9809-d3e0d5f169ab', '贈長城庾將軍', '贈长城庾將軍', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["初年三十拜將軍，近代英雄獨未聞。","向國報恩心比石，辭天作鎮氣凌雲。","逆風走馬貂裘卷，望塞懸弧雁陣分。","定擁節麾從此去，安西大破犬戎羣。"]', '["初年三十拜將軍，近代英雄独未闻。","向国報恩心比石，辞天作鎮氣凌云。","逆风走马貂裘卷，望塞懸弧雁陣分。","定擁節麾從此去，安西大破犬戎羣。"]', '诗', 'shi', '', NULL, '贈長城庾將軍 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7faa7ba0-8ac0-4161-a239-1ea27a742bf1', '浙東獻鄭大夫', '浙东獻鄭大夫', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["聖主東憂漲海濱，思移副相倚陶鈞。","樓臺獨坐江山月，舟楫先行澤國春。","遙想萬家開戶外，近聞羣盜竄諸鄰。","幾時入去調元化，天下同爲堯舜人。"]', '["聖主东憂漲海濱，思移副相倚陶鈞。","楼台独坐江山月，舟楫先行澤国春。","遙想万家开戶外，近闻羣盜竄諸鄰。","幾时入去調元化，天下同爲堯舜人。"]', '诗', 'shi', '', NULL, '浙東獻鄭大夫 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd0ed4a4-35c3-4073-a035-9de286a41877', '鏡湖夜泊有懷', '镜湖夜泊有懷', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["廣水遙隄利物功，因思太守惠無窮。","自從版築興農隙，長與耕耘致歲豐。","漲接星津流蕩漾，寬浮雲岫動虛空。","想當戰國開時有，范蠡扁舟祗此中。"]', '["廣水遙隄利物功，因思太守惠無窮。","自從版築兴農隙，长與耕耘致歲豐。","漲接星津流蕩漾，寬浮云岫动虛空。","想當戰国开时有，范蠡扁舟祗此中。"]', '诗', 'shi', '', NULL, '鏡湖夜泊有懷 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9b7ddd-99dd-48aa-8a4f-4cc1453f868f', '宣州獻從叔大夫', '宣州獻從叔大夫', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["清時選地任賢明，從此觀風輟尹京。","日月天中辭洛邑，雲山江上領宣城。","萬家閭井俱安寢，千里農桑竟起耕。","聞說聖朝同漢代，已愁徵入拜公卿。"]', '["清时選地任賢明，從此观风輟尹京。","日月天中辞洛邑，云山江上領宣城。","万家閭井俱安寢，千里農桑竟起耕。","闻说聖朝同漢代，已愁徵入拜公卿。"]', '诗', 'shi', '', NULL, '宣州獻從叔大夫 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('509dffc1-7403-4bd8-832c-0c2c5dc0ba73', '賀同年翰林從叔舍人知制誥', '賀同年翰林從叔舍人知制誥', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["仙禁何人躡近蹤，孔門先選得真龍。","別居雲路拋三省，專掌天書在九重。","五色毫揮成渙汗，百寮班下獨從容。","芳年貴盛誰爲比，鬱鬱青青嶽頂松。"]', '["仙禁何人躡近蹤，孔门先選得真龙。","別居云路拋三省，專掌天书在九重。","五色毫揮成渙汗，百寮班下独從容。","芳年貴盛誰爲比，鬱鬱青青嶽頂松。"]', '诗', 'shi', '', NULL, '賀同年翰林從叔舍人知制誥 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf7b90af-99c1-45ea-a310-6427dbc01346', '吳門別主人', '吳门別主人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["早晚更看吳苑月，小齋長憶落西窗。","不知明夜誰家見，應照離人隔楚江。"]', '["早晚更看吳苑月，小斋长憶落西窗。","不知明夜誰家见，應照離人隔楚江。"]', '诗', 'shi', '', NULL, '吳門別主人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c15c44-c312-4f62-8b94-8b29728d2bd7', '自黔中歸新安', '自黔中归新安', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["朝過春關辭北闕，暮參戎幕向南巴。","却將仙桂東歸去，江月相隨直到家。"]', '["朝過春关辞北闕，暮參戎幕向南巴。","却將仙桂东归去，江月相隨直到家。"]', '诗', 'shi', '', NULL, '自黔中歸新安 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bf0ebcf-f51c-4992-9fc2-da994b1709f0', '奉和鄭薰相公', '奉和鄭薰相公', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["三四株松匝草亭，便成彭澤柳爲名。","蓮峰隱去難辭闕，滻水朝回與出城。"]', '["三四株松匝草亭，便成彭澤柳爲名。","蓮峰隐去难辞闕，滻水朝回與出城。"]', '诗', 'shi', '', NULL, '奉和鄭薰相公 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3d8be3-6769-4323-a143-2cf1abd75a5a', '及第後還家過峴嶺', '及第後還家過峴嶺', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["魏馱山前一朵花，嶺西更有幾千家。","石斑魚鮓香衝鼻，淺水沙田飯遶牙。"]', '["魏馱山前一朵花，嶺西更有幾千家。","石斑鱼鮓香衝鼻，淺水沙田飯遶牙。"]', '诗', 'shi', '', NULL, '及第後還家過峴嶺 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32fe510a-b564-44ec-a96c-bb030d00dc26', '春日旅舍', '春日旅舍', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["未識東西南北路，青春白日坐銷難。","如何一別故園後，五度花開五處看。"]', '["未識东西南北路，青春白日坐銷难。","如何一別故园後，五度花开五处看。"]', '诗', 'shi', '', NULL, '春日旅舍 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf08652f-2676-4b32-aa0b-06e2e2598360', '過長江傷賈島', '過长江傷賈島', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["忽從一宦遠流離，無罪無人子細知。","到得長江聞杜宇，想君魂魄也相隨。"]', '["忽從一宦远流離，無罪無人子細知。","到得长江闻杜宇，想君魂魄也相隨。"]', '诗', 'shi', '', NULL, '過長江傷賈島 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d1b277a-e957-4239-a463-48f51006ce9e', '自遣', '自遣', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["永擬東歸把釣絲，將行忽起半心疑。","青雲道是不平地，還有平人上得時。"]', '["永擬东归把釣絲，將行忽起半心疑。","青云道是不平地，還有平人上得时。"]', '诗', 'shi', '', NULL, '自遣 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('242b5624-6d24-4343-a9c9-c454ab4ccea1', '寄曹鄴', '寄曹鄴', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["終南山是枕前雲，禁鼓無因曉夜聞。","朝客秋來不朝日，曲江西岸去尋君。"]', '["終南山是枕前云，禁鼓無因晓夜闻。","朝客秋来不朝日，曲江西岸去尋君。"]', '诗', 'shi', '', NULL, '寄曹鄴 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c13d4be-6e7b-479c-acef-bc6bf9bc3152', '述懷', '述懷', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["望月疑無得桂緣，春天又待到秋天。","杏花開與槐花落，愁去愁來過幾年。"]', '["望月疑無得桂緣，春天又待到秋天。","杏花开與槐花落，愁去愁来過幾年。"]', '诗', 'shi', '', NULL, '述懷 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a464a5e1-e2de-4983-a0b8-15959fcd5918', '客洛酬劉駕', '客洛酬劉駕', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["浮世總應相送老，共君偏更遠行多。","此回不似前回別，聽盡離歌逐櫂歌。"]', '["浮世總應相送老，共君偏更远行多。","此回不似前回別，听尽離歌逐櫂歌。"]', '诗', 'shi', '', NULL, '客洛酬劉駕 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('587da2a0-98fd-4e9d-8aa7-0997e703e274', '題釣臺障子', '題釣台障子', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["君家盡是我家山，嚴子前臺枕古灣。","却把釣竿終不可，幾時入海得魚還。"]', '["君家尽是我家山，嚴子前台枕古灣。","却把釣竿終不可，幾时入海得鱼還。"]', '诗', 'shi', '', NULL, '題釣臺障子 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f44ae051-cd72-4228-ab45-387873ef7048', '題陽山顧煉師草堂', '題陽山顧煉師草堂', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["若到當時上升處，長生何事後無人。","前峰自去種松子，坐見年來取茯神。"]', '["若到當时上升处，长生何事後無人。","前峰自去種松子，坐见年来取茯神。"]', '诗', 'shi', '', NULL, '題陽山顧煉師草堂 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b39d401d-2b24-4334-8dbc-6f9b900a1ad9', '聞金吾妓唱梁州', '闻金吾妓唱梁州', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["聞君一曲古梁州，驚起黃雲塞上愁。","秦女樹前花正發，北風吹落滿城秋。"]', '["闻君一曲古梁州，驚起黄云塞上愁。","秦女樹前花正發，北风吹落满城秋。"]', '诗', 'shi', '', NULL, '聞金吾妓唱梁州 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59b65da7-9042-46ab-900c-208887bd5d77', '游蜀回簡友人', '游蜀回簡友人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["別來十二月，去到漏天邊。","不是因逢閏，還應是隔年。"]', '["別来十二月，去到漏天邊。","不是因逢閏，還應是隔年。"]', '诗', 'shi', '', NULL, '游蜀回簡友人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac8b41f2-0397-4224-acf8-aad23eafbaf7', '贈涇州王侍御', '贈涇州王侍御', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["一旦天書下紫微，三年旌斾隴雲飛。","塞門無事春空到，邊草青青戰馬肥。"]', '["一旦天书下紫微，三年旌斾隴云飞。","塞门無事春空到，邊草青青戰马肥。"]', '诗', 'shi', '', NULL, '贈涇州王侍御 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f461e230-d7d0-4ca4-affc-0c04e1f023c1', '夏日宿秘書姚監宅', '夏日宿秘书姚監宅', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["貴宅多嘉樹，先秋有好風。","情閑離闕下，夢野在山中。","露色浮寒瓦，螢光墮暗叢。","聽吟麗句盡，河漢任西東。"]', '["貴宅多嘉樹，先秋有好风。","情闲離闕下，梦野在山中。","露色浮寒瓦，螢光墮暗叢。","听吟丽句尽，河漢任西东。"]', '诗', 'shi', '', NULL, '夏日宿秘書姚監宅 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('445828e8-03de-470d-9d49-058d069224cf', '過嵩陰隱者', '過嵩陰隐者', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["當門看少室，倚杖復披衣。","每日醒還醉，無人是與非。","架書抽讀亂，庭果摘嘗稀。","獨有江南客，思家未得歸。"]', '["當门看少室，倚杖复披衣。","每日醒還醉，無人是與非。","架书抽读亂，庭果摘嘗稀。","独有江南客，思家未得归。"]', '诗', 'shi', '', NULL, '過嵩陰隱者 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('781eb8bd-dd5f-41a6-b861-e5dcd64ceb4f', '留別山家', '留別山家', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["閑門不易求，半月在林丘。","已與山水別，難爲花木留。","孤懷歸靜夜，遠會隔高秋。","莫道無言去，冥心在重遊。"]', '["闲门不易求，半月在林丘。","已與山水別，难爲花木留。","孤懷归静夜，远會隔高秋。","莫道無言去，冥心在重游。"]', '诗', 'shi', '', NULL, '留別山家 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95842962-291c-4806-a919-d6a1f724fe76', '送人遊吳', '送人游吳', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["楚田開雪後，草色與君看。","積水浮春氣，深山滯雨寒。","毗陵孤月出，建業一鍾殘。","爲把鄉書去，因收別淚難。"]', '["楚田开雪後，草色與君看。","積水浮春氣，深山滯雨寒。","毗陵孤月出，建業一鍾殘。","爲把乡书去，因收別泪难。"]', '诗', 'shi', '', NULL, '送人遊吳 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2288d47-90d0-45f9-b234-7be5b71baa06', '東渭橋晚眺', '东渭橋晚眺', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["秦地有吳洲，千檣渭曲頭。","人當返照立，水徹故鄉流。","落第春難過，窮途日易愁。","誰知橋上思，萬里在江樓。"]', '["秦地有吳洲，千檣渭曲头。","人當返照立，水徹故乡流。","落第春难過，窮途日易愁。","誰知橋上思，万里在江楼。"]', '诗', 'shi', '', NULL, '東渭橋晚眺 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a32b1d71-503b-40fe-815f-34f57634b1fd', '送延陵韋少府', '送延陵韋少府', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["延陵稱貴邑，季子有高蹤。","古跡傳多代，仙山管幾峰。","微泉聲小雨，異木色深冬。","去畢三年秩，新詩篋不容。"]', '["延陵稱貴邑，季子有高蹤。","古跡傳多代，仙山管幾峰。","微泉声小雨，異木色深冬。","去畢三年秩，新诗篋不容。"]', '诗', 'shi', '', NULL, '送延陵韋少府 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32eb0c05-87d7-4ae6-93c9-9591053781d1', '淮南送友人歸滄州', '淮南送友人归滄州', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["風色忽西轉，坐爲千里分。","高帆背楚落，寒日逆淮曛。","斷燒緣喬木，盤鵰隱片雲。","鄉關百戰地，歸去始休軍。"]', '["风色忽西轉，坐爲千里分。","高帆背楚落，寒日逆淮曛。","斷燒緣喬木，盤鵰隐片云。","乡关百戰地，归去始休軍。"]', '诗', 'shi', '', NULL, '淮南送友人歸滄州 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90a8ce29-80e0-4b64-816c-e08bed5fcdc5', '夏日題盩厔友人書齋', '夏日題盩厔友人书斋', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["脩竹齊高樹，書齋竹樹中。","四時無夏氣，三伏有秋風。","黑處巢幽鳥，陰來呌候蟲。","牕西太白雪，萬仞在遙空。"]', '["脩竹齊高樹，书斋竹樹中。","四时無夏氣，三伏有秋风。","黑处巢幽鸟，陰来呌候蟲。","牕西太白雪，万仞在遙空。"]', '诗', 'shi', '', NULL, '夏日題盩厔友人書齋 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe92f8bf-6625-4176-9181-87b6daefff0f', '尋山', '尋山', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["一逕入雙崖，初疑有幾家。","行窮人不見，坐久日空斜。","石上生靈草，泉中落異花。","終須結茅屋，向此學餐霞。"]', '["一逕入雙崖，初疑有幾家。","行窮人不见，坐久日空斜。","石上生靈草，泉中落異花。","終須結茅屋，向此学餐霞。"]', '诗', 'shi', '', NULL, '尋山 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('976867e2-eff6-4564-aedd-e18746e40412', '送元遂上人歸錢唐', '送元遂上人归錢唐', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["白衣遊帝鄉，已得事空王。","却返湖山寺，高禪水月房。","雨中過嶽黑，秋後宿船涼。","回顧秦人語，他生會別方。"]', '["白衣游帝乡，已得事空王。","却返湖山寺，高禪水月房。","雨中過嶽黑，秋後宿船涼。","回顧秦人語，他生會別方。"]', '诗', 'shi', '', NULL, '送元遂上人歸錢唐 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1654f5f8-7d7a-4f77-ac54-547190adb31b', '貽友人喻坦之', '貽友人喻坦之', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["從容心自切，飲水勝銜杯。","共在山中長，相隨闕下來。","脩身空有道，取事各無媒。","不信昇平代，終遺草澤才。"]', '["從容心自切，饮水勝銜杯。","共在山中长，相隨闕下来。","脩身空有道，取事各無媒。","不信昇平代，終遺草澤才。"]', '诗', 'shi', '', NULL, '貽友人喻坦之 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98f136cd-d526-494e-9e12-4e8d214c1050', '送友人往振武', '送友人往振武', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["風沙遙見說，道路替君愁。","磧夜星垂地，雲明火上樓。","征鴻辭塞雪，戰馬識邊秋。","不共將軍語，何因有去留。"]', '["风沙遙见说，道路替君愁。","磧夜星垂地，云明火上楼。","征鴻辞塞雪，戰马識邊秋。","不共將軍語，何因有去留。"]', '诗', 'shi', '', NULL, '送友人往振武 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5bab627-dacc-490a-9ef4-f8bd1e531aed', '賦得長城斑竹杖', '賦得长城斑竹杖', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["秦興版築時，翦伐不知誰。","異代餘根在，幽人得手持。","細看生古意，閑倚動邊思。","莫作鳩形並，空將鶴髪期。"]', '["秦兴版築时，翦伐不知誰。","異代餘根在，幽人得手持。","細看生古意，闲倚动邊思。","莫作鳩形並，空將鹤髪期。"]', '诗', 'shi', '', NULL, '賦得長城斑竹杖 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6877c51-bc71-43cb-862c-44bcd0aefe71', '送德清喻明府', '送德清喻明府', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["棹返霅溪雲，仍參舊使君。","州傳多古跡，縣記是新文。","水柵橫舟閉，湖田立木分。","但如詩思苦，爲政即超羣。"]', '["棹返霅溪云，仍參旧使君。","州傳多古跡，縣記是新文。","水柵橫舟閉，湖田立木分。","但如诗思苦，爲政即超羣。"]', '诗', 'shi', '', NULL, '送德清喻明府 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d290779b-b471-47cc-a54d-c0a273a0fb71', '送薛能少府任盩厔', '送薛能少府任盩厔', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["不才甘下第，君子蹇何重。","相送昆明岸，同看太白峰。","數瓢留頃刻，殘照迫從容。","好去煙霞縣，仙人有舊蹤。"]', '["不才甘下第，君子蹇何重。","相送昆明岸，同看太白峰。","數瓢留頃刻，殘照迫從容。","好去煙霞縣，仙人有旧蹤。"]', '诗', 'shi', '', NULL, '送薛能少府任盩厔 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd4113da-c577-4737-9506-2c4e6216e973', '送許壽下第歸東山', '送許壽下第归东山', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["吾君設禮闈，誰合學忘機。","却是高人起，難爲下第歸。","出關心縱野，避世事終稀。","莫更今秋夕，相思望少微。"]', '["吾君設禮闈，誰合学忘機。","却是高人起，难爲下第归。","出关心縱野，避世事終稀。","莫更今秋夕，相思望少微。"]', '诗', 'shi', '', NULL, '送許壽下第歸東山 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7ebd106-c322-4bd9-8bd2-5882ecb5be8c', '冬夜酬范秘書', '冬夜酬范秘书', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["九衢行一匝，不敢入他門。","累日無餘事，通宵得至言。","命嗟清世蹇，春覺閏冬暄。","翻覆吟佳句，何酬國士恩。"]', '["九衢行一匝，不敢入他门。","累日無餘事，通宵得至言。","命嗟清世蹇，春覺閏冬暄。","翻覆吟佳句，何酬国士恩。"]', '诗', 'shi', '', NULL, '冬夜酬范秘書 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40a6b1bd-cca2-481e-80a5-a4bd4e123674', '送陸肱尉江夏', '送陸肱尉江夏', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["如何執簡去，便作挂帆期。","澤國三春早，江天落日遲。","縣人齊候處，洲鳥欲飛時。","免褐方三十，青雲豈白髭。"]', '["如何執簡去，便作挂帆期。","澤国三春早，江天落日遲。","縣人齊候处，洲鸟欲飞时。","免褐方三十，青云豈白髭。"]', '诗', 'shi', '', NULL, '送陸肱尉江夏 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a0932d-af0b-45a3-bb19-1f9a805e893d', '漢上送人西歸', '漢上送人西归', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["幾作西歸夢，因爲愴別心。","野銜天去盡，山夾漢來深。","疊浪翻殘照，高帆引片陰。","空留相贈句，畢我白頭吟。"]', '["幾作西归梦，因爲愴別心。","野銜天去尽，山夾漢来深。","叠浪翻殘照，高帆引片陰。","空留相贈句，畢我白头吟。"]', '诗', 'shi', '', NULL, '漢上送人西歸 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6a0cb5e-d8f1-4990-82ce-a7a2db1463c5', '蜀中逢友人', '蜀中逢友人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["自古有行役，誰人免別家。","相歡猶陌上，一醉任天涯。","積疊山藏蜀，潺湲水遶巴。","他年復何處，共說海棠花。"]', '["自古有行役，誰人免別家。","相歡猶陌上，一醉任天涯。","積叠山藏蜀，潺湲水遶巴。","他年复何处，共说海棠花。"]', '诗', 'shi', '', NULL, '蜀中逢友人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde2d1ee-925d-47d6-b2c4-d91f61567233', '寄范評事', '寄范評事', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["行坐不相遺，轅門載筆時。","雅知難更遇，舊分合長思。","夢即重尋熟，書常轉達遲。","山齋終擬到，何日遂心期。"]', '["行坐不相遺，轅门載笔时。","雅知难更遇，旧分合长思。","梦即重尋熟，书常轉達遲。","山斋終擬到，何日遂心期。"]', '诗', 'shi', '', NULL, '寄范評事 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('475cd9a9-a45e-4373-8751-c912c34b8ecc', '南遊過湘漢即事寄友人', '南游過湘漢即事寄友人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["南去遠駈逐，三湘五月行。","巴山雪水下，楚澤火雲生。","向野聊中飯，乘涼探暮程。","離懷不可說，已迫峽猿聲。"]', '["南去远駈逐，三湘五月行。","巴山雪水下，楚澤火云生。","向野聊中飯，乘涼探暮程。","離懷不可说，已迫峽猿声。"]', '诗', 'shi', '', NULL, '南遊過湘漢即事寄友人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2903b681-6554-43e0-aca0-c47ff4d92b5d', '送許渾侍御赴潤州', '送許渾侍御赴潤州', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["家山近石頭，遂意恣東遊。","祖席離烏府，歸帆轉蜃樓。","陰氛出海散，落月向潮流。","別有爲霖日，孤雲未自由。"]', '["家山近石头，遂意恣东游。","祖席離烏府，归帆轉蜃楼。","陰氛出海散，落月向潮流。","別有爲霖日，孤云未自由。"]', '诗', 'shi', '', NULL, '送許渾侍御赴潤州 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2670d667-46e7-4c1e-ba5c-66545ca5ea78', '喜友人厲圖南及第', '喜友人厲圖南及第', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["相憂過己切，相賀似身榮。","心達無前後，神交共死生。","承家吾子事，登第世人情。","未有通儒術，明時道不行。"]', '["相憂過己切，相賀似身榮。","心達無前後，神交共死生。","承家吾子事，登第世人情。","未有通儒術，明时道不行。"]', '诗', 'shi', '', NULL, '喜友人厲圖南及第 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f89f90-993d-42f2-929b-86f13c94cc0b', '送友人下第歸越', '送友人下第归越', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["歸意隨流水，江湖共在東。","山陰何處去，草際片帆通。","雨色春愁裏，潮聲曉夢中。","雖爲半年客，便是往來鴻。"]', '["归意隨流水，江湖共在东。","山陰何处去，草際片帆通。","雨色春愁裏，潮声晓梦中。","雖爲半年客，便是往来鴻。"]', '诗', 'shi', '', NULL, '送友人下第歸越 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9391df0b-42e8-4911-a908-611f0bd2cb81', '寄友人', '寄友人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["一別一相見，須臾老此生。","客衣寒後薄，山思夜深清。","詩近吟何句，髭新白幾莖。","路岐如昨日，來往夢分明。"]', '["一別一相见，須臾老此生。","客衣寒後薄，山思夜深清。","诗近吟何句，髭新白幾莖。","路岐如昨日，来往梦分明。"]', '诗', 'shi', '', NULL, '寄友人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db446d59-91e0-41d2-bd74-08d1cccc9875', '送友人下第歸宛陵', '送友人下第归宛陵', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["天涯長戀親，闕下獨傷春。","擬住還求己，須歸不爲身。","臨岐仍犯雪，挂席始離塵。","共泣東風別，同爲滄海人。"]', '["天涯长戀親，闕下独傷春。","擬住還求己，須归不爲身。","臨岐仍犯雪，挂席始離塵。","共泣东风別，同爲滄海人。"]', '诗', 'shi', '', NULL, '送友人下第歸宛陵 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efad0020-1e72-4b9c-8188-3c837774eb00', '秋夜對月寄鳯翔范書記', '秋夜对月寄鳯翔范书記', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["月過秋霖後，光應夜夜清。","一回相憶起，幾度獨吟行。","河漢東西直，山川遠近明。","寸心遙往處，新有雁來聲。"]', '["月過秋霖後，光應夜夜清。","一回相憶起，幾度独吟行。","河漢东西直，山川远近明。","寸心遙往处，新有雁来声。"]', '诗', 'shi', '', NULL, '秋夜對月寄鳯翔范書記 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83abed08-d69f-4875-97b5-29655761f6e5', '送孫明秀才往潘州訪韋卿', '送孫明秀才往潘州訪韋卿', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["北鳥飛不到，北人今去遊。","天涯浮瘴水，嶺外問潘州。","草木春冬茂，猿猱日夜愁。","定知遷客淚，應只對君流。"]', '["北鸟飞不到，北人今去游。","天涯浮瘴水，嶺外问潘州。","草木春冬茂，猿猱日夜愁。","定知遷客泪，應只对君流。"]', '诗', 'shi', '', NULL, '送孫明秀才往潘州訪韋卿 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aefb57b-9047-481e-bcdb-8f90539babd4', '八月十五夜對月', '八月十五夜对月', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["陰盛此宵中，多爲雨與風。","坐無雲雨至，看與雪霜同。","抱濕離遙海，傾寒向逈空。","年年不可值，還似命難通。"]', '["陰盛此宵中，多爲雨與风。","坐無云雨至，看與雪霜同。","抱濕離遙海，傾寒向逈空。","年年不可值，還似命难通。"]', '诗', 'shi', '', NULL, '八月十五夜對月 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ce0030b-36a3-4228-a89e-dd2e6f249d44', '及第後歸', '及第後归', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["家臨浙水傍，岸對買臣鄉。","縱棹隨歸鳥，乘潮向夕陽。","苦吟身得雪，甘意鬢成霜。","況此年猶少，酬知足自強。"]', '["家臨浙水傍，岸对買臣乡。","縱棹隨归鸟，乘潮向夕陽。","苦吟身得雪，甘意鬢成霜。","況此年猶少，酬知足自強。"]', '诗', 'shi', '', NULL, '及第後歸 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00c9e09d-924f-4a1d-958f-e2520e17fce5', '過巫峽', '過巫峽', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["擁棹向驚湍，巫峰直上看。","削成從水底，聳出在雲端。","暮雨晴時少，啼猿渴下難。","一聞神女去，風竹掃空壇。"]', '["擁棹向驚湍，巫峰直上看。","削成從水底，聳出在云端。","暮雨晴时少，啼猿渴下难。","一闻神女去，风竹掃空壇。"]', '诗', 'shi', '', NULL, '過巫峽 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59a87e11-d975-40e1-bbd8-b8455f77d776', '送友人往太原', '送友人往太原', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["離亭聊把酒，此路徹邊頭。","草白雁來盡，時清人去遊。","汾河流晉地，塞雪滿幷州。","別後相思夜，空看北斗愁。"]', '["離亭聊把酒，此路徹邊头。","草白雁来尽，时清人去游。","汾河流晉地，塞雪满幷州。","別後相思夜，空看北斗愁。"]', '诗', 'shi', '', NULL, '送友人往太原 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa179ade-0b77-45de-a022-f51385e5b914', '旅懷', '旅懷', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["萬里共心論，徒言吾道存。","奉親無別業，謁帝有何門。","水宿驚濤浦，山行落葉村。","長安長夢去，欹枕即聞猿。"]', '["万里共心論，徒言吾道存。","奉親無別業，謁帝有何门。","水宿驚濤浦，山行落葉村。","长安长梦去，欹枕即闻猿。"]', '诗', 'shi', '', NULL, '旅懷 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('649279b6-2a63-4a6c-9605-c2a7bd348908', '送裴御史赴湖南', '送裴御史赴湖南', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["關門鳥道中，飛傳復乘驄。","暮雪離秦甸，春雲入楚宮。","平蕪天共闊，積水地多空。","使府懸帆去，能消幾日風。"]', '["关门鸟道中，飞傳复乘驄。","暮雪離秦甸，春云入楚宮。","平蕪天共闊，積水地多空。","使府懸帆去，能消幾日风。"]', '诗', 'shi', '', NULL, '送裴御史赴湖南 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad80de49-e92f-42af-825a-d4ddf3be6b4f', '送姚郜先輩赴汝州辟', '送姚郜先輩赴汝州辟', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["行李事寒天，東來聘禮全。","州當定鼎處，人去偃戈年。","雷雨依嵩嶺，桑麻接楚田。","遙知清夜作，不是借戎篇。"]', '["行李事寒天，东来聘禮全。","州當定鼎处，人去偃戈年。","雷雨依嵩嶺，桑麻接楚田。","遙知清夜作，不是借戎篇。"]', '诗', 'shi', '', NULL, '送姚郜先輩赴汝州辟 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1d38741-4714-4c25-b6d1-414368e2848e', '初離黔中泊江上', '初離黔中泊江上', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["去去把青桂，平生心不違。","更蒙蓮府辟，兼脫布衣歸。","霽岳明殘雪，清波漾落暉。","無窮幽鳥戲，時向棹前飛。"]', '["去去把青桂，平生心不違。","更蒙蓮府辟，兼脫布衣归。","霽岳明殘雪，清波漾落暉。","無窮幽鸟戲，时向棹前飞。"]', '诗', 'shi', '', NULL, '初離黔中泊江上 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e301fea5-a1b2-42dd-a30a-6b846812d452', '黔中酬同院韋判官', '黔中酬同院韋判官', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["平生同所爲，相遇偶然遲。","各著青袍後，無歸白社期。","江流來絕域，府地管諸夷。","聖代都無事，從公且賦詩。"]', '["平生同所爲，相遇偶然遲。","各著青袍後，無归白社期。","江流来絕域，府地管諸夷。","聖代都無事，從公且賦诗。"]', '诗', 'shi', '', NULL, '黔中酬同院韋判官 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dc27cfb-5770-4d67-a100-9e63ced8edac', '和范秘書襄陽舊遊', '和范秘书襄陽旧游', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["聽話揚帆興，初從峴首還。","高吟入白浪，遙坐看青山。","枯木猿啼爽，寒汀鶴步閑。","秋來關去夢，幾夜度商顏。"]', '["听話揚帆兴，初從峴首還。","高吟入白浪，遙坐看青山。","枯木猿啼爽，寒汀鹤步闲。","秋来关去梦，幾夜度商顏。"]', '诗', 'shi', '', NULL, '和范秘書襄陽舊遊 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0b8b184-515c-4b9f-b283-cfcf8e93f3b4', '秋夜山中思歸送友人', '秋夜山中思归送友人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["蕭條對秋色，相憶在雲泉。","木落病身起，潮平歸思懸。","涼鐘山頂寺，暝火渡頭船。","此地非吾土，淹留又一年。"]', '["蕭條对秋色，相憶在云泉。","木落病身起，潮平归思懸。","涼鐘山頂寺，暝火渡头船。","此地非吾土，淹留又一年。"]', '诗', 'shi', '', NULL, '秋夜山中思歸送友人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4f2514-1c28-41b6-961f-d708e69a5190', '自黔中東歸旅次淮上', '自黔中东归旅次淮上', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["行旅本同愁，黔吳復阻脩。","半年方中路，窮節到孤舟。","夕靄垂陰野，晨光動積流。","家山一夜夢，便是昔年遊。"]', '["行旅本同愁，黔吳复阻脩。","半年方中路，窮節到孤舟。","夕靄垂陰野，晨光动積流。","家山一夜梦，便是昔年游。"]', '诗', 'shi', '', NULL, '自黔中東歸旅次淮上 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cee4a0d-c06c-4664-aaee-2ed49aa28720', '江夏春感舊', '江夏春感旧', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["東風出海門，處處動林園。","澤國雪霜少，沙汀花木繁。","暖魚依水淺，晴雁入空翻。","何處陽和力，生萍不駐根。"]', '["东风出海门，处处动林园。","澤国雪霜少，沙汀花木繁。","暖鱼依水淺，晴雁入空翻。","何处陽和力，生萍不駐根。"]', '诗', 'shi', '', NULL, '江夏春感舊 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c10beffc-d1cc-4d38-a5dd-55ac9af9d5fb', '眉州別李使君', '眉州別李使君', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["回首雪峰前，朱門心杳然。","離人自嗚咽，流水莫潺湲。","毒草通蠻徼，秋林近漏天。","一生從此去，五字有誰憐。"]', '["回首雪峰前，朱门心杳然。","離人自嗚咽，流水莫潺湲。","毒草通蠻徼，秋林近漏天。","一生從此去，五字有誰怜。"]', '诗', 'shi', '', NULL, '眉州別李使君 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6e8492a-1ade-4dee-b3c8-44a9114b9ee2', '送許棠及第歸宣州', '送許棠及第归宣州', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["高科終自致，志業信如神。","待得逢公道，由來合貴身。","秋歸方覺好，舊夢始知真。","更想青山宅，誰爲後主人。"]', '["高科終自致，志業信如神。","待得逢公道，由来合貴身。","秋归方覺好，旧梦始知真。","更想青山宅，誰爲後主人。"]', '诗', 'shi', '', NULL, '送許棠及第歸宣州 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ed9f6c6-1475-4773-85bd-895af11dc8e3', '黔中罷職將泛江東', '黔中罷職將泛江东', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["黔中初罷職，薄俸亦無殘。","舉目鄉關遠，攜家旅食難。","野梅將雪競，江月與沙寒。","兩鬢愁應白，何勞把鏡看。"]', '["黔中初罷職，薄俸亦無殘。","舉目乡关远，携家旅食难。","野梅將雪競，江月與沙寒。","兩鬢愁應白，何勞把镜看。"]', '诗', 'shi', '', NULL, '黔中罷職將泛江東 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7745765e-daac-4ed7-95b3-09aee2dc42d1', '長安書事寄所知', '长安书事寄所知', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["帝里本無名，端居有道情。","睡魂春夢斷，書興晚窗明。","老擬歸何處，閑應過此生。","江湖終一日，拜別便東行。"]', '["帝里本無名，端居有道情。","睡魂春梦斷，书兴晚窗明。","老擬归何处，闲應過此生。","江湖終一日，拜別便东行。"]', '诗', 'shi', '', NULL, '長安書事寄所知 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb6b8b3-643b-466d-b2d1-0a1484d5b440', '酬姚覃', '酬姚覃', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["不見又相招，何曾訴寂寥。","醉眠春草長，吟坐夜燈銷。","淚墮思山切，身歸轉路遙。","年年送別處，楊柳少垂條。"]', '["不见又相招，何曾訴寂寥。","醉眠春草长，吟坐夜灯銷。","泪墮思山切，身归轉路遙。","年年送別处，楊柳少垂條。"]', '诗', 'shi', '', NULL, '酬姚覃 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('811610ae-4a7b-4a67-bb42-96bcc99201ec', '春日鄜州贈裴居言', '春日鄜州贈裴居言', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["雖將身佐幕，出入似閑居。","草色長相待，山情信不疎。","燈前春睡足，酒後夜寒餘。","筆硯時時近，終非署簿書。"]', '["雖將身佐幕，出入似闲居。","草色长相待，山情信不疎。","灯前春睡足，酒後夜寒餘。","笔硯时时近，終非署簿书。"]', '诗', 'shi', '', NULL, '春日鄜州贈裴居言 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04cd2cb2-f710-4a3f-9cc3-20bc0c800eed', '送于生入蜀', '送于生入蜀', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["家吳聞入蜀，道路頗乖離。","一第何多難，都城可少知。","江山非久適，命數未終奇。","況又將冤抱，經春杜魄隨。"]', '["家吳闻入蜀，道路頗乖離。","一第何多难，都城可少知。","江山非久適，命數未終奇。","況又將冤抱，經春杜魄隨。"]', '诗', 'shi', '', NULL, '送于生入蜀 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f2a358f-88a2-4052-a813-55e5133d48ca', '送許棠歸涇縣作尉', '送許棠归涇縣作尉', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["青桂復青袍，一歸榮一高。","縣人齊下拜，邑宰共分曹。","遶郭看秧插，尋街聽繭繅。","封侯萬里者，燕頷乃徒勞。"]', '["青桂复青袍，一归榮一高。","縣人齊下拜，邑宰共分曹。","遶郭看秧插，尋街听繭繅。","封侯万里者，燕頷乃徒勞。"]', '诗', 'shi', '', NULL, '送許棠歸涇縣作尉 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b6ee5f-c4e4-44a0-b547-fd1acc791f53', '友人話別', '友人話別', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["論交雖不蚤，話別且相親。","除却棲禪客，誰非南陌人。","半生都返性，終老擬安貧。","願入白雲社，高眠自致身。"]', '["論交雖不蚤，話別且相親。","除却棲禪客，誰非南陌人。","半生都返性，終老擬安貧。","願入白云社，高眠自致身。"]', '诗', 'shi', '', NULL, '友人話別 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afff0c17-0fe4-45af-85f8-5ff090244a25', '山居', '山居', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["欲出窮吾道，東西自未能。","捲書唯對鶴，開畫獨留僧。","落葉和雲掃，秋山共月登。","何年石上水，夜夜滴高層。"]', '["欲出窮吾道，东西自未能。","捲书唯对鹤，开畫独留僧。","落葉和云掃，秋山共月登。","何年石上水，夜夜滴高層。"]', '诗', 'shi', '', NULL, '山居 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c58e9000-e311-4750-9924-625c1616b78d', '寄范郎中', '寄范郎中', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["蔾杖山中出，吟詩對范家。","相知從海嶠，寄食向京華。","名宦成何報，清眸未縱賒。","臨邛夢來往，雨雪滿襃斜。"]', '["蔾杖山中出，吟诗对范家。","相知從海嶠，寄食向京华。","名宦成何報，清眸未縱賒。","臨邛梦来往，雨雪满襃斜。"]', '诗', 'shi', '', NULL, '寄范郎中 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e426816-c58c-409c-914f-a9e167197c50', '書懷', '书懷', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["宦途從不問，身事覺無差。","華髪初生女，滄洲未有家。","却閑思洞穴，終老曠桑麻。","別訪棲禪侶，相期語劫沙。"]', '["宦途從不问，身事覺無差。","华髪初生女，滄洲未有家。","却闲思洞穴，終老曠桑麻。","別訪棲禪侶，相期語劫沙。"]', '诗', 'shi', '', NULL, '書懷 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b54225c-1204-42ba-a6a7-2d1d3377d78c', '越中行', '越中行', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["越國臨滄海，芳洲復暮晴。","湖通諸浦白，日隱亂峰明。","野宿多無定，閑遊免有情。","天台聞不遠，終到石橋行。"]', '["越国臨滄海，芳洲复暮晴。","湖通諸浦白，日隐亂峰明。","野宿多無定，闲游免有情。","天台闻不远，終到石橋行。"]', '诗', 'shi', '', NULL, '越中行 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f59fb2b1-46e1-4303-8e3b-25d3ab8c5b9c', '春日南遊寄浙東許同年', '春日南游寄浙东許同年', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["孤帆處處宿，不問是誰家。","南國平蕪遠，東風細雨斜。","旅懷多寄酒，寒意欲留花。","更想前途去，茫茫滄海涯。"]', '["孤帆处处宿，不问是誰家。","南国平蕪远，东风細雨斜。","旅懷多寄酒，寒意欲留花。","更想前途去，茫茫滄海涯。"]', '诗', 'shi', '', NULL, '春日南遊寄浙東許同年 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9732635-cd42-42c9-b073-32062a46b175', '明州江亭夜別段秀才', '明州江亭夜別段秀才', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["離亭向水開，時候復蒸梅。","霹靂燈燭滅，蒹葭風雨來。","京關雖共語，海嶠不同回。","莫爲蓴鱸美，天涯滯爾才。"]', '["離亭向水开，时候复蒸梅。","霹靂灯燭滅，蒹葭风雨来。","京关雖共語，海嶠不同回。","莫爲蓴鱸美，天涯滯爾才。"]', '诗', 'shi', '', NULL, '明州江亭夜別段秀才 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9d08e81-f134-4c5a-ae77-2140ab264fdc', '臨岐留別相知', '臨岐留別相知', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["百歲竟何事，一身長遠遊。","行行將近老，處處不離愁。","世路多相取，權門不自投。","難爲此時別，欲別願人留。"]', '["百歲竟何事，一身长远游。","行行將近老，处处不離愁。","世路多相取，權门不自投。","难爲此时別，欲別願人留。"]', '诗', 'shi', '', NULL, '臨岐留別相知 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed2cb24f-c40e-4b8e-8800-35535a728cd6', '鄂渚湖上即事', '鄂渚湖上即事', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["杜門聊自適，湖水在窗間。","縱得滄洲去，無過白日閑。","多慵空好道，少賤早凋顏。","獨有東山月，依依自往還。"]', '["杜门聊自適，湖水在窗间。","縱得滄洲去，無過白日闲。","多慵空好道，少賤早凋顏。","独有东山月，依依自往還。"]', '诗', 'shi', '', NULL, '鄂渚湖上即事 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35a92d34-aa42-45c5-a873-df372c6fe9a6', '辭夏口崔尚書', '辞夏口崔尚书', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["一飯仍難受，依仁況一年。","終期身可報，不擬骨空鐫。","城晚風高角，江春浪起船。","同來棲止地，獨去塞鴻前。"]', '["一飯仍难受，依仁況一年。","終期身可報，不擬骨空鐫。","城晚风高角，江春浪起船。","同来棲止地，独去塞鴻前。"]', '诗', 'shi', '', NULL, '辭夏口崔尚書 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceac9e2b-a485-4fc0-aa13-b8688eab8e83', '秦原早望', '秦原早望', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["一忝鄉書薦，長安未得回。","年光逐渭水，春色上秦臺。","燕掠平蕪去，人衝細雨來。","東風生故里，又過幾花開。"]', '["一忝乡书薦，长安未得回。","年光逐渭水，春色上秦台。","燕掠平蕪去，人衝細雨来。","东风生故里，又過幾花开。"]', '诗', 'shi', '', NULL, '秦原早望 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5621e8e9-0952-4551-87a6-80c77c8e0d86', '送友人之揚州', '送友人之揚州', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["一別長安後，晨征便信雞。","河聲入峽急，地勢出關低。","綠樹叢垓下，青蕪闊楚西。","路長知不惡，隨處得詩題。"]', '["一別长安後，晨征便信雞。","河声入峽急，地勢出关低。","綠樹叢垓下，青蕪闊楚西。","路长知不惡，隨处得诗題。"]', '诗', 'shi', '', NULL, '送友人之揚州 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d8618e-edb9-40c7-93dd-c8bfdd1f4758', '過四皓廟', '過四皓廟', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["東西南北人，高跡自相親。","天下已歸漢，山中猶避秦。","龍樓曾作客，鶴氅不爲臣。","獨有千年後，青青廟木春。"]', '["东西南北人，高跡自相親。","天下已归漢，山中猶避秦。","龙楼曾作客，鹤氅不爲臣。","独有千年後，青青廟木春。"]', '诗', 'shi', '', NULL, '過四皓廟 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb327c73-d247-444d-b4e1-57d96fa2b7a6', '陝下懷歸', '陝下懷归', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["故園何處在，零落五湖東。","日暮無來客，天寒有去鴻。","大河冰徹塞，高嶽雪連空。","獨夜懸歸思，迢迢永漏中。"]', '["故园何处在，零落五湖东。","日暮無来客，天寒有去鴻。","大河冰徹塞，高嶽雪連空。","独夜懸归思，迢迢永漏中。"]', '诗', 'shi', '', NULL, '陝下懷歸 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54d6ff00-d8c7-4a05-aca2-996635c0a6f1', '送徐處士歸江南', '送徐处士归江南', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["行行野雪薄，寒氣日通春。","故國又芳草，滄江終白身。","遊歸花落滿，睡起鳥啼新。","莫惜閑書札，西來問旅人。"]', '["行行野雪薄，寒氣日通春。","故国又芳草，滄江終白身。","游归花落满，睡起鸟啼新。","莫惜闲书札，西来问旅人。"]', '诗', 'shi', '', NULL, '送徐處士歸江南 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61149c4d-2fc3-41db-8cb6-e4cca4cb1c8b', '鄜州留別王從事', '鄜州留別王從事', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["相識未十日，相知如十年。","從來易離別，此去忽留連。","路險行衝雨，山高度隔天。","難終清夜坐，更聽說安邊。"]', '["相識未十日，相知如十年。","從来易離別，此去忽留連。","路險行衝雨，山高度隔天。","难終清夜坐，更听说安邊。"]', '诗', 'shi', '', NULL, '鄜州留別王從事 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac401fd-f53b-4f75-9d30-c6728cc7928e', '長安夜懷', '长安夜懷', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["匹馬西遊日，從吳又轉荆。","風雷幾夜坐，山水半年行。","夢永秋燈滅，吟餘曉露明。","良時不我與，白髮向秦生。"]', '["匹马西游日，從吳又轉荆。","风雷幾夜坐，山水半年行。","梦永秋灯滅，吟餘晓露明。","良时不我與，白髮向秦生。"]', '诗', 'shi', '', NULL, '長安夜懷 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95d8500e-923d-4703-a6f2-e987a0520195', '冬夜山中尋友', '冬夜山中尋友', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["何人山雪夜，相訪不相思。","若得長閑日，應無暫到時。","葉寒凋欲盡，泉凍落還遲。","即此天明去，重來未有期。"]', '["何人山雪夜，相訪不相思。","若得长闲日，應無暫到时。","葉寒凋欲尽，泉凍落還遲。","即此天明去，重来未有期。"]', '诗', 'shi', '', NULL, '冬夜山中尋友 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92dc105b-1564-4ab7-9104-330b603e5a70', '送劉山人歸洞庭', '送劉山人归洞庭', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["君逐雲山去，人間又絕蹤。","半湖乘早月，中路入疎鐘。","秋盡草蟲急，夜深山雨重。","平生心未已，豈得更相從。"]', '["君逐云山去，人间又絕蹤。","半湖乘早月，中路入疎鐘。","秋尽草蟲急，夜深山雨重。","平生心未已，豈得更相從。"]', '诗', 'shi', '', NULL, '送劉山人歸洞庭 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c84a5bc0-e95d-4857-86d6-fcc7a4490ced', '古意', '古意', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["白馬遊何處，青樓日正長。","鳳簫拋舊曲，鸞鏡嬾新妝。","玄鳥深巢靜，飛花入戶香。","雖非竇滔婦，錦字已成章。"]', '["白马游何处，青楼日正长。","鳳簫拋旧曲，鸾镜嬾新妝。","玄鸟深巢静，飞花入戶香。","雖非竇滔婦，錦字已成章。"]', '诗', 'shi', '', NULL, '古意 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d4e7603-41a1-416a-80e7-d0e7101feb17', '避暑', '避暑', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["當暑憶歸林，陶家借柳陰。","蟬從初伏噪，客向晚涼吟。","白日欺玄鬢，滄江負素心。","神仙倘有術，引我出幽岑。"]', '["當暑憶归林，陶家借柳陰。","蟬從初伏噪，客向晚涼吟。","白日欺玄鬢，滄江負素心。","神仙倘有術，引我出幽岑。"]', '诗', 'shi', '', NULL, '避暑 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c44a4a5-9419-4643-ae9c-ccb56fce9c7c', '送吳秘書歸杭州', '送吳秘书归杭州', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["爲客得從容，官清料復重。","海崖歸有業，天目近何峰。","是處通春棹，無村不夜舂。","馬卿夸貴達，還說返臨邛。"]', '["爲客得從容，官清料复重。","海崖归有業，天目近何峰。","是处通春棹，無村不夜舂。","马卿夸貴達，還说返臨邛。"]', '诗', 'shi', '', NULL, '送吳秘書歸杭州 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38b6af91-b486-40b1-951e-97324e1346e1', '中秋對月', '中秋对月', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["秋分一夜停，陰魄最晶熒。","好是生滄海，徐看歷杳冥。","層空疑洗色，萬怪想潛形。","他夕無相類，晨雞不可聽。"]', '["秋分一夜停，陰魄最晶熒。","好是生滄海，徐看歷杳冥。","層空疑洗色，万怪想潛形。","他夕無相類，晨雞不可听。"]', '诗', 'shi', '', NULL, '中秋對月 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ae4d35-35dd-4ea2-bf0d-57f599678643', '八月上峽', '八月上峽', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["萬里巴江水，秋來滿峽流。","亂山無陸路，行客在孤舟。","洶洶灘聲急，冥冥樹色愁。","免爲三不弔，已白一生頭。"]', '["万里巴江水，秋来满峽流。","亂山無陸路，行客在孤舟。","洶洶灘声急，冥冥樹色愁。","免爲三不弔，已白一生头。"]', '诗', 'shi', '', NULL, '八月上峽 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a99bd7-88ad-4758-9a6b-8d0b1453e003', '送狄明府赴九江', '送狄明府赴九江', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["字人修祖德，清白定聞傳。","匹馬從秦去，孤帆入楚懸。","關中寒食雨，湖上暑衣天。","四考兼重請，相知住幾年。"]', '["字人修祖德，清白定闻傳。","匹马從秦去，孤帆入楚懸。","关中寒食雨，湖上暑衣天。","四考兼重請，相知住幾年。"]', '诗', 'shi', '', NULL, '送狄明府赴九江 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('475bd683-f6f5-4bde-9553-13feb6cccde9', '陝下投姚諫議', '陝下投姚諫議', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["舊業在東鄙，西遊從楚荆。","風雷幾夜坐，山水半年行。","夢永秋燈滅，吟孤曉露明。","前心若不遂，有耻却歸耕。"]', '["旧業在东鄙，西游從楚荆。","风雷幾夜坐，山水半年行。","梦永秋灯滅，吟孤晓露明。","前心若不遂，有耻却归耕。"]', '诗', 'shi', '', NULL, '陝下投姚諫議 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca375d52-f2f0-492a-ba97-9d79bc7f01c1', '關東逢薛能', '关东逢薛能', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["何處不相思，相逢還有時。","交心如到老，會面未爲遲。","苦學緣明代，勞生欲白髭。","唯君一度別，便似見無期。"]', '["何处不相思，相逢還有时。","交心如到老，會面未爲遲。","苦学緣明代，勞生欲白髭。","唯君一度別，便似见無期。"]', '诗', 'shi', '', NULL, '關東逢薛能 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5675e35e-2fcd-48a9-9f1a-6e5c5e1fa586', '富春贈孫璐', '富春贈孫璐', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["天柱與天目，曾棲絕頂房。","青雲求祿晚，白日坐家長。","井氣通潮信，牕風引海涼。","平生詩稱在，老達亦何妨。"]', '["天柱與天目，曾棲絕頂房。","青云求祿晚，白日坐家长。","井氣通潮信，牕风引海涼。","平生诗稱在，老達亦何妨。"]', '诗', 'shi', '', NULL, '富春贈孫璐 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9014fcd2-6744-4d85-9d43-eee13952dc3c', '送友人遊蜀', '送友人游蜀', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["東堂雖不捷，西去復何愁。","蜀馬知歸路，巴山似舊遊。","星臨劒閣動，花落錦江流。","鼓吹青林下，時聞祭武侯。"]', '["东堂雖不捷，西去复何愁。","蜀马知归路，巴山似旧游。","星臨劒閣动，花落錦江流。","鼓吹青林下，时闻祭武侯。"]', '诗', 'shi', '', NULL, '送友人遊蜀 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7163e631-cc74-4ee0-9a16-d4ec2f587e08', '夏日盩厔郊居寄姚少府', '夏日盩厔郊居寄姚少府', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["古木有清陰，寒泉有下深。","蟬從初伏噪，客向晚涼吟。","白日欺玄鬢，滄江負素心。","甚思中夜話，何路許相尋。"]', '["古木有清陰，寒泉有下深。","蟬從初伏噪，客向晚涼吟。","白日欺玄鬢，滄江負素心。","甚思中夜話，何路許相尋。"]', '诗', 'shi', '', NULL, '夏日盩厔郊居寄姚少府 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de4a29bf-da79-485d-8e9f-ab9fb9ef5b0f', '送胡休處士歸湘江', '送胡休处士归湘江', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["見說湘江切，長愁有去時。","江湖秋涉遠，雷雨夜眠遲。","舊業多歸興，空山盡老期。","天寒一瓢酒，落日醉留誰。"]', '["见说湘江切，长愁有去时。","江湖秋涉远，雷雨夜眠遲。","旧業多归兴，空山尽老期。","天寒一瓢酒，落日醉留誰。"]', '诗', 'shi', '', NULL, '送胡休處士歸湘江 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f15d94a9-d748-4057-838c-9a625c32e4bc', '峽州送清徹上人歸浙西', '峽州送清徹上人归浙西', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["風濤幾千里，歸路半乘舟。","此地難相遇，何人更共遊。","坐經嵩頂夏，行值洛陽秋。","到寺安禪夕，江雲滿石樓。"]', '["风濤幾千里，归路半乘舟。","此地难相遇，何人更共游。","坐經嵩頂夏，行值洛陽秋。","到寺安禪夕，江云满石楼。"]', '诗', 'shi', '', NULL, '峽州送清徹上人歸浙西 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21dd6cc6-2ce5-4f63-93f9-94c6a15d851c', '送僧入天台', '送僧入天台', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["一錫隨緣赴，天台又去登。","長亭舊別路，落日獨行僧。","夜燒山何處，秋帆浪幾層。","他時授巾拂，莫爲老無能。"]', '["一錫隨緣赴，天台又去登。","长亭旧別路，落日独行僧。","夜燒山何处，秋帆浪幾層。","他时授巾拂，莫爲老無能。"]', '诗', 'shi', '', NULL, '送僧入天台 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888f73cd-938c-4cae-813c-c80573a32ae5', '回山後寄范酇先輩', '回山後寄范酇先輩', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["高樓會月夜，北雁向南分。","留住經春雪，辭來見夏雲。","遙空江不極，絕頂日難曛。","一與山僧坐，無因得議文。"]', '["高楼會月夜，北雁向南分。","留住經春雪，辞来见夏云。","遙空江不極，絕頂日难曛。","一與山僧坐，無因得議文。"]', '诗', 'shi', '', NULL, '回山後寄范酇先輩 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5166c587-ee47-47dd-a475-e2c8136a54fa', '長安送友人東歸', '长安送友人东归', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["白社思歸處，青門見去人。","鄉遙茂苑樹，路入廣陵塵。","海日潮浮曉，湖山雪露春。","猶期來帝里，未是得閑人。"]', '["白社思归处，青门见去人。","乡遙茂苑樹，路入廣陵塵。","海日潮浮晓，湖山雪露春。","猶期来帝里，未是得闲人。"]', '诗', 'shi', '', NULL, '長安送友人東歸 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d812c37a-fa93-445b-8fff-dd0ee1a464d7', '深秋過源宗上人房', '深秋過源宗上人房', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["到日值搖落，相留山舍空。","微寒生夜半，積雨向秋終。","度講多來雁，經禪少候蟲。","方從聽話後，不省在愁中。"]', '["到日值搖落，相留山舍空。","微寒生夜半，積雨向秋終。","度講多来雁，經禪少候蟲。","方從听話後，不省在愁中。"]', '诗', 'shi', '', NULL, '深秋過源宗上人房 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9abf4c9f-f569-41be-94c8-1e6e825157ec', '秋日登山閣', '秋日登山閣', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["蒼蒼山閣晚，杳杳隙塵秋。","偶上多時立，翻成盡日愁。","草平連邑動，河滿逐江流。","下視窮邊路，行人在隴頭。"]', '["蒼蒼山閣晚，杳杳隙塵秋。","偶上多时立，翻成尽日愁。","草平連邑动，河满逐江流。","下視窮邊路，行人在隴头。"]', '诗', 'shi', '', NULL, '秋日登山閣 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93adb863-7d10-4b40-b0e4-e64bd4223706', '秋宿慈恩寺遂上人院', '秋宿慈恩寺遂上人院', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["滿閣終南色，清宵獨倚欄。","風高斜漢動，葉下曲江寒。","帝里求名老，空門見性難。","吾師無一事，不似在長安。"]', '["满閣終南色，清宵独倚欄。","风高斜漢动，葉下曲江寒。","帝里求名老，空门见性难。","吾師無一事，不似在长安。"]', '诗', 'shi', '', NULL, '秋宿慈恩寺遂上人院 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8656a575-0e2c-4077-8214-70f202c4980c', '題棲霞寺慶上人院', '題棲霞寺慶上人院', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["居與鳥巢鄰，日將巢鳥親。","多生從此性，久集得無身。","樹老風終夜，山寒雪見春。","不知諸祖後，傳印是何人。"]', '["居與鸟巢鄰，日將巢鸟親。","多生從此性，久集得無身。","樹老风終夜，山寒雪见春。","不知諸祖後，傳印是何人。"]', '诗', 'shi', '', NULL, '題棲霞寺慶上人院 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7345bc9d-6b0c-41c1-be11-002f858ce90e', '送友人入蜀', '送友人入蜀', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["天際蜀門開，西看舉別杯。","何人不異禮，上客自懷才。","夜澗青林發，秋江淥水來。","臨邛行樂處，莫到白頭回。"]', '["天際蜀门开，西看舉別杯。","何人不異禮，上客自懷才。","夜澗青林發，秋江淥水来。","臨邛行乐处，莫到白头回。"]', '诗', 'shi', '', NULL, '送友人入蜀 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51dc310b-cb62-44f5-9091-62a29fc8e131', '贈同官蘇明府', '贈同官蘇明府', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["山中畿內邑，別覺大夫清。","簿領分王事，官資寄野情。","閑齋無獄訟，隱几向泉聲。","從此朝天路，門前是去程。"]', '["山中畿內邑，別覺大夫清。","簿領分王事，官資寄野情。","闲斋無獄訟，隐几向泉声。","從此朝天路，门前是去程。"]', '诗', 'shi', '', NULL, '贈同官蘇明府 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7781d087-9a13-461f-9c49-eb72b0689176', '送厲圖南往荆州覲伯', '送厲圖南往荆州覲伯', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["雲水入荆湘，古來魚鳥鄉。","故關重隔遠，春日獨行長。","山溜含清韻，江雷吐夜光。","郡中詞客會，遊子更升堂。"]', '["云水入荆湘，古来鱼鸟乡。","故关重隔远，春日独行长。","山溜含清韻，江雷吐夜光。","郡中词客會，游子更升堂。"]', '诗', 'shi', '', NULL, '送厲圖南往荆州覲伯 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f625a8-cfc1-430b-a9db-0c09a9171b2f', '山中夜坐', '山中夜坐', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["歸家來幾夜，倏忽覺秋殘。","月滿方塘白，風依老樹寒。","戲魚重躍定，驚鳥却棲難。","爲有門前路，吾生不得安。"]', '["归家来幾夜，倏忽覺秋殘。","月满方塘白，风依老樹寒。","戲鱼重躍定，驚鸟却棲难。","爲有门前路，吾生不得安。"]', '诗', 'shi', '', NULL, '山中夜坐 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7572df3b-441e-44cd-b6ab-f7a886228f88', '送台州唐興陳明府', '送台州唐兴陳明府', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["見說海西隅，山川與俗殊。","宦遊如不到，仙分即應無。","瀑布當公署，天台是縣圖。","遙知爲吏去，有術字惸孤。"]', '["见说海西隅，山川與俗殊。","宦游如不到，仙分即應無。","瀑布當公署，天台是縣圖。","遙知爲吏去，有術字惸孤。"]', '诗', 'shi', '', NULL, '送台州唐興陳明府 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a70e91-a8f5-41a1-8f75-6409c9ac30d0', '夏日過友人檀溪別業', '夏日過友人檀溪別業', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["暑天宜野宅，林籟爽泠泠。","沙月邀開戶，巖風助掃庭。","鷺棲依綠篠，魚躍出清萍。","客抱方如醉，因來得暫醒。"]', '["暑天宜野宅，林籟爽泠泠。","沙月邀开戶，巖风助掃庭。","鷺棲依綠篠，鱼躍出清萍。","客抱方如醉，因来得暫醒。"]', '诗', 'shi', '', NULL, '夏日過友人檀溪別業 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e330be48-ffc2-4fce-9eb8-247807f4f71a', '自江上入關', '自江上入关', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["盡室寄滄洲，孤帆獨泝流。","天涯心似夢，江上雨兼秋。","文字爲人棄，田園被債收。"]', '["尽室寄滄洲，孤帆独泝流。","天涯心似梦，江上雨兼秋。","文字爲人棄，田园被債收。"]', '诗', 'shi', '', NULL, '自江上入關 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411796cc-6950-4267-8025-53ea725553c0', '冬夜和范秘書宿秘省中作', '冬夜和范秘书宿秘省中作', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["每日得閑吟，清曹闕下深。","因知遙夜坐，別有遠山心。","芸細書中氣，松疎雪後陰。","歸時高興足，還復插朝簪。"]', '["每日得闲吟，清曹闕下深。","因知遙夜坐，別有远山心。","芸細书中氣，松疎雪後陰。","归时高兴足，還复插朝簪。"]', '诗', 'shi', '', NULL, '冬夜和范秘書宿秘省中作 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa2cdb39-1eae-4fce-83d3-c73d24227aaa', '送友人遊太原', '送友人游太原', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["孤帆幾日懸，楚客思飄然。","水宿南湖夜，山離舊國年。","秋風高送雁，寒雨入停蟬。","此去勤書札，時常中路傳。"]', '["孤帆幾日懸，楚客思飄然。","水宿南湖夜，山離旧国年。","秋风高送雁，寒雨入停蟬。","此去勤书札，时常中路傳。"]', '诗', 'shi', '', NULL, '送友人遊太原 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dc64afc-9d79-4924-a40e-313469970770', '江上居寄山中客', '江上居寄山中客', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["山後與山前，相思隔呌猿。","殘雲收樹末，返照落江源。","苦雨秋濤漲，狂風野火翻。","朝來賣藥客，遇我達無言。"]', '["山後與山前，相思隔呌猿。","殘云收樹末，返照落江源。","苦雨秋濤漲，狂风野火翻。","朝来賣藥客，遇我達無言。"]', '诗', 'shi', '', NULL, '江上居寄山中客 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb7414e5-fd3e-46eb-99b2-3bad97e2b620', '送張郎中赴睦州', '送張郎中赴睦州', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["青山復淥水，想入富春西。","夾岸清猿去，中流白日低。","美兼華省出，榮共故鄉齊。","賤子遙攀送，歸心逐馬蹄。"]', '["青山复淥水，想入富春西。","夾岸清猿去，中流白日低。","美兼华省出，榮共故乡齊。","賤子遙攀送，归心逐马蹄。"]', '诗', 'shi', '', NULL, '送張郎中赴睦州 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f66b613-c6ad-4ffe-807e-4f8a06edc638', '送鄂渚韋尚書赴鎮', '送鄂渚韋尚书赴鎮', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["夏口本吳頭，重城據上遊。","戈船轉江漢，風月宿汀洲。","執憲傾民望，銜恩赴主憂。","誰知舊寮屬，攀餞淚仍流。"]', '["夏口本吳头，重城據上游。","戈船轉江漢，风月宿汀洲。","執憲傾民望，銜恩赴主憂。","誰知旧寮屬，攀餞泪仍流。"]', '诗', 'shi', '', NULL, '送鄂渚韋尚書赴鎮 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04022602-65ef-40e1-bc6a-ec75bee4e148', '送崔侍御書記赴山北座主尚書招辟', '送崔侍御书記赴山北座主尚书招辟', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["書記向丘門，旌幢夾谷尊。","從來遊幕意，此去幷酬恩。","雁呌嫌冰合，驄嘶喜雪繁。","同爲入室士，不覺別銷魂。"]', '["书記向丘门，旌幢夾谷尊。","從来游幕意，此去幷酬恩。","雁呌嫌冰合，驄嘶喜雪繁。","同爲入室士，不覺別銷魂。"]', '诗', 'shi', '', NULL, '送崔侍御書記赴山北座主尚書招辟 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc6d24c-3f64-4a74-9f07-bcd8e5bfa574', '入朝遇雪', '入朝遇雪', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["霜鬢持霜簡，朝天向雪天。","玉階初辨色，瓊樹乍相鮮。","密翳空難曙，盈徴瑞不愆。","誰爲洛陽客，是日更高眠。"]', '["霜鬢持霜簡，朝天向雪天。","玉階初辨色，瓊樹乍相鲜。","密翳空难曙，盈徴瑞不愆。","誰爲洛陽客，是日更高眠。"]', '诗', 'shi', '', NULL, '入朝遇雪 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47a5c3f2-7f63-4863-b660-650c8e417c56', '勉力', '勉力', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["日月不並照，升沈俱有時。","自媒徒欲速，孤立却宜遲。","盡力唯求己，公心任遇誰。","人間不得意，半是鬢先衰。"]', '["日月不並照，升沈俱有时。","自媒徒欲速，孤立却宜遲。","尽力唯求己，公心任遇誰。","人间不得意，半是鬢先衰。"]', '诗', 'shi', '', NULL, '勉力 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('345f04ea-f77a-4c46-be30-55caa4dd5a79', '郊居寄友人', '郊居寄友人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["林色樹還曛，何時得見君。","獨居度永日，相去遠浮雲。","故疾隨秋至，離懷覺夜分。","蛩聲非自苦，偏是旅人聞。"]', '["林色樹還曛，何时得见君。","独居度永日，相去远浮云。","故疾隨秋至，離懷覺夜分。","蛩声非自苦，偏是旅人闻。"]', '诗', 'shi', '', NULL, '郊居寄友人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc34511-ad8e-4dee-8155-8153d9688989', '送陸肱歸吳興', '送陸肱归吳兴', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["雪後江上去，風光故國新。","清渾天氣曉，綠動浪花春。","勸酒提壺鳥，乘舟震澤人。","誰知滄海月，取桂却來秦。"]', '["雪後江上去，风光故国新。","清渾天氣晓，綠动浪花春。","勸酒提壺鸟，乘舟震澤人。","誰知滄海月，取桂却来秦。"]', '诗', 'shi', '', NULL, '送陸肱歸吳興 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a21c126f-edf4-4dcf-92a6-6ca34b2e06ca', '暮秋重過山僧院', '暮秋重過山僧院', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["却接良宵坐，明河幾轉流。","安禪逢小暑，抱疾入高秋。","靜室聞玄理，深山可白頭。","朝朝獻林果，亦欲學獼猴。"]', '["却接良宵坐，明河幾轉流。","安禪逢小暑，抱疾入高秋。","静室闻玄理，深山可白头。","朝朝獻林果，亦欲学獼猴。"]', '诗', 'shi', '', NULL, '暮秋重過山僧院 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfc5e0de-3e4f-4695-9ec7-7332bde9b938', '送新安少府', '送新安少府', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["南浮雖六月，風水已秋涼。","日亂看江樹，身飛逐楚檣。","後期誰可定，臨別語空長。","遠宦須清苦，幽蘭貴獨芳。"]', '["南浮雖六月，风水已秋涼。","日亂看江樹，身飞逐楚檣。","後期誰可定，臨別語空长。","远宦須清苦，幽蘭貴独芳。"]', '诗', 'shi', '', NULL, '送新安少府 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa7aa13-ae74-44bb-891a-6face034eeb9', '送人歸吳', '送人归吳', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["何人不歸去，君去是閑人。","帝里求相識，山家即近鄰。","交情吾道可，離思柳條新。","未飲青門酒，先如醉夢身。"]', '["何人不归去，君去是闲人。","帝里求相識，山家即近鄰。","交情吾道可，離思柳條新。","未饮青门酒，先如醉梦身。"]', '诗', 'shi', '', NULL, '送人歸吳 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb3be4a-f521-4de0-a820-7799bdaaeaac', '送姚評事', '送姚評事', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["儒服從戎去，須知勝事全。","使君開幕日，天子偃戈年。","風雨依嵩嶺，桑麻接楚田。","新詩隨過客，旋滿洛陽傳。"]', '["儒服從戎去，須知勝事全。","使君开幕日，天子偃戈年。","风雨依嵩嶺，桑麻接楚田。","新诗隨過客，旋满洛陽傳。"]', '诗', 'shi', '', NULL, '送姚評事 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1a16a64-7822-4b90-8b88-31e9bf7eb59f', '題棲雲寺立上人院', '題棲云寺立上人院', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["是法從生有，脩持歷劫塵。","獨居巖下室，長似定中身。","樹老風終夜，山寒雪見春。","不知諸祖後，傳印是何人。"]', '["是法從生有，脩持歷劫塵。","独居巖下室，长似定中身。","樹老风終夜，山寒雪见春。","不知諸祖後，傳印是何人。"]', '诗', 'shi', '', NULL, '題棲雲寺立上人院 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14494be6-98f2-4f3b-8089-e490ce77c3a0', '黔中罷職過峽州題田使君北樓', '黔中罷職過峽州題田使君北楼', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["巴中初去日，已遇使君留。","及得尋東道，還陪上北樓。","江衝巫峽出，檣過洛宮收。","好是從戎罷，看山覺自由。"]', '["巴中初去日，已遇使君留。","及得尋东道，還陪上北楼。","江衝巫峽出，檣過洛宮收。","好是從戎罷，看山覺自由。"]', '诗', 'shi', '', NULL, '黔中罷職過峽州題田使君北樓 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e0c989-f402-4fea-84b9-c8e121b3e70b', '江上送從兄羣玉校書東遊', '江上送從兄羣玉校书东游', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["逍遙蓬閣吏，才子復詩流。","墳籍因窮覽，江湖却縱遊。","眠波聽戍鼓，飯浦約魚舟。","處處迎高密，先應掃郡樓。"]', '["逍遙蓬閣吏，才子复诗流。","墳籍因窮覽，江湖却縱游。","眠波听戍鼓，飯浦約鱼舟。","处处迎高密，先應掃郡楼。"]', '诗', 'shi', '', NULL, '江上送從兄羣玉校書東遊 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cffea41-be7b-45b2-9e94-5c11ba3e7e88', '宛陵東峰亭與友人話別', '宛陵东峰亭與友人話別', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["坐舉天涯目，停杯語日晡。","脩篁齊逈檻，列岫限平蕪。","亂水通三楚，歸帆挂五湖。"]', '["坐舉天涯目，停杯語日晡。","脩篁齊逈檻，列岫限平蕪。","亂水通三楚，归帆挂五湖。"]', '诗', 'shi', '', NULL, '宛陵東峰亭與友人話別 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da08ae1e-81dd-440c-9c69-96e79e6c6950', '華山尋隱者', '华山尋隐者', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["自入華山居，關東相見疎。","瓢中誰寄酒，葉上我留書。","巢鳥寒棲盡，潭泉暮凍餘。","長聞得藥力，此說又何如。"]', '["自入华山居，关东相见疎。","瓢中誰寄酒，葉上我留书。","巢鸟寒棲尽，潭泉暮凍餘。","长闻得藥力，此说又何如。"]', '诗', 'shi', '', NULL, '華山尋隱者 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884a7c90-4d31-429b-866f-29fa86e0c2cd', '題薦福寺僧棲白上人院', '題薦福寺僧棲白上人院', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["空門有才子，得道亦吟詩。","內殿頻徴入，孤峰久作期。","高名何代比，密行幾生持。","長愛喬松院，清涼坐夏時。"]', '["空门有才子，得道亦吟诗。","內殿頻徴入，孤峰久作期。","高名何代比，密行幾生持。","长愛喬松院，清涼坐夏时。"]', '诗', 'shi', '', NULL, '題薦福寺僧棲白上人院 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9d595d-c789-446b-a974-952a6718e992', '遊四明山劉樊二真人祠題山下孫氏居', '游四明山劉樊二真人祠題山下孫氏居', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["久在仙壇下，全家是地仙。","池塘來乳洞，禾黍接芝田。","起看青山足，還傾白酒眠。","不知塵世事，雙鬢逐流年。"]', '["久在仙壇下，全家是地仙。","池塘来乳洞，禾黍接芝田。","起看青山足，還傾白酒眠。","不知塵世事，雙鬢逐流年。"]', '诗', 'shi', '', NULL, '遊四明山劉樊二真人祠題山下孫氏居 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c1987e-e61d-4028-b52a-8c021c200e92', '和太學趙鴻博士歸蔡中', '和太学趙鴻博士归蔡中', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["得祿從高第，還鄉見後生。","田園休問主，詞賦已垂名。","掃壁前題出，開窗舊景清。","遙知賢太守，致席日邀迎。"]', '["得祿從高第，還乡见後生。","田园休问主，词賦已垂名。","掃壁前題出，开窗旧景清。","遙知賢太守，致席日邀迎。"]', '诗', 'shi', '', NULL, '和太學趙鴻博士歸蔡中 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b0dddab-70d1-4514-a7a7-a80eb2def195', '送壽昌曹明府', '送壽昌曹明府', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["惠人須宰邑，爲政貴通經。","却用清琴理，猶嫌薄俗聽。","漲江晴漸淥，春嶠燒還青。","若宿嚴陵瀨，誰當是客星。"]', '["惠人須宰邑，爲政貴通經。","却用清琴理，猶嫌薄俗听。","漲江晴漸淥，春嶠燒還青。","若宿嚴陵瀨，誰當是客星。"]', '诗', 'shi', '', NULL, '送壽昌曹明府 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5a3e1f9-e399-4fd4-b2b5-af14402068c4', '哭賈島', '哭賈島', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["秦樓吟苦夜，南望只悲君。","一宦終遐徼，千山隔旅墳。","恨聲流蜀魄，冤氣入湘雲。","無限風騷句，時來日夜聞。"]', '["秦楼吟苦夜，南望只悲君。","一宦終遐徼，千山隔旅墳。","恨声流蜀魄，冤氣入湘云。","無限风騷句，时来日夜闻。"]', '诗', 'shi', '', NULL, '哭賈島 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f920b77-d950-40ae-9398-36b75cff38a6', '送薛能赴鎮徐方', '送薛能赴鎮徐方', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["列土人間盛，彭門屬九州。","山河天設險，禮樂牧分憂。","皎日爲明信，清風占早秋。","雖同郤縠舉，郤縠不封侯。"]', '["列土人间盛，彭门屬九州。","山河天設險，禮乐牧分憂。","皎日爲明信，清风占早秋。","雖同郤縠舉，郤縠不封侯。"]', '诗', 'shi', '', NULL, '送薛能赴鎮徐方 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f7db208-afbd-4e1f-ba1e-7ea7eb61052c', '送鳯翔范書記', '送鳯翔范书記', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["西京無暑氣，夏景似清秋。","天府來相辟，高人去自由。","江山通蜀國，日月近神州。","若共將軍語，河蘭地未收。"]', '["西京無暑氣，夏景似清秋。","天府来相辟，高人去自由。","江山通蜀国，日月近神州。","若共將軍語，河蘭地未收。"]', '诗', 'shi', '', NULL, '送鳯翔范書記 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c2239b-3160-4324-bb97-daec992f0414', '岐山逢陝下故人', '岐山逢陝下故人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["三秦一會面，二陝久分攜。","共憶黃河北，相留白日西。","寄來書少達，別後夢多迷。","早晚期于此，看花聽鳥啼。"]', '["三秦一會面，二陝久分携。","共憶黄河北，相留白日西。","寄来书少達，別後梦多迷。","早晚期于此，看花听鸟啼。"]', '诗', 'shi', '', NULL, '岐山逢陝下故人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ebc7b30-bb7a-4194-a32e-debf531e335f', '送友人陸肱往太原', '送友人陸肱往太原', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["幷州非故國，君去復尋誰。","獫狁方爲寇，嫖姚正用師。","戍煙來自號，邊雪下無時。","更想經綿上，應逢禁火期。"]', '["幷州非故国，君去复尋誰。","獫狁方爲寇，嫖姚正用師。","戍煙来自號，邊雪下無时。","更想經綿上，應逢禁火期。"]', '诗', 'shi', '', NULL, '送友人陸肱往太原 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db716d68-91c5-428f-9a1b-078f554eafac', '贈李將軍', '贈李將軍', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["吾宗偏好武，漢代將家流。","走馬辭中禁，屯軍向渭州。","天心待破虜，陣面許封侯。","却得河源水，方應洗國讐。"]', '["吾宗偏好武，漢代將家流。","走马辞中禁，屯軍向渭州。","天心待破虜，陣面許封侯。","却得河源水，方應洗国讐。"]', '诗', 'shi', '', NULL, '贈李將軍 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c97ba93a-285c-4182-bf9d-96663e102d5e', '送友人喻坦之歸睦州', '送友人喻坦之归睦州', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["歸心常共知，歸路不相隨。","彼此無依倚，東西又別離。","山花含雨濕，江樹近潮欹。","莫戀漁樵興，生涯各有爲。"]', '["归心常共知，归路不相隨。","彼此無依倚，东西又別離。","山花含雨濕，江樹近潮欹。","莫戀漁樵兴，生涯各有爲。"]', '诗', 'shi', '', NULL, '送友人喻坦之歸睦州 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9836f9fe-8999-4293-bc12-aefa289abdad', '尋華陽隱者', '尋华陽隐者', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["閑却白雲居，行蹤出去初。","窗中聊取筆，架上獨留書。","日背林光冷，潭澄嶽影虛。","長聞得藥力，此說復何如。"]', '["闲却白云居，行蹤出去初。","窗中聊取笔，架上独留书。","日背林光冷，潭澄嶽影虛。","长闻得藥力，此说复何如。"]', '诗', 'shi', '', NULL, '尋華陽隱者 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8837a315-30cd-44b9-b861-8c3e1807a06a', '長安即事', '长安即事', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["豈得有書名，徒爲老帝京。","關中秋氣早，雨後夜涼生。","滄海身終泛，青門夢已行。","秦人縱相識，多少別離情。"]', '["豈得有书名，徒爲老帝京。","关中秋氣早，雨後夜涼生。","滄海身終泛，青门梦已行。","秦人縱相識，多少別離情。"]', '诗', 'shi', '', NULL, '長安即事 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b11d202-ac0d-448c-ac9d-7c78925db617', '送友人遊塞北', '送友人游塞北', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["朔野正秋風，前程見磧鴻。","日西身獨遠，山轉路無窮。","樹隔高關斷，沙連大漠空。","君看河外將，早晚擬平戎。"]', '["朔野正秋风，前程见磧鴻。","日西身独远，山轉路無窮。","樹隔高关斷，沙連大漠空。","君看河外將，早晚擬平戎。"]', '诗', 'shi', '', NULL, '送友人遊塞北 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f8047e7-b2b4-42b9-b711-6e75b37009b2', '陝府上姚中丞', '陝府上姚中丞', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["關東領藩鎮，[闕]下授旌旄。","覓句秋吟苦，酬恩夜坐勞。","天開吹角出，木落上樓高。","閑話錢塘郡，半年聽海潮。"]', '["关东領藩鎮，[闕]下授旌旄。","覓句秋吟苦，酬恩夜坐勞。","天开吹角出，木落上楼高。","闲話錢塘郡，半年听海潮。"]', '诗', 'shi', '', NULL, '陝府上姚中丞 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('796791e6-77e6-4ddc-90ae-f48a3fd4b0f5', '送供奉喻鍊師歸天目山', '送供奉喻鍊師归天目山', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["承恩雖內殿，得道本深山。","舉世相看老，孤峰獨自還。","溪來青壁裏，路在白雲間。","絕頂無人住，雙峰是舊關。"]', '["承恩雖內殿，得道本深山。","舉世相看老，孤峰独自還。","溪来青壁裏，路在白云间。","絕頂無人住，雙峰是旧关。"]', '诗', 'shi', '', NULL, '送供奉喻鍊師歸天目山 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f91a2347-7f92-4b09-92e5-a28032e2e614', '之任建安淥溪亭偶作二首 一', '之任建安淥溪亭偶作二首 一', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["入境當春務，農蠶事正殷。","逢溪難飲馬，度嶺更勞人。","想取烝黎泰，無過賦歛均。","不知成政後，誰是得爲鄰。"]', '["入境當春務，農蠶事正殷。","逢溪难饮马，度嶺更勞人。","想取烝黎泰，無過賦歛均。","不知成政後，誰是得爲鄰。"]', '诗', 'shi', '', NULL, '之任建安淥溪亭偶作二首 一 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d0930d4-7acc-4907-bd89-ed143dffdd95', '之任建安淥溪亭偶作二首 二', '之任建安淥溪亭偶作二首 二', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["維舟綠溪岸，繞郡白雲峰。","將幕連山起，人家向水重。","短才無獨見，長策未相逢。","所幸分堯理，烝民悉可封。"]', '["維舟綠溪岸，繞郡白云峰。","將幕連山起，人家向水重。","短才無独见，长策未相逢。","所幸分堯理，烝民悉可封。"]', '诗', 'shi', '', NULL, '之任建安淥溪亭偶作二首 二 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a371a06f-071f-4c0f-a01b-4c6fd1e77147', '送侯郎中任新定二首 一', '送侯郎中任新定二首 一', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["爲郎非白頭，作牧授滄洲。","江界乘潮入，山川值勝遊。","暑氣隨轉扇，涼月傍開樓。","便欲歸田里，拋官逐隱侯。"]', '["爲郎非白头，作牧授滄洲。","江界乘潮入，山川值勝游。","暑氣隨轉扇，涼月傍开楼。","便欲归田里，拋官逐隐侯。"]', '诗', 'shi', '', NULL, '送侯郎中任新定二首 一 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53bfce48-8e9b-430d-b274-ec311fbec21d', '送侯郎中任新定二首 二', '送侯郎中任新定二首 二', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["罷郎東出守，半路得浮舟。","大斾行當夏，桐江到未秋。","雲閑分島寺，濤靜見沙鷗。","誰伴臨清景，吟詩上郡樓。"]', '["罷郎东出守，半路得浮舟。","大斾行當夏，桐江到未秋。","云闲分島寺，濤静见沙鷗。","誰伴臨清景，吟诗上郡楼。"]', '诗', 'shi', '', NULL, '送侯郎中任新定二首 二 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c9af664-38c8-46fb-b0f7-0adb6a0db138', '送太學吳康仁及第南歸', '送太学吳康仁及第南归', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["因爲太學選，志業徹春闈。","首領諸生出，先登上第歸。","一榮猶未已，具慶且應稀。","縱馬行青草，臨岐脫白衣。","家遙楚國寄，帆對漢山飛。","知己盈華省，看君再發機。"]', '["因爲太学選，志業徹春闈。","首領諸生出，先登上第归。","一榮猶未已，具慶且應稀。","縱马行青草，臨岐脫白衣。","家遙楚国寄，帆对漢山飞。","知己盈华省，看君再發機。"]', '诗', 'shi', '', NULL, '送太學吳康仁及第南歸 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde02478-7088-4b6b-ab09-fa091b1c6d1c', '陝州題河上亭', '陝州題河上亭', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["岸擁洪流急，亭開清興長。","當軒河草晚，入坐水風涼。","獨鳥驚來客，孤雲觸去檣。","秋聲和遠雨，暮色帶微陽。","浪靜澄牕影，沙陰發簟光。","逍遙每盡日，誰識愛滄浪。"]', '["岸擁洪流急，亭开清兴长。","當軒河草晚，入坐水风涼。","独鸟驚来客，孤云觸去檣。","秋声和远雨，暮色带微陽。","浪静澄牕影，沙陰發簟光。","逍遙每尽日，誰識愛滄浪。"]', '诗', 'shi', '', NULL, '陝州題河上亭 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('119764a3-8f77-49f7-a47f-4c0104636f22', '留題姚氏山齋', '留題姚氏山斋', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["未厭棲林趣，猶懷濟世才。","閑眠知道在，高步會時來。","露滴從添硯，蟬吟便送杯。","亂書離縹帙，迸筍出苔莓。","異果因僧摘，幽窗爲燕開。","春遊何處盡，欲別幾遲回。"]', '["未厭棲林趣，猶懷濟世才。","闲眠知道在，高步會时来。","露滴從添硯，蟬吟便送杯。","亂书離縹帙，迸筍出苔莓。","異果因僧摘，幽窗爲燕开。","春游何处尽，欲別幾遲回。"]', '诗', 'shi', '', NULL, '留題姚氏山齋 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90925448-0a88-4f27-86dc-eff3920430c3', '長安書懷投知己', '长安书懷投知己', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["所學近雕蟲，知難謁至公。","徒隨衆人後，擬老一生中。","間歲家書到，經荒世業空。","心懸滄海斷，夢與白雲通。","玉漏聲連北，銀河氣極東。","關門迢遞月，禁苑寂寥鴻。","地廣身難束，時平道獨窮。","蕭條苔長雨，淅瀝葉危風。","久媿干朝客，多慚別釣翁。","因依非不忝，延薦況曾蒙。","與善應無替，垂恩本有終。","霜天搖落日，莫使逐孤蓬。"]', '["所学近雕蟲，知难謁至公。","徒隨衆人後，擬老一生中。","间歲家书到，經荒世業空。","心懸滄海斷，梦與白云通。","玉漏声連北，銀河氣極东。","关门迢遞月，禁苑寂寥鴻。","地廣身难束，时平道独窮。","蕭條苔长雨，淅瀝葉危风。","久媿干朝客，多慚別釣翁。","因依非不忝，延薦況曾蒙。","與善應無替，垂恩本有終。","霜天搖落日，莫使逐孤蓬。"]', '诗', 'shi', '', NULL, '長安書懷投知己 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df2d0ae0-7193-4124-afb4-9493ade54718', '送姚侍御充渭北掌書記', '送姚侍御充渭北掌书記', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["北境烽煙急，南山戰伐頻。","撫綏初易帥，參畫盡須人。","書記才偏稱，朝廷意更親。","繡衣行李日，綺陌別離塵。","報國將臨虜，之藩不離秦。","豸冠嚴在首，雄筆健隨身。","飲馬河聲暮，休兵塞色春。","敗亡仍暴骨，冤哭可傷神。","上策何當用，邊情此是真。","雕陰曾久客，拜送欲霑巾。"]', '["北境烽煙急，南山戰伐頻。","撫綏初易帥，參畫尽須人。","书記才偏稱，朝廷意更親。","繡衣行李日，綺陌別離塵。","報国將臨虜，之藩不離秦。","豸冠嚴在首，雄笔健隨身。","饮马河声暮，休兵塞色春。","敗亡仍暴骨，冤哭可傷神。","上策何當用，邊情此是真。","雕陰曾久客，拜送欲霑巾。"]', '诗', 'shi', '', NULL, '送姚侍御充渭北掌書記 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e24e9ae8-798d-4760-9676-b3e6f8d1db6c', '長安書情投知己', '长安书情投知己', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["陝服因詩句，從容已半年。","一從歸闕下，罕得到門前。","每候朝軒出，常看列宿懸。","重投期見獎，數首果蒙傳。","轉覺功宜倍，兼令住更堅。","都忘春暫醉，少省夜曾眠。","煩暑燈誰讀，孤雲業自專。","精華搜未竭，騷雅琢須全。","此事勤雖過，他謀拙莫先。","槐街勞白日，桂路在青天。","取第殊無序，還鄉可有緣。","旅情長越鳥，秋思幾秦蟬。","月色千樓滿，砧聲萬井連。","江山阻迢遞，時節暗推遷。","道即窮通守，才應始末憐。","書紳相戒語，藏篋贈行篇。","致主當齊聖，爲郎本是仙。","人心期際會，鳳翼許遷延。","畢竟良圖在，何妨逸性便。","幽齋中寢覺，珍木正陰圓。","隱几閑瞻夜，臨雲興渺然。","五陵供麗景，六義動花牋。","倘與潛生翼，寧非助化權。","免教垂素髪，歸種海隅田。"]', '["陝服因诗句，從容已半年。","一從归闕下，罕得到门前。","每候朝軒出，常看列宿懸。","重投期见獎，數首果蒙傳。","轉覺功宜倍，兼令住更堅。","都忘春暫醉，少省夜曾眠。","煩暑灯誰读，孤云業自專。","精华搜未竭，騷雅琢須全。","此事勤雖過，他謀拙莫先。","槐街勞白日，桂路在青天。","取第殊無序，還乡可有緣。","旅情长越鸟，秋思幾秦蟬。","月色千楼满，砧声万井連。","江山阻迢遞，时節暗推遷。","道即窮通守，才應始末怜。","书紳相戒語，藏篋贈行篇。","致主當齊聖，爲郎本是仙。","人心期際會，鳳翼許遷延。","畢竟良圖在，何妨逸性便。","幽斋中寢覺，珍木正陰圓。","隐几闲瞻夜，臨云兴渺然。","五陵供丽景，六義动花牋。","倘與潛生翼，寧非助化權。","免教垂素髪，归種海隅田。"]', '诗', 'shi', '', NULL, '長安書情投知己 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4135975e-abe0-4512-aa8f-2a2deafb0c9e', '府試丹浦非樂戰', '府試丹浦非乐戰', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["自古爲君道，垂衣致理難。","懷仁須去殺，用武即勝殘。","毒幟誅方及，兵臨釁可觀。","居來彭蠡固，戰罷洞庭寬。","雪國知天遠，霜林是血丹。","吾皇則堯典，薄伐至桑亁。"]', '["自古爲君道，垂衣致理难。","懷仁須去殺，用武即勝殘。","毒幟誅方及，兵臨釁可观。","居来彭蠡固，戰罷洞庭寬。","雪国知天远，霜林是血丹。","吾皇則堯典，薄伐至桑亁。"]', '诗', 'shi', '', NULL, '府試丹浦非樂戰 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dc22683-6954-493a-af61-8770d66cc7c5', '府試風雨聞雞', '府試风雨闻雞', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["不爲風雨變，雞德一何貞。","在暗長先覺，臨晨即自鳴。","陰霾方見信，頃刻詎移聲。","向晦如相警，知時似獨清。","蕭蕭和斷漏，喔喔報重城。","欲識詩人興，中含君子情。"]', '["不爲风雨变，雞德一何貞。","在暗长先覺，臨晨即自鳴。","陰霾方见信，頃刻詎移声。","向晦如相警，知时似独清。","蕭蕭和斷漏，喔喔報重城。","欲識诗人兴，中含君子情。"]', '诗', 'shi', '', NULL, '府試風雨聞雞 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19c1b125-f6b3-4a9d-9c67-be39388e5d54', '府試觀蘭亭圖', '府試观蘭亭圖', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["往會人何處，遺蹤事可觀。","林亭今日在，草木古春殘。","筆想吟中駐，杯疑飲後乾。","向青穿峻嶺，當白認回湍。","月影窗間夜，湖光枕上寒。","不知詩酒客，誰更慕前歡。"]', '["往會人何处，遺蹤事可观。","林亭今日在，草木古春殘。","笔想吟中駐，杯疑饮後乾。","向青穿峻嶺，當白認回湍。","月影窗间夜，湖光枕上寒。","不知诗酒客，誰更慕前歡。"]', '诗', 'shi', '', NULL, '府試觀蘭亭圖 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('829b29d0-1caf-4416-83de-141271b04ee4', '府試老人星見', '府試老人星见', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["良宵出戶庭，極目向青冥。","海內逢康日，天邊見壽星。","臨空遙的的，竟曉獨熒熒。","春後先依景，秋來忽近丁。","垂休臨有道，作瑞掩前經。","豈比周王夢，徒言得九齡。"]', '["良宵出戶庭，極目向青冥。","海內逢康日，天邊见壽星。","臨空遙的的，竟晓独熒熒。","春後先依景，秋来忽近丁。","垂休臨有道，作瑞掩前經。","豈比周王梦，徒言得九齡。"]', '诗', 'shi', '', NULL, '府試老人星見 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0abfb71-c78e-4401-9c92-2b761693f2f8', '省試振鷺', '省試振鷺', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["有鳥生江浦，霜華作羽翰。","君臣將比潔，朝野共相歡。","月影林梢下，冰光水際殘。","翻飛時共樂，飲啄道皆安。","逈翥宜高詠，羣棲入靜看。","由來鴛鷺侶，濟濟列千官。"]', '["有鸟生江浦，霜华作羽翰。","君臣將比潔，朝野共相歡。","月影林梢下，冰光水際殘。","翻飞时共乐，饮啄道皆安。","逈翥宜高詠，羣棲入静看。","由来鴛鷺侶，濟濟列千官。"]', '诗', 'shi', '', NULL, '省試振鷺 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de17960a-cbb1-4d67-a3d1-184dd2c8fe47', '寄辛明府', '寄辛明府', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["何處無苛政，東南有子男。","細將朝客說，須是邑人諳。","別業空經稔，歸田獨未甘。","目凝煙積樹，心貯月明潭。","曉鼓愁方亂，春山睡正酣。","不任啼鳥思，鄉社欲桑蠶。"]', '["何处無苛政，东南有子男。","細將朝客说，須是邑人諳。","別業空經稔，归田独未甘。","目凝煙積樹，心貯月明潭。","晓鼓愁方亂，春山睡正酣。","不任啼鸟思，乡社欲桑蠶。"]', '诗', 'shi', '', NULL, '寄辛明府 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b28557f4-6ffe-4102-b993-81513aca309c', '苑中題友人林亭', '苑中題友人林亭', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["井邑藏嵓穴，幽棲趣若何。","春篁抽筍密，夏鳥雜雛多。","坐有清風至，林無暑氣過。","亂書還就葉，真飲不聽歌。","片影明紅蘚，斜陰映綠蘿。","雄文終可惜，莫更棄高科。"]', '["井邑藏嵓穴，幽棲趣若何。","春篁抽筍密，夏鸟杂雛多。","坐有清风至，林無暑氣過。","亂书還就葉，真饮不听歌。","片影明紅蘚，斜陰映綠蘿。","雄文終可惜，莫更棄高科。"]', '诗', 'shi', '', NULL, '苑中題友人林亭 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fce6e119-a8ea-4bfe-93fe-6a4252d2fb6a', '投京兆府試官任文學先輩', '投京兆府試官任文学先輩', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["高興每論詩，非才獨見推。","應當明試日，不比暗投時。","出口人皆信，操心自可知。","孤單雖有託，際會別無期。","取舍知由己，窮通斷在茲。","賤身何足數，公道自難欺。","澤國違甘旨，漁舟積夢思。","長安未歸去，爲倚鑒妍媸。"]', '["高兴每論诗，非才独见推。","應當明試日，不比暗投时。","出口人皆信，操心自可知。","孤單雖有託，際會別無期。","取舍知由己，窮通斷在茲。","賤身何足數，公道自难欺。","澤国違甘旨，漁舟積梦思。","长安未归去，爲倚鑒妍媸。"]', '诗', 'shi', '', NULL, '投京兆府試官任文學先輩 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca567bee-ce66-429e-810b-f2c0bf420750', '宋少府東溪泛舟', '宋少府东溪泛舟', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["登岸還入舟，水禽驚笑語。","晚葉低衆色，濕雲帶繁暑。","落日乘醉歸，溪流復幾許。"]', '["登岸還入舟，水禽驚笑語。","晚葉低衆色，濕云带繁暑。","落日乘醉归，溪流复幾許。"]', '诗', 'shi', '', NULL, '宋少府東溪泛舟 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcb48b29-ad6c-475f-a489-8b0e493a3ca1', '聞北虜入靈州二首 一', '闻北虜入靈州二首 一', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["河冰一夜合，虜騎入靈州。","歲歲徴兵去，難防塞草秋。"]', '["河冰一夜合，虜騎入靈州。","歲歲徴兵去，难防塞草秋。"]', '诗', 'shi', '', NULL, '聞北虜入靈州二首 一 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc1a9ed-4053-4c88-9c57-2144e58e34b5', '聞北虜入靈州二首 二', '闻北虜入靈州二首 二', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["見說靈州戰，沙中血未乾。","將軍日告急，走馬向長安。"]', '["见说靈州戰，沙中血未乾。","將軍日告急，走马向长安。"]', '诗', 'shi', '', NULL, '聞北虜入靈州二首 二 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9442dc86-6661-43b8-87b9-31df50b0a05a', '送友人下第歸感懷', '送友人下第归感懷', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["帝里春無意，歸山對物華。","即應來日去，九陌踏槐花。"]', '["帝里春無意，归山对物华。","即應来日去，九陌踏槐花。"]', '诗', 'shi', '', NULL, '送友人下第歸感懷 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72133e79-bc65-4686-bb38-1abc76457e3f', '贈桂林友人', '贈桂林友人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["君家桂林住，日伐桂枝炊。","何事東堂樹，年年待一枝。"]', '["君家桂林住，日伐桂枝炊。","何事东堂樹，年年待一枝。"]', '诗', 'shi', '', NULL, '贈桂林友人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04971c17-5c15-4e04-b2a5-f8cdfc63f1a2', '長安感懷', '长安感懷', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["一第知何日，全家待此身。","空將灞陵酒，酌送向東人。"]', '["一第知何日，全家待此身。","空將灞陵酒，酌送向东人。"]', '诗', 'shi', '', NULL, '長安感懷 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2652529-6311-4778-b342-f292fb420889', '題長孫桐樹', '題长孫桐樹', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["一去龍門側，千年鳳影移。","空餘剪圭處，無復在孫枝。"]', '["一去龙门側，千年鳳影移。","空餘剪圭处，無复在孫枝。"]', '诗', 'shi', '', NULL, '題長孫桐樹 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6144ae0-3bcf-4503-b58d-9abf24d6608c', '渡漢江', '渡漢江', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["嶺外音書絕，經年復歷春。","近鄉情更怯，不敢問來人。"]', '["嶺外音书絕，經年复歷春。","近乡情更怯，不敢问来人。"]', '诗', 'shi', '', NULL, '渡漢江 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73ce85e2-72a1-4042-a809-172177db3da4', '嵩山夜還', '嵩山夜還', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["家住東臯去，好採舊山薇。","自省遊泉石，何曾不夜歸。"]', '["家住东臯去，好採旧山薇。","自省游泉石，何曾不夜归。"]', '诗', 'shi', '', NULL, '嵩山夜還 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31187640-bb91-4ac9-85cc-7115be6c4e5b', '暮秋宿清源上人院', '暮秋宿清源上人院', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["野客愁來日，山房木落中。","微風生夜半，積雨向秋終。","證道方離法，安禪不住空。","迷途將覺路，語默見西東。"]', '["野客愁来日，山房木落中。","微风生夜半，積雨向秋終。","證道方離法，安禪不住空。","迷途將覺路，語默见西东。"]', '诗', 'shi', '', NULL, '暮秋宿清源上人院 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5eca67c-e1db-40f9-bd4b-920f21734996', '秋夜宿重本上人院', '秋夜宿重本上人院', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["却憶涼堂坐，明河幾度流。","安禪逢小暑，抱疾入高秋。","水國曾重講，雲林半舊遊。","此來看月落，還似道相求。"]', '["却憶涼堂坐，明河幾度流。","安禪逢小暑，抱疾入高秋。","水国曾重講，云林半旧游。","此来看月落，還似道相求。"]', '诗', 'shi', '', NULL, '秋夜宿重本上人院 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5e02e3f-9588-4beb-8278-411eddeb2662', '贈立規上人', '贈立規上人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["竹向空齋合，無僧在四鄰。","去雲離坐石，斜月到禪身。","樹老風終夜，山寒雪見春。","不知諸祖後，傳印是何人。"]', '["竹向空斋合，無僧在四鄰。","去云離坐石，斜月到禪身。","樹老风終夜，山寒雪见春。","不知諸祖後，傳印是何人。"]', '诗', 'shi', '', NULL, '贈立規上人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4051ba4e-bf73-46d1-9ed6-5bd0a31a849e', '蘇州寒食日送人歸覲', '蘇州寒食日送人归覲', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["江城寒食下，花木慘離魂。","幾宿投山寺，孤帆過海門。","□聲潑火雨，柳色禁煙村。","定看堂高後，斑衣滅淚痕。"]', '["江城寒食下，花木慘離魂。","幾宿投山寺，孤帆過海门。","□声潑火雨，柳色禁煙村。","定看堂高後，斑衣滅泪痕。"]', '诗', 'shi', '', NULL, '蘇州寒食日送人歸覲 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('801df974-5d29-4119-aa6a-6a638ef67544', '即席送許□之曹南省兄', '即席送許□之曹南省兄', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["梅爛荷圓六月天，歸帆高背虎丘煙。","到時自見成行雁，別處休聽滿樹蟬。","賣劒爲賒吳市酒，攜家猶借洞庭船。","待看春榜來江外，名占蓬萊第幾仙。"]', '["梅爛荷圓六月天，归帆高背虎丘煙。","到时自见成行雁，別处休听满樹蟬。","賣劒爲賒吳市酒，携家猶借洞庭船。","待看春榜来江外，名占蓬萊第幾仙。"]', '诗', 'shi', '', NULL, '即席送許□之曹南省兄 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25c0a253-706f-4ab8-94af-cbaacceffd38', '送羅著作兩浙按獄', '送羅著作兩浙按獄', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["使印星車適舊遊，陶潛今日在瀛洲。","科條盡曉三千罪，囹圄應空十二州。","舊綬有香籠驛馬，皇華無暇狎沙鷗。","歸來重過姑蘇郡，莫忘題名在虎丘。"]', '["使印星车適旧游，陶潛今日在瀛洲。","科條尽晓三千罪，囹圄應空十二州。","旧綬有香籠驛马，皇华無暇狎沙鷗。","归来重過姑蘇郡，莫忘題名在虎丘。"]', '诗', 'shi', '', NULL, '送羅著作兩浙按獄 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c2610bf-d41b-46b3-ba0b-925ddf294ae8', '下第後屏居書懷寄張侍御', '下第後屏居书懷寄張侍御', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["刖足豈一生，良工隔千里。","故山彭澤上，歸夢向汾水。","低催神氣盡，僮僕心亦耻。","未達誰不知，達者多忘此。","行年忽已壯，去老年更幾。","功名如不彰，身歿豈爲鬼。","纔看芳草歇，即歎涼風起。","驄馬未來朝，嘶聲尚在耳。"]', '["刖足豈一生，良工隔千里。","故山彭澤上，归梦向汾水。","低催神氣尽，僮僕心亦耻。","未達誰不知，達者多忘此。","行年忽已壯，去老年更幾。","功名如不彰，身歿豈爲鬼。","纔看芳草歇，即歎涼风起。","驄马未来朝，嘶声尚在耳。"]', '诗', 'shi', '', NULL, '下第後屏居書懷寄張侍御 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52c11e55-22fa-4efd-93c6-d7669a98196d', '荅韓中丞容不飲酒', '荅韓中丞容不饮酒', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["老大成名仍足病，強聽絲竹亦無歡。","高情太守容閑坐，借與青山盡日看。"]', '["老大成名仍足病，強听絲竹亦無歡。","高情太守容闲坐，借與青山尽日看。"]', '诗', 'shi', '', NULL, '荅韓中丞容不飲酒 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('616014db-3d2e-465e-81bf-cef3aa2cf32a', '句', '句', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["只將五字句，用破一生心。","楚里八千里，槃槃此都會。","巍峩數里城，遠水相映帶。"]', '["只將五字句，用破一生心。","楚里八千里，槃槃此都會。","巍峩數里城，远水相映带。"]', '诗', 'shi', '', NULL, '句 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07e12fb9-a0f7-4cba-81a3-65b03dbf4639', '冬至後西湖泛舟看斷冰偶成長句', '冬至後西湖泛舟看斷冰偶成长句', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["一陽生後陰飆竭，湖上層冰看折時。","雲母扇搖當殿色，珊瑚樹碎滿盤枝。","斜汀藻動魚應覺，極浦波生鴈未知。","山影淺中留瓦礫，日光寒外送漣漪。","崖崩葦岸縱橫散，篙蹙蘭舟片段隨。","曾向黃河望衝激，大鵬飛起雪風吹。"]', '["一陽生後陰飆竭，湖上層冰看折时。","云母扇搖當殿色，珊瑚樹碎满盤枝。","斜汀藻动鱼應覺，極浦波生鴈未知。","山影淺中留瓦礫，日光寒外送漣漪。","崖崩葦岸縱橫散，篙蹙蘭舟片段隨。","曾向黄河望衝激，大鵬飞起雪风吹。"]', '诗', 'shi', '', NULL, '冬至後西湖泛舟看斷冰偶成長句 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('817c933e-49a2-40eb-acd7-4565e8246a15', '陽羨春歌', '陽羨春歌', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["石亭梅花落如積，玉蘚斕班竹姑赤。","祝陵有酒清若空，煮稬蒸魚作寒食。","長橋新晴好天氣，兩市兒郎[櫂]船戲。","溪頭鐃鼓狂殺儂，青蓋紅裙偶相值。","風光何處最可憐，邵家高樓白日邊。","樓下遊人顏色喜，溪南黃帽應羞死。","三月未有二月殘，靈龜可信渰水乾。","葑草青青促歸去，短簫橫笛說明年。"]', '["石亭梅花落如積，玉蘚斕班竹姑赤。","祝陵有酒清若空，煮稬蒸鱼作寒食。","长橋新晴好天氣，兩市兒郎[櫂]船戲。","溪头鐃鼓狂殺儂，青蓋紅裙偶相值。","风光何处最可怜，邵家高楼白日邊。","楼下游人顏色喜，溪南黄帽應羞死。","三月未有二月殘，靈龟可信渰水乾。","葑草青青促归去，短簫橫笛说明年。"]', '诗', 'shi', '', NULL, '陽羨春歌 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc39a4f-2d24-4fde-aef0-7b7c6840c604', '茶山貢焙歌', '茶山貢焙歌', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["使君愛客情無已，客在金臺價無比。","春風三月貢茶時，盡逐紅旌到山裏。","焙中清曉朱門開，筐箱漸見新芽來。","陵煙觸露不停探，官家赤印連帖催。","朝飢暮匐誰興哀，喧闐競納不盈掬。","一時一餉還成堆，蒸之馥之香勝梅，研膏架動轟如雷。","茶成拜表貢天子，萬人爭噉春山摧。","驛騎鞭聲砉流電，半夜驅夫誰復見。","十日王程路四千，到時須及清明宴。","吾君可謂納諫君，諫官不諫何由聞。","九重城裏雖玉食，天涯吏役長紛紛。","使君憂民慘容色，就焙嘗茶坐諸客。","幾回到口重咨嗟，嫩綠鮮芳出何力。","山中有酒亦有歌，樂營房戶皆仙家。","仙家十隊酒百斛，金絲宴饌隨經過。","使君是日憂思多，客亦無言徵綺羅。","殷勤繞焙復長歎，官府例成期如何。","吳民吳民莫憔悴，使君作相期蘇爾。"]', '["使君愛客情無已，客在金台價無比。","春风三月貢茶时，尽逐紅旌到山裏。","焙中清晓朱门开，筐箱漸见新芽来。","陵煙觸露不停探，官家赤印連帖催。","朝飢暮匐誰兴哀，喧闐競納不盈掬。","一时一餉還成堆，蒸之馥之香勝梅，研膏架动轟如雷。","茶成拜表貢天子，万人爭噉春山摧。","驛騎鞭声砉流電，半夜驱夫誰复见。","十日王程路四千，到时須及清明宴。","吾君可謂納諫君，諫官不諫何由闻。","九重城裏雖玉食，天涯吏役长紛紛。","使君憂民慘容色，就焙嘗茶坐諸客。","幾回到口重咨嗟，嫩綠鲜芳出何力。","山中有酒亦有歌，乐營房戶皆仙家。","仙家十隊酒百斛，金絲宴饌隨經過。","使君是日憂思多，客亦無言徵綺羅。","殷勤繞焙复长歎，官府例成期如何。","吳民吳民莫憔悴，使君作相期蘇爾。"]', '诗', 'shi', '', NULL, '茶山貢焙歌 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd17641b-9782-4779-8ddd-7d52cebeedf4', '夏日登信州北樓', '夏日登信州北楼', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["高樓上長望，百里見靈山。","雨歇河珠定，雲開谷鳥還。","田苗映林合，牛犢傍村閑。","始得消憂處，蟬聲催入關。"]', '["高楼上长望，百里见靈山。","雨歇河珠定，云开谷鸟還。","田苗映林合，牛犢傍村闲。","始得消憂处，蟬声催入关。"]', '诗', 'shi', '', NULL, '夏日登信州北樓 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28efa2ac-79b8-4230-ae11-e5b97a066d6c', '遊天柱觀', '游天柱观', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["聽鐘到靈觀，仙子喜相尋。","茅洞幾千載，水聲寒至今。","讀碑丹井上，坐石澗亭陰。","清興未云盡，煙霞生夕林。"]', '["听鐘到靈观，仙子喜相尋。","茅洞幾千載，水声寒至今。","读碑丹井上，坐石澗亭陰。","清兴未云尽，煙霞生夕林。"]', '诗', 'shi', '', NULL, '遊天柱觀 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61bbd58-ee62-4786-a541-38fb136aecbf', '酬劉谷除夜見寄', '酬劉谷除夜见寄', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["坐恐三更至，流年此夜分。","客心無限事，愁雨不堪聞。","灞上家殊遠，爐前酒暫醺。","劉郎亦多恨，詩憶故山雲。"]', '["坐恐三更至，流年此夜分。","客心無限事，愁雨不堪闻。","灞上家殊远，爐前酒暫醺。","劉郎亦多恨，诗憶故山云。"]', '诗', 'shi', '', NULL, '酬劉谷除夜見寄 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae3ee4a1-bd33-4e68-923f-564673f318bf', '元日作', '元日作', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["鏘鏘華駟客，門館賀新正。","野雪江山霽，微風竹樹清。","蕪庭春意曉，殘枿燼煙生。","忽憶王孫草，前年在帝京。"]', '["鏘鏘华駟客，门館賀新正。","野雪江山霽，微风竹樹清。","蕪庭春意晓，殘枿燼煙生。","忽憶王孫草，前年在帝京。"]', '诗', 'shi', '', NULL, '元日作 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb114637-7666-49a6-a6e5-5f12718a1fdd', '酬劉谷立春日吏隱亭見寄', '酬劉谷立春日吏隐亭见寄', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["孤亭遙帶寺，靜者獨登臨。","楚霽江流慢，春歸澤氣陰。","野田青牧馬，幽竹暖鳴禽。","日日年光盡，何堪故國心。"]', '["孤亭遙带寺，静者独登臨。","楚霽江流慢，春归澤氣陰。","野田青牧马，幽竹暖鳴禽。","日日年光尽，何堪故国心。"]', '诗', 'shi', '', NULL, '酬劉谷立春日吏隱亭見寄 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54732191-7d84-438e-8abe-3a219ec8f642', '宿憐上人房', '宿怜上人房', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["重公舊相識，一夕話勞生。","藥裹關身病，經函寄道情。","嶽寒當寺色，灘夜入樓聲。","不待移文誚，三年別赤城。"]', '["重公旧相識，一夕話勞生。","藥裹关身病，經函寄道情。","嶽寒當寺色，灘夜入楼声。","不待移文誚，三年別赤城。"]', '诗', 'shi', '', NULL, '宿憐上人房 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e04892-3305-4692-85bb-550117d07d68', '園居', '园居', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["暮雨楊雄宅，秋風向秀園。","不聞砧杵動，時看桔槔翻。","釣下魚初食，船移鴨蹔喧。","橘寒才弄色，須帶早霜繁。"]', '["暮雨楊雄宅，秋风向秀园。","不闻砧杵动，时看桔槔翻。","釣下鱼初食，船移鴨蹔喧。","橘寒才弄色，須带早霜繁。"]', '诗', 'shi', '', NULL, '園居 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4af9edd-641f-4773-8d9f-d1f9c9480321', '中元夜', '中元夜', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["江南水寺中元夜，金粟欄邊見月娥。","紅燭影迴仙態近，翠鬟光動看人多。","香飄彩殿凝蘭麝，露繞輕衣雜綺羅。","湘水夜空巫峽遠，不知歸路欲如何。"]', '["江南水寺中元夜，金粟欄邊见月娥。","紅燭影迴仙態近，翠鬟光动看人多。","香飄彩殿凝蘭麝，露繞轻衣杂綺羅。","湘水夜空巫峽远，不知归路欲如何。"]', '诗', 'shi', '', NULL, '中元夜 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('346f418b-b2ef-45a1-8178-2cdb2ee12d6c', '贈羽林將軍', '贈羽林將軍', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["虬鬚憔悴羽林郎，曾入甘泉侍武皇。","鵰沒夜雲知御苑，馬隨仙仗識天香。","五湖歸去孤舟月，六國平來兩鬢霜。","唯有桓伊江上笛，臥吹三弄送殘陽。"]', '["虬鬚憔悴羽林郎，曾入甘泉侍武皇。","鵰沒夜云知御苑，马隨仙仗識天香。","五湖归去孤舟月，六国平来兩鬢霜。","唯有桓伊江上笛，臥吹三弄送殘陽。"]', '诗', 'shi', '', NULL, '贈羽林將軍 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d32635e-a4dd-42b2-b01d-953467116556', '送人之嶺南', '送人之嶺南', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["關山迢遰古交州，歲[晏]憐君走馬遊。","謝氏海邊逢素女，越王潭上見青牛。","嵩臺月照啼猨曙，石室煙含古桂秋。","迴望長安五千里，刺桐花下莫淹留。"]', '["关山迢遰古交州，歲[晏]怜君走马游。","謝氏海邊逢素女，越王潭上见青牛。","嵩台月照啼猨曙，石室煙含古桂秋。","迴望长安五千里，刺桐花下莫淹留。"]', '诗', 'shi', '', NULL, '送人之嶺南 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e6edac4-29e5-4b04-8cef-99434afa9df0', '晚泊松江驛', '晚泊松江驛', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["片帆孤客晚夷猶，紅蓼花前水驛秋。","歲月方驚離別盡，煙波仍駐古今愁。","雲陰故國山川暮，潮落空江網罟收。","還有吳娃舊歌曲，櫂聲遙散採菱舟。"]', '["片帆孤客晚夷猶，紅蓼花前水驛秋。","歲月方驚離別尽，煙波仍駐古今愁。","云陰故国山川暮，潮落空江網罟收。","還有吳娃旧歌曲，櫂声遙散採菱舟。"]', '诗', 'shi', '', NULL, '晚泊松江驛 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76d6f0f4-302e-4bec-8fd7-44a713f15a38', '江亭春霽', '江亭春霽', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["江蘺漠漠荇田田，江上雲亭霽景鮮。","蜀客帆檣背歸燕，楚山花木怨啼鵑。","春風掩映千門柳，曉色淒涼萬井煙。","金磬泠泠水南寺，上方僧室翠微連。"]', '["江蘺漠漠荇田田，江上云亭霽景鲜。","蜀客帆檣背归燕，楚山花木怨啼鵑。","春风掩映千门柳，晓色淒涼万井煙。","金磬泠泠水南寺，上方僧室翠微連。"]', '诗', 'shi', '', NULL, '江亭春霽 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('875f8ffa-ebb3-47e1-acba-48f498ac629e', '早秋書懷', '早秋书懷', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["高梧一葉墜涼天，宋玉悲秋淚灑然。","霜拂楚山頻見菊，雨零溪樹忽無蟬。","虛村暮角催殘日，近寺歸僧寄野泉。","青鬢已緣多病鑷，可堪風景促流年。"]', '["高梧一葉墜涼天，宋玉悲秋泪灑然。","霜拂楚山頻见菊，雨零溪樹忽無蟬。","虛村暮角催殘日，近寺归僧寄野泉。","青鬢已緣多病鑷，可堪风景促流年。"]', '诗', 'shi', '', NULL, '早秋書懷 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08227cbe-b546-4554-9d3a-3bc77b2a1b8a', '爲妻作生日寄意', '爲妻作生日寄意', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["謝家生日好風煙，柳暖花春二月天。","金鳳對翹雙翡翠，蜀琴初上七絲弦。","鴛鴦交頸期千歲，琴瑟諧和願百年。","應恨客程歸未得，綠窗江淚冷涓涓。"]', '["謝家生日好风煙，柳暖花春二月天。","金鳳对翹雙翡翠，蜀琴初上七絲弦。","鴛鴦交頸期千歲，琴瑟諧和願百年。","應恨客程归未得，綠窗江泪冷涓涓。"]', '诗', 'shi', '', NULL, '爲妻作生日寄意 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('369c801b-1e0a-4ecd-b02c-9c7e1f6aa0df', '重陽日寄浙東諸從事', '重陽日寄浙东諸從事', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["野人多病門長掩，荒圃重陽菊自開。","愁裏又聞清笛怨，望中難見白衣來。","元瑜正及從軍樂，甯戚誰憐叩角哀。","紅斾紛紛碧江暮，知君醉下望鄉臺。"]', '["野人多病门长掩，荒圃重陽菊自开。","愁裏又闻清笛怨，望中难见白衣来。","元瑜正及從軍乐，甯戚誰怜叩角哀。","紅斾紛紛碧江暮，知君醉下望乡台。"]', '诗', 'shi', '', NULL, '重陽日寄浙東諸從事 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ca95409-b8b5-4ca5-a635-3e83b7dcd220', '和湖州杜員外冬至日白蘋洲見憶', '和湖州杜員外冬至日白蘋洲见憶', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["白蘋亭上一陽生，謝朓新裁錦繡成。","千嶂雪消溪影淥，幾家梅綻海波清。","已知鷗鳥長來狎，可許汀洲獨有名。","多媿龍門重招引，即拋田舍棹舟行。"]', '["白蘋亭上一陽生，謝朓新裁錦繡成。","千嶂雪消溪影淥，幾家梅綻海波清。","已知鷗鸟长来狎，可許汀洲独有名。","多媿龙门重招引，即拋田舍棹舟行。"]', '诗', 'shi', '', NULL, '和湖州杜員外冬至日白蘋洲見憶 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73f298fc-c893-4e6c-9b94-8ed9a4a97158', '上裴晉公', '上裴晉公', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["四朝憂國鬢如絲，龍馬精神海鶴姿。","天上玉書傳詔夜，陣前金甲受降時。","曾經庾亮三秋月，下盡羊曇兩路碁。","惆悵舊堂扃綠野，夕陽無限鳥飛遲。"]', '["四朝憂国鬢如絲，龙马精神海鹤姿。","天上玉书傳詔夜，陣前金甲受降时。","曾經庾亮三秋月，下尽羊曇兩路碁。","惆悵旧堂扃綠野，夕陽無限鸟飞遲。"]', '诗', 'shi', '', NULL, '上裴晉公 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15d1ebdb-2b3a-45cc-b5d0-575ac1276136', '錢塘青山題李隱居西齋', '錢塘青山題李隐居西斋', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["小隱西齋爲客開，翠蘿深處遍青苔。","林間掃石安碁局，巖下分泉遰酒杯。","蘭葉露光秋月上，蘆花風起夜潮來。","湖山遶屋猶嫌淺，欲櫂漁舟近釣臺。"]', '["小隐西斋爲客开，翠蘿深处遍青苔。","林间掃石安碁局，巖下分泉遰酒杯。","蘭葉露光秋月上，蘆花风起夜潮来。","湖山遶屋猶嫌淺，欲櫂漁舟近釣台。"]', '诗', 'shi', '', NULL, '錢塘青山題李隱居西齋 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6797bc8-dd2d-461a-a3ce-b4aa924f3539', '友人適越路過桐廬寄題江驛', '友人適越路過桐廬寄題江驛', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["桐廬縣前洲渚平，桐廬江上晚潮生。","莫言獨有山川秀，過日仍聞官長清。","麥隴虛涼當水店，鱸魚鮮美稱蓴羹。","王孫客棹殘春去，相送河橋羨此行。"]', '["桐廬縣前洲渚平，桐廬江上晚潮生。","莫言独有山川秀，過日仍闻官长清。","麦隴虛涼當水店，鱸鱼鲜美稱蓴羹。","王孫客棹殘春去，相送河橋羨此行。"]', '诗', 'shi', '', NULL, '友人適越路過桐廬寄題江驛 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5b18759-908d-456b-bd56-6e670bae5d25', '送劉谷', '送劉谷', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["村橋西路雪初晴，雲暖沙乾馬足輕。","寒澗渡頭芳草色，新梅嶺外鷓鴣聲。","郵亭已送輕車發，山館誰將候火迎。","落日千峰轉迢遰，知君回首望高城。"]', '["村橋西路雪初晴，云暖沙乾马足轻。","寒澗渡头芳草色，新梅嶺外鷓鴣声。","郵亭已送轻车發，山館誰將候火迎。","落日千峰轉迢遰，知君回首望高城。"]', '诗', 'shi', '', NULL, '送劉谷 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb19acb-618c-4920-a19e-cd84e763d1e9', '七夕', '七夕', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["烏鵲橋頭雙扇開，年年一度過河來。","莫嫌天上稀相見，猶勝人間去不回。","欲減煙花饒俗世，暫煩煙月掩粧臺。","別時舊路長清淺，豈肯離情似死灰。"]', '["烏鵲橋头雙扇开，年年一度過河来。","莫嫌天上稀相见，猶勝人间去不回。","欲減煙花饒俗世，暫煩煙月掩粧台。","別时旧路长清淺，豈肯離情似死灰。"]', '诗', 'shi', '', NULL, '七夕 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('392b0510-cded-4247-8449-2952af101d2c', '秦處士移家富春發樟亭懷寄', '秦处士移家富春發樟亭懷寄', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["潮落空江洲渚生，知君已上富春亭。","嘗聞郭邑山多秀，更說官僚眼盡青。","離別幾宵魂耿耿，相思一座髪星星。","仙翁白石高歌調，無復松齋半夜聽。"]', '["潮落空江洲渚生，知君已上富春亭。","嘗闻郭邑山多秀，更说官僚眼尽青。","離別幾宵魂耿耿，相思一座髪星星。","仙翁白石高歌調，無复松斋半夜听。"]', '诗', 'shi', '', NULL, '秦處士移家富春發樟亭懷寄 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c1956a7-e88c-4515-b7bb-6b149bb2b598', '故洛陽城', '故洛陽城', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["胡兵一動朔方塵，不使鑾輿此重巡。","清洛但流嗚咽水，上陽深鎖寂寥春。","雲收少室初晴雨，柳拂中橋晚渡津。","欲問升平無故老，鳳樓回首落花頻。"]', '["胡兵一动朔方塵，不使鑾輿此重巡。","清洛但流嗚咽水，上陽深鎖寂寥春。","云收少室初晴雨，柳拂中橋晚渡津。","欲问升平無故老，鳳楼回首落花頻。"]', '诗', 'shi', '', NULL, '故洛陽城 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a95adb4a-9cbf-42fe-8814-a93153b1a160', '紫極宮上元齋次呈諸道流', '紫極宮上元斋次呈諸道流', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["碧簡朝天章奏頻，清宮髣髴降靈真。","五龍金角向星斗，三洞玉音愁鬼神。","風拂亂燈山磬□，露霑仙杏石壇春。","明朝醮罷羽客散，塵土滿城空世人。"]', '["碧簡朝天章奏頻，清宮髣髴降靈真。","五龙金角向星斗，三洞玉音愁鬼神。","风拂亂灯山磬□，露霑仙杏石壇春。","明朝醮罷羽客散，塵土满城空世人。"]', '诗', 'shi', '', NULL, '紫極宮上元齋次呈諸道流 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90956415-a133-49ae-ba98-e8d7ad172c43', '立春一日江村偶興', '立春一日江村偶兴', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["舊曆年光看卷盡，立春何用更相催。","江邊野店寒無色，竹外孤村坐見梅。","山雪乍晴嵐翠起，漁家向晚笛聲哀。","南州近有秦中使，聞道胡兵索戰來。"]', '["旧曆年光看卷尽，立春何用更相催。","江邊野店寒無色，竹外孤村坐见梅。","山雪乍晴嵐翠起，漁家向晚笛声哀。","南州近有秦中使，闻道胡兵索戰来。"]', '诗', 'shi', '', NULL, '立春一日江村偶興 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fee5f1d-b9dc-4f9b-bdc1-9a8ac8c88084', '立秋後自京歸家', '立秋後自京归家', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["籬落秋歸見豆花，竹門當水岸橫槎。","松齋一雨宜清簟，佛室孤燈對絳紗。","盡日抱愁跧似鼠，移時不動嬾於虵。","西江近有鱸魚否，張翰扁舟始到家。"]', '["籬落秋归见豆花，竹门當水岸橫槎。","松斋一雨宜清簟，佛室孤灯对絳紗。","尽日抱愁跧似鼠，移时不动嬾於虵。","西江近有鱸鱼否，張翰扁舟始到家。"]', '诗', 'shi', '', NULL, '立秋後自京歸家 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c02bff12-a87e-4c89-ae16-d84276464bd4', '奉陪裴相公重陽日遊安樂池亭', '奉陪裴相公重陽日游安乐池亭', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["絳霄輕靄翊三台，稽阮襟懷管樂才。","蓮沼昔爲王儉府，菊籬今作孟嘉杯。","寧知北闕元勳在，却引東山舊客來。","自笑吐茵還酩酊，日斜空從絳衣迴。"]', '["絳霄轻靄翊三台，稽阮襟懷管乐才。","蓮沼昔爲王儉府，菊籬今作孟嘉杯。","寧知北闕元勳在，却引东山旧客来。","自笑吐茵還酩酊，日斜空從絳衣迴。"]', '诗', 'shi', '', NULL, '奉陪裴相公重陽日遊安樂池亭 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b2e31d7-b0ab-4585-9284-40e1fff9b193', '淛河館', '淛河館', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["雨濕菰蒲斜日明，茅廚煮繭掉車聲。","青蛇上竹一種色，黃蝶隔溪無限情。","何處樵漁將遠餉，故園田土憶春耕。","千峰萬瀨水潏潏，羸馬此中愁獨行。"]', '["雨濕菰蒲斜日明，茅廚煮繭掉车声。","青蛇上竹一種色，黄蝶隔溪無限情。","何处樵漁將远餉，故园田土憶春耕。","千峰万瀨水潏潏，羸马此中愁独行。"]', '诗', 'shi', '', NULL, '淛河館 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bfe7dc1-0eb7-4e8b-a2ad-c6b4c319d0d5', '春日題山家', '春日題山家', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["偶與樵人熟，春殘日日來。","依崗尋紫蕨，挽樹得青梅。","燕靜銜泥起，蜂喧抱蘂回。","嫩茶重攪綠，新酒畧炊醅。","漠漠蠶生紙，涓涓水弄苔。","丁香政堪結，留步小庭隈。"]', '["偶與樵人熟，春殘日日来。","依崗尋紫蕨，挽樹得青梅。","燕静銜泥起，蜂喧抱蘂回。","嫩茶重攪綠，新酒畧炊醅。","漠漠蠶生紙，涓涓水弄苔。","丁香政堪結，留步小庭隈。"]', '诗', 'shi', '', NULL, '春日題山家 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f9f322c-cdf0-47a0-ac0f-e9e5183c80c7', '江亭晚望', '江亭晚望', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["碧天涼冷鴈來疎，閑望江雲思有餘。","秋館池亭荷葉後，野人籬落豆花初。","無愁自得仙人術，多病能忘太史書。","聞說故園香稻熟，片帆歸去就鱸魚。"]', '["碧天涼冷鴈来疎，闲望江云思有餘。","秋館池亭荷葉後，野人籬落豆花初。","無愁自得仙人術，多病能忘太史书。","闻说故园香稻熟，片帆归去就鱸鱼。"]', '诗', 'shi', '', NULL, '江亭晚望 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b21a6826-9385-4c1f-8c98-abc2ce336e3c', '長安夜訪澈上人', '长安夜訪澈上人', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["關西木落夜霜凝，烏帽閑尋紫閣僧。","松迥月光先照鶴，寺寒溝水忽生冰。","琤琤曉漏喧秦禁，漠漠秋煙起漢陵。","聞說天台舊禪處，石房獨有一龕燈。"]', '["关西木落夜霜凝，烏帽闲尋紫閣僧。","松迥月光先照鹤，寺寒溝水忽生冰。","琤琤晓漏喧秦禁，漠漠秋煙起漢陵。","闻说天台旧禪处，石房独有一龕灯。"]', '诗', 'shi', '', NULL, '長安夜訪澈上人 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0a80cec-c0dc-4b30-95d7-a009fafaad9e', '送圓鑒上人遊天台', '送圓鑒上人游天台', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["西嶺草堂留不住，獨攜瓶錫向天台。","霜清海寺聞潮至，日宴江船乞食回。","華頂夜寒孤月落，石橋秋盡一僧來。","靈溪道者相逢處，陰洞泠泠竹室開。"]', '["西嶺草堂留不住，独携瓶錫向天台。","霜清海寺闻潮至，日宴江船乞食回。","华頂夜寒孤月落，石橋秋尽一僧来。","靈溪道者相逢处，陰洞泠泠竹室开。"]', '诗', 'shi', '', NULL, '送圓鑒上人遊天台 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bdd7ff9-921a-4aa6-93c7-32822d6787af', '送僧之台州', '送僧之台州', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["獨尋台嶺閑遊去，豈覺靈溪道里賒。","三井應潮通海浪，五峰攢寺落天花。","寒潭盥漱銅瓶潔，野店安禪錫杖斜。","到日初尋石橋路，莫教雲雨濕袈裟。"]', '["独尋台嶺闲游去，豈覺靈溪道里賒。","三井應潮通海浪，五峰攢寺落天花。","寒潭盥漱銅瓶潔，野店安禪錫杖斜。","到日初尋石橋路，莫教云雨濕袈裟。"]', '诗', 'shi', '', NULL, '送僧之台州 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('428b3e18-015e-4a30-974d-0162ec9d0d62', '傷賈島無可', '傷賈島無可', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["却到京師事事傷，惠休歸寂賈生亡。","何人收得文章篋，獨我來經苔蘚房。","一命未霑爲逐客，萬緣初盡別空王。","蕭蕭竹塢斜陽在，葉覆閑堦雪擁牆。"]', '["却到京師事事傷，惠休归寂賈生亡。","何人收得文章篋，独我来經苔蘚房。","一命未霑爲逐客，万緣初尽別空王。","蕭蕭竹塢斜陽在，葉覆闲堦雪擁牆。"]', '诗', 'shi', '', NULL, '傷賈島無可 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eec41831-e7b0-4c31-b8f8-e0a23d8196f4', '孔雀', '孔雀', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["越鳥青春好顏色，晴軒入戶看呫衣。","一身金翠畫不得，萬里山川來者稀。","絲竹慣聽時獨舞，樓臺初上欲孤飛。","刺桐花謝芳草歇，南國同巢應望歸。"]', '["越鸟青春好顏色，晴軒入戶看呫衣。","一身金翠畫不得，万里山川来者稀。","絲竹慣听时独舞，楼台初上欲孤飞。","刺桐花謝芳草歇，南国同巢應望归。"]', '诗', 'shi', '', NULL, '孔雀 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c036111-3bef-457e-9f9e-ae1615404d94', '秋晚寄題陸勳校書義興禪居時淮南從事', '秋晚寄題陸勳校书義兴禪居时淮南從事', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["禪居秋草晚，蕭索異前時。","蓮幕青雲貴，翱翔絕後期。","蘚房檉架掩，山砌石盆欹。","劒戟晨趨靜，笙歌夜散遲。","谷寒霜狖靜，林晚磬蟲悲。","惠遠煙霞在，方平杖履隨。","骨清須貴達，神重有威儀。","萬卒千蹄馬，橫鞭從信騎。"]', '["禪居秋草晚，蕭索異前时。","蓮幕青云貴，翱翔絕後期。","蘚房檉架掩，山砌石盆欹。","劒戟晨趨静，笙歌夜散遲。","谷寒霜狖静，林晚磬蟲悲。","惠远煙霞在，方平杖履隨。","骨清須貴達，神重有威儀。","万卒千蹄马，橫鞭從信騎。"]', '诗', 'shi', '', NULL, '秋晚寄題陸勳校書義興禪居時淮南從事 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02b92837-41cc-4527-88f7-5e153727e8ac', '酬王舍人雪中見寄', '酬王舍人雪中见寄', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["三日柴門擁不開，堦庭平滿白皚皚。","今朝踏作瓊瑤跡，爲有詩從鳳沼來。"]', '["三日柴门擁不开，堦庭平满白皚皚。","今朝踏作瓊瑤跡，爲有诗從鳳沼来。"]', '诗', 'shi', '', NULL, '酬王舍人雪中見寄 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c48650e-2c48-478e-b587-e7dccd27332e', '蟬', '蟬', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["飲蟬驚雨落高槐，山蟻移將入石階。","若使秦樓美人見，還應一爲拔金釵。"]', '["饮蟬驚雨落高槐，山蟻移將入石階。","若使秦楼美人见，還應一爲拔金釵。"]', '诗', 'shi', '', NULL, '蟬 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('639f0a81-65c2-47c1-9a44-a45b7b42f53f', '自水口入茶山', '自水口入茶山', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["蒨蒨紅裙好女兒，相偎相倚看人時。","使君馬上應含笑，橫把金鞭爲詠詩。"]', '["蒨蒨紅裙好女兒，相偎相倚看人时。","使君马上應含笑，橫把金鞭爲詠诗。"]', '诗', 'shi', '', NULL, '自水口入茶山 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3af43ff5-183a-49ee-8365-266050d3d00f', '重遊天台', '重游天台', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["南國天台山水奇，石橋危險古來知。","龍潭直下一百丈，誰見生公獨坐時。"]', '["南国天台山水奇，石橋危險古来知。","龙潭直下一百丈，誰见生公独坐时。"]', '诗', 'shi', '', NULL, '重遊天台 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb9d7e2-b5a5-4169-bcb6-20902e866b82', '山行', '山行', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["小田微雨稻苗香，田畔清溪潏潏涼。","自憶東吳榜舟日，蓼花溝水半篙強。"]', '["小田微雨稻苗香，田畔清溪潏潏涼。","自憶东吳榜舟日，蓼花溝水半篙強。"]', '诗', 'shi', '', NULL, '山行 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935f3e8f-736c-492a-a97e-373270f5445a', '上元日寄湖杭二從事', '上元日寄湖杭二從事', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["戀別山燈憶水燈，山光水焰百千層。","謝公留賞山公喚，知入笙歌阿那朋。"]', '["戀別山灯憶水灯，山光水焰百千層。","謝公留賞山公喚，知入笙歌阿那朋。"]', '诗', 'shi', '', NULL, '上元日寄湖杭二從事 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6174dbd-3f25-4b0f-9636-83f10f5f0522', '寒食野望', '寒食野望', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["舊墳新隴哭多時，流世都堪幾度悲。","烏鳥亂啼人未遠，野風吹散白棠梨。"]', '["旧墳新隴哭多时，流世都堪幾度悲。","烏鸟亂啼人未远，野风吹散白棠梨。"]', '诗', 'shi', '', NULL, '寒食野望 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd7d46e1-7b64-43e8-bdbb-fcabdfb9c2be', '清明日題一公禪室', '清明日題一公禪室', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["山頭蘭若石楠春，山下清明煙火新。","此日何窮禮禪客，歸心誰是戀禪人。"]', '["山头蘭若石楠春，山下清明煙火新。","此日何窮禮禪客，归心誰是戀禪人。"]', '诗', 'shi', '', NULL, '清明日題一公禪室 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f41d9d47-9d12-4e05-a3d7-d5cedfe87113', '七夕寄張氏兄弟', '七夕寄張氏兄弟', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["新秋牛女會佳期，紅粉筵開玉饌時。","好與檀郎寄花朵，莫教清曉羨蛛絲。"]', '["新秋牛女會佳期，紅粉筵开玉饌时。","好與檀郎寄花朵，莫教清晓羨蛛絲。"]', '诗', 'shi', '', NULL, '七夕寄張氏兄弟 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b511049-ee2f-4226-9fd3-32f729aaf037', '春晚與諸同舍出城迎座主侍郎', '春晚與諸同舍出城迎座主侍郎', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["三十驊騮一鬨塵，來時不鎖杏園春。","東風柳絮輕如雪，應有偷游曲水人。"]', '["三十驊騮一鬨塵，来时不鎖杏园春。","东风柳絮轻如雪，應有偷游曲水人。"]', '诗', 'shi', '', NULL, '春晚與諸同舍出城迎座主侍郎 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86a921e6-9869-4cc1-8585-8e15ce10d6c6', '張郎中宅戲贈二首 一', '張郎中宅戲贈二首 一', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["薄雪燕蓊紫燕釵，釵垂簏簌抱香懷。","一聲歌罷劉郎醉，脫取明金壓繡鞋。"]', '["薄雪燕蓊紫燕釵，釵垂簏簌抱香懷。","一声歌罷劉郎醉，脫取明金壓繡鞋。"]', '诗', 'shi', '', NULL, '張郎中宅戲贈二首 一 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f290ed3-a7ec-411f-8701-ceae956a7072', '張郎中宅戲贈二首 二', '張郎中宅戲贈二首 二', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["謝家青妓邃重關，誰省春風見玉顏。","聞道綵鸞三十六，一雙雙對碧池蓮。"]', '["謝家青妓邃重关，誰省春风见玉顏。","闻道綵鸾三十六，一雙雙对碧池蓮。"]', '诗', 'shi', '', NULL, '張郎中宅戲贈二首 二 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fbb188c-449d-4776-b70f-9579edd75514', '醉送', '醉送', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["江梅冷豔酒清光，急拍繁弦醉畫堂。","無限柳條多少雪，一將春恨付劉郎。"]', '["江梅冷豔酒清光，急拍繁弦醉畫堂。","無限柳條多少雪，一將春恨付劉郎。"]', '诗', 'shi', '', NULL, '醉送 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fb42ef0-ada8-440f-8e8a-e5d36efc6da4', '曉井', '晓井', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["桐陰覆井月斜明，百尺寒泉古甃清。","越女攜瓶下金索，曉天初放轆轤聲。"]', '["桐陰覆井月斜明，百尺寒泉古甃清。","越女携瓶下金索，晓天初放轆轤声。"]', '诗', 'shi', '', NULL, '曉井 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba518da-b0e1-4cc9-972c-b847d48dd356', '南池', '南池', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["小男供餌婦搓絲，溢榼香醪倒接䍦。","日出兩竿魚正食，一家歡笑在南池。"]', '["小男供餌婦搓絲，溢榼香醪倒接䍦。","日出兩竿鱼正食，一家歡笑在南池。"]', '诗', 'shi', '', NULL, '南池 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80dc0cd4-fec0-467d-b714-5191d4be6d39', '偶作', '偶作', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["一杯正發吟哦興，兩盞還生去住愁。","何似全家上船去，酒旗多處即淹留。"]', '["一杯正發吟哦兴，兩盞還生去住愁。","何似全家上船去，酒旗多处即淹留。"]', '诗', 'shi', '', NULL, '偶作 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef6f5d2f-45c2-4ea3-a76e-c126036622e5', '畫鼓', '畫鼓', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["嘗聞畫鼓動歡情，及送離人恨鼓聲。","兩杖一揮行纜解，暮天空使別魂驚。"]', '["嘗闻畫鼓动歡情，及送離人恨鼓声。","兩杖一揮行纜解，暮天空使別魂驚。"]', '诗', 'shi', '', NULL, '畫鼓 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e33b58-d3f8-45ea-abea-0f1ebe4f7474', '燕蓊花', '燕蓊花', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["十二街中何限草，燕蓊盡欲占殘春。","黃花撲地無窮極，愁殺江南去住人。"]', '["十二街中何限草，燕蓊尽欲占殘春。","黄花撲地無窮極，愁殺江南去住人。"]', '诗', 'shi', '', NULL, '燕蓊花 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e164aa9-1051-45fb-b064-01d761fae92d', '邵博士溪亭', '邵博士溪亭', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["野茶無限春風葉，溪水千重返照波。","只去長橋三十里，誰人一解枉帆過。"]', '["野茶無限春风葉，溪水千重返照波。","只去长橋三十里，誰人一解枉帆過。"]', '诗', 'shi', '', NULL, '邵博士溪亭 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39596d01-0397-46de-9a2d-401da0b951c5', '小石上見亡友題處', '小石上见亡友題处', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["笋石清琤入紫煙，陸雲題處是前年。","苔侵雨打依稀在，惆悵涼風樹樹蟬。"]', '["笋石清琤入紫煙，陸云題处是前年。","苔侵雨打依稀在，惆悵涼风樹樹蟬。"]', '诗', 'shi', '', NULL, '小石上見亡友題處 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f0f529-53cf-48c9-8225-f1900f14fb92', '洞靈觀流泉', '洞靈观流泉', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["石上苔蕪水上煙，潺湲聲在觀門前。","千巖萬壑分流去，更引飛花入洞天。"]', '["石上苔蕪水上煙，潺湲声在观门前。","千巖万壑分流去，更引飞花入洞天。"]', '诗', 'shi', '', NULL, '洞靈觀流泉 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02ea6f69-4bf3-4640-8a5f-abb9b1a6cfa3', '送李判官', '送李判官', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["津市停橈送別難，熒熒蠟炬照更闌。","東風萬疊吹江月，誰伴袁襃宿夜灘。"]', '["津市停橈送別难，熒熒蠟炬照更闌。","东风万叠吹江月，誰伴袁襃宿夜灘。"]', '诗', 'shi', '', NULL, '送李判官 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c62e871f-0037-4c8f-a0ce-40e9096b899f', '宿杭州虛白堂', '宿杭州虛白堂', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["秋月斜明虛白堂，寒蛩唧唧樹蒼蒼。","江風徹曉不得睡，二十五聲秋點長。"]', '["秋月斜明虛白堂，寒蛩唧唧樹蒼蒼。","江风徹晓不得睡，二十五声秋点长。"]', '诗', 'shi', '', NULL, '宿杭州虛白堂 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7eb8bfa-54e0-4c89-b2df-448369ad56be', '道林寺', '道林寺', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["臨湘之濱麓之隅，西有松寺東岸無。","松風千里擺不斷，竹泉瀉入于僧廚。","宏梁大棟何足貴，山寺難有山泉俱。","四時唯夏不敢入，燭龍安敢停斯須。","遠公池上種何物，碧羅扇底紅鱗魚。","香閣朝鳴大法鼓，天宮夜轉三乘書。","野花市井栽不著，山雞飲啄聲相呼。","金檻僧迴步步影，石盆水濺聯聯珠。","北臨高處日正午，舉手欲摸黃金烏。","遙江大船小於葉，遠村雜樹齊如蔬。","潭州城郭在何處，東邊一片青模糊。","今來古往人滿地，勞生未了歸丘墟。","長卿之門久寂寞，五言七字誇規模。","我吟杜詩清入骨，灌頂何必須醍醐。","白日不照耒陽縣，皇天厄死飢寒軀。","明珠大貝採欲盡，蚌蛤空滿赤沙湖。","今我題詩亦無味，懷賢覽古成長吁。","不如興罷過江去，已有好月明歸途。"]', '["臨湘之濱麓之隅，西有松寺东岸無。","松风千里擺不斷，竹泉瀉入于僧廚。","宏梁大棟何足貴，山寺难有山泉俱。","四时唯夏不敢入，燭龙安敢停斯須。","远公池上種何物，碧羅扇底紅鱗鱼。","香閣朝鳴大法鼓，天宮夜轉三乘书。","野花市井栽不著，山雞饮啄声相呼。","金檻僧迴步步影，石盆水濺聯聯珠。","北臨高处日正午，舉手欲摸黄金烏。","遙江大船小於葉，远村杂樹齊如蔬。","潭州城郭在何处，东邊一片青模糊。","今来古往人满地，勞生未了归丘墟。","长卿之门久寂寞，五言七字誇規模。","我吟杜诗清入骨，灌頂何必須醍醐。","白日不照耒陽縣，皇天厄死飢寒軀。","明珠大貝採欲尽，蚌蛤空满赤沙湖。","今我題诗亦無味，懷賢覽古成长吁。","不如兴罷過江去，已有好月明归途。"]', '诗', 'shi', '', NULL, '道林寺 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef96daf2-7596-4663-8431-901daf08fafa', '美人嘗茶行', '美人嘗茶行', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["雲鬟枕落困春泥，玉郎爲碾瑟瑟塵。","閑教鸚鵡啄窗響，和嬌扶起濃睡人。","銀瓶貯泉水一掬，松雨聲來乳花熟。","朱脣啜破綠雲時，咽入香喉爽紅玉。","明眸漸開橫秋水，手撥絲簧醉心起。","臺時却坐推金箏，不語思量夢中事。"]', '["云鬟枕落困春泥，玉郎爲碾瑟瑟塵。","闲教鸚鵡啄窗响，和嬌扶起濃睡人。","銀瓶貯泉水一掬，松雨声来乳花熟。","朱脣啜破綠云时，咽入香喉爽紅玉。","明眸漸开橫秋水，手撥絲簧醉心起。","台时却坐推金箏，不語思量梦中事。"]', '诗', 'shi', '', NULL, '美人嘗茶行 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8250f0c6-0aba-4a9c-92dc-03fb7c00ee57', '門前柳', '门前柳', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["門前蜀柳□知春，風澹煖煙愁殺人。","將謂只栽郡樓下，不知迤邐連南津。","南津柳色連南市，南市戎州三百里。","夷陬蠻落相連接，故鄉莫道心先死。","我今帝里尚有家，門前嫩柳插仙霞。","晨霑太一壇邊雨，暮宿鳳皇城裏鵶。","別來三載當誰道，門前年年綠陰好。","春來定解飛雪花，雨後還應庇煙草。","憶昔當年栽柳時，新芽茁茁嫌生遲。","如今宛轉稊著地，常向綠陰勞夢思。","不道彼樹好，不道此樹惡。","試將此意問野人，野人盡道生處樂。","爲報門前楊柳栽，我應來歲當歸來。","縱令樹下能攀折，白髮如絲心似灰。"]', '["门前蜀柳□知春，风澹煖煙愁殺人。","將謂只栽郡楼下，不知迤邐連南津。","南津柳色連南市，南市戎州三百里。","夷陬蠻落相連接，故乡莫道心先死。","我今帝里尚有家，门前嫩柳插仙霞。","晨霑太一壇邊雨，暮宿鳳皇城裏鵶。","別来三載當誰道，门前年年綠陰好。","春来定解飞雪花，雨後還應庇煙草。","憶昔當年栽柳时，新芽茁茁嫌生遲。","如今宛轉稊著地，常向綠陰勞梦思。","不道彼樹好，不道此樹惡。","試將此意问野人，野人尽道生处乐。","爲報门前楊柳栽，我應来歲當归来。","縱令樹下能攀折，白髮如絲心似灰。"]', '诗', 'shi', '', NULL, '門前柳 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('434b5024-590e-4bdc-8041-505bd9d04ee5', '岳陽樓晚望', '岳陽楼晚望', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["乾坤千里水雲間，釣艇如萍去復還。","樓上北風斜捲席，湖中西日倒銜山。","懷沙有恨騷人往，鼓瑟無聲帝子閑。","何事黃昏尚凝睇，數行煙樹接荆蠻。"]', '["乾坤千里水云间，釣艇如萍去复還。","楼上北风斜捲席，湖中西日倒銜山。","懷沙有恨騷人往，鼓瑟無声帝子闲。","何事黄昏尚凝睇，數行煙樹接荆蠻。"]', '诗', 'shi', '', NULL, '岳陽樓晚望 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c76c75-62dc-421c-bfba-738757b44c08', '哭李商隱 一', '哭李商隐 一', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["成紀星郎字義山，適歸高壤抱長歎。","詞林枝葉三春盡，學海波瀾一夜乾。","風雨已吹燈燭滅，姓名長在齒牙寒。","只應物外攀琪樹，便著霓裳上絳壇。"]', '["成紀星郎字義山，適归高壤抱长歎。","词林枝葉三春尽，学海波瀾一夜乾。","风雨已吹灯燭滅，姓名长在齒牙寒。","只應物外攀琪樹，便著霓裳上絳壇。"]', '诗', 'shi', '', NULL, '哭李商隱 一 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e814be8a-03b3-4cd6-b3d5-fac39324bf28', '哭李商隱 二', '哭李商隐 二', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["虛負凌雲萬丈才，一生襟抱未曾開。","鳥啼花落人何在，竹死桐枯鳳不來。","良馬足因無主踠，舊交心爲絕弦哀。","九泉莫嘆三光隔，又送文星入夜臺。"]', '["虛負凌云万丈才，一生襟抱未曾开。","鸟啼花落人何在，竹死桐枯鳳不来。","良马足因無主踠，旧交心爲絕弦哀。","九泉莫嘆三光隔，又送文星入夜台。"]', '诗', 'shi', '', NULL, '哭李商隱 二 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('890bb482-2690-47f1-be07-800f339008d7', '和友人鴛鴦之什 一', '和友人鴛鴦之什 一', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["翠鬣紅衣舞夕暉，水禽情似此禽稀。","暫分煙島猶回首，只渡寒塘亦共飛。","映霧乍迷珠殿瓦，逐梭齊上玉人機。","採蓮無限蘭橈女，笑指中流羨爾歸。"]', '["翠鬣紅衣舞夕暉，水禽情似此禽稀。","暫分煙島猶回首，只渡寒塘亦共飞。","映霧乍迷珠殿瓦，逐梭齊上玉人機。","採蓮無限蘭橈女，笑指中流羨爾归。"]', '诗', 'shi', '', NULL, '和友人鴛鴦之什 一 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb084998-7c51-45e7-8d70-e1b37f6030eb', '和友人鴛鴦之什 二', '和友人鴛鴦之什 二', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["寂寂春塘煙晚時，兩心和影共依依。","溪頭日暖眠沙穩，渡口風寒浴浪稀。","翡翠莫誇饒彩飾，鸊鵜須羨好毛衣。"]', '["寂寂春塘煙晚时，兩心和影共依依。","溪头日暖眠沙穩，渡口风寒浴浪稀。","翡翠莫誇饒彩飾，鸊鵜須羨好毛衣。"]', '诗', 'shi', '', NULL, '和友人鴛鴦之什 二 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5675ccb6-8646-436e-a7ff-32136177be54', '和友人鴛鴦之什 三', '和友人鴛鴦之什 三', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["舞鶴翔鸞俱別離，可憐生死兩相隨。","紅絲毳落眠汀處，白雪花成蹙浪時。","琴上只聞交頸語，窗前空展共飛詩。","何如相見長相對，肯羨人間多所思。"]', '["舞鹤翔鸾俱別離，可怜生死兩相隨。","紅絲毳落眠汀处，白雪花成蹙浪时。","琴上只闻交頸語，窗前空展共飞诗。","何如相见长相对，肯羨人间多所思。"]', '诗', 'shi', '', NULL, '和友人鴛鴦之什 三 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47f4f6a8-5567-4459-b052-f88c9a996b70', '有贈 一', '有贈 一', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["莫道妝成斷客腸，粉胸綿手白蓮香。","煙分頂上三層綠，劒截眸中一寸光。","舞勝柳枝腰更軟，歌嫌珠貫曲猶長。","雖然不似王孫女，解愛臨邛賣賦郎。"]', '["莫道妝成斷客腸，粉胸綿手白蓮香。","煙分頂上三層綠，劒截眸中一寸光。","舞勝柳枝腰更軟，歌嫌珠貫曲猶长。","雖然不似王孫女，解愛臨邛賣賦郎。"]', '诗', 'shi', '', NULL, '有贈 一 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a1ca53-9b7b-4a3e-84e9-d9fed977733b', '有贈 二', '有贈 二', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["錦里芬芳少佩蘭，風流全占似君難。","心迷曉夢窗猶暗，粉落香肌汗未乾。","兩臉夭桃從鏡發，一眸春水照人寒。","自嗟此地非吾土，不得如花歲歲看。"]', '["錦里芬芳少佩蘭，风流全占似君难。","心迷晓梦窗猶暗，粉落香肌汗未乾。","兩臉夭桃從镜發，一眸春水照人寒。","自嗟此地非吾土，不得如花歲歲看。"]', '诗', 'shi', '', NULL, '有贈 二 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9060dcd-1e8f-48c8-a62b-7eb6d8262936', '和人聽歌 一', '和人听歌 一', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["氣吐幽蘭出洞房，樂人先問調宮商。","聲和細管珠纔轉，曲度沈煙雪更香。","公子不隨腸萬結，離人須落淚千行。","巫山唱罷行雲過，猶自微塵舞畫梁。"]', '["氣吐幽蘭出洞房，乐人先问調宮商。","声和細管珠纔轉，曲度沈煙雪更香。","公子不隨腸万結，離人須落泪千行。","巫山唱罷行云過，猶自微塵舞畫梁。"]', '诗', 'shi', '', NULL, '和人聽歌 一 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f3cb4c-cb97-4f76-a833-f224e13a65d3', '和人聽歌 二', '和人听歌 二', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["紅臉初分翠黛愁，錦筵歌板拍清秋。","一樓春雪和塵落，午夜寒泉帶雨流。","座上美人心盡死，尊前旅客淚難收。","莫辭更送劉郎酒，百斛明珠異日酬。"]', '["紅臉初分翠黛愁，錦筵歌板拍清秋。","一楼春雪和塵落，午夜寒泉带雨流。","座上美人心尽死，尊前旅客泪难收。","莫辞更送劉郎酒，百斛明珠異日酬。"]', '诗', 'shi', '', NULL, '和人聽歌 二 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('768d62a5-f142-4b68-bbf1-5bdf6dd4f5c5', '水晶枕', '水晶枕', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["千年積雪萬年冰，掌上初擎力不勝。","南國舊知何處得，北方寒氣此中凝。","黃昏轉燭螢飛沼，白日褰簾水在簪。","蘄簟蜀琴相對好，裁詩乞與滌煩襟。"]', '["千年積雪万年冰，掌上初擎力不勝。","南国旧知何处得，北方寒氣此中凝。","黄昏轉燭螢飞沼，白日褰簾水在簪。","蘄簟蜀琴相对好，裁诗乞與滌煩襟。"]', '诗', 'shi', '', NULL, '水晶枕 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd4ead8-d86a-47bd-a698-67a97ff5af51', '席間詠琴客', '席间詠琴客', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["七條弦上五音寒，此藝知音自古難。","唯有河南房次律，始終憐得董庭蘭。"]', '["七條弦上五音寒，此藝知音自古难。","唯有河南房次律，始終怜得董庭蘭。"]', '诗', 'shi', '', NULL, '席間詠琴客 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f3a52a1-bef5-4a49-af79-abc004433a5f', '句', '句', '2aa73044-4f47-4fae-801b-f95cc4e1746f', '唐', '["楚王宮地羅含宅，賴許時時聽法來。"]', '["楚王宮地羅含宅，賴許时时听法来。"]', '诗', 'shi', '', NULL, '句 崔珏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34d81741-6166-4690-84ee-6aa26305e75b', '徒相逢', '徒相逢', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["江邊野花不須採，梁頭野燕不用親。","西施本是越溪女，承恩不薦越溪人。"]', '["江邊野花不須採，梁头野燕不用親。","西施本是越溪女，承恩不薦越溪人。"]', '诗', 'shi', '', NULL, '徒相逢 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43c226cd-2309-433f-8942-84d90bbd85c7', '雜誡', '杂誡', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["帶香入鮑肆，香氣同鮑魚。","未入猶可悟，已入當何如。"]', '["带香入鲍肆，香氣同鲍鱼。","未入猶可悟，已入當何如。"]', '诗', 'shi', '', NULL, '雜誡 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b22dc07-e585-42df-8866-582f58e8f6d1', '捕漁謠', '捕漁謠', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["天子好征戰，百姓不種桑。","天子好年少，無人薦馮唐。","天子好美女，夫婦不成雙。"]', '["天子好征戰，百姓不種桑。","天子好年少，無人薦馮唐。","天子好美女，夫婦不成雙。"]', '诗', 'shi', '', NULL, '捕漁謠 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf17ecc7-5687-4c4c-bddb-ef4cfa600c7d', '四怨三愁五情詩十二首 其一怨', '四怨三愁五情诗十二首 其一怨', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["美人如新花，許嫁還獨守。","豈無青銅鏡，終日自疑醜。"]', '["美人如新花，許嫁還独守。","豈無青銅镜，終日自疑醜。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其一怨 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4035d30f-7eba-43c6-80fe-fd38cdf32762', '四怨三愁五情詩十二首 其二怨', '四怨三愁五情诗十二首 其二怨', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["庭花已結子，巖花猶弄色。","誰令生處遠，用盡春風力。"]', '["庭花已結子，巖花猶弄色。","誰令生处远，用尽春风力。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其二怨 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('986a5c16-6321-4b5e-836f-5f7bd701f88e', '四怨三愁五情詩十二首 其三怨', '四怨三愁五情诗十二首 其三怨', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["短鬟一如螓，長眉一如蛾。","相共棹蓮舟，得花不如他。"]', '["短鬟一如螓，长眉一如蛾。","相共棹蓮舟，得花不如他。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其三怨 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62deae00-7f5c-4734-8ae2-261c94b3e724', '四怨三愁五情詩十二首 其四怨', '四怨三愁五情诗十二首 其四怨', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["手推嘔啞車，朝朝暮暮耕。","未曾分得穀，空得老農名。"]', '["手推嘔啞车，朝朝暮暮耕。","未曾分得穀，空得老農名。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其四怨 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e6c948e-6987-4869-99e1-cdf195c1e818', '四怨三愁五情詩十二首 其一愁', '四怨三愁五情诗十二首 其一愁', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["遠夢如水急，白髮如草新。","歸期待春至，春至還送人。"]', '["远梦如水急，白髮如草新。","归期待春至，春至還送人。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其一愁 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('062faa2e-f31b-4ae2-bb67-fd4a96971ea3', '四怨三愁五情詩十二首 其二愁', '四怨三愁五情诗十二首 其二愁', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["澗草短短青，山月朗朗明。","此夜目不掩，屋頭烏啼聲。"]', '["澗草短短青，山月朗朗明。","此夜目不掩，屋头烏啼声。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其二愁 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc9d64c0-1d04-4d1e-aa0d-619039bccd8a', '四怨三愁五情詩十二首 其三愁', '四怨三愁五情诗十二首 其三愁', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["別家鬢未生，到城鬢似髪。","朝朝臨川望，灞水不入越。"]', '["別家鬢未生，到城鬢似髪。","朝朝臨川望，灞水不入越。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其三愁 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('216c622a-f10c-4adc-8cae-699ee8db5a7a', '四怨三愁五情詩十二首 其一情', '四怨三愁五情诗十二首 其一情', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["東西是長江，南北是官道。","牛羊不戀山，只戀山中草。"]', '["东西是长江，南北是官道。","牛羊不戀山，只戀山中草。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其一情 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08ad4457-3581-47b8-b42f-c02533097030', '四怨三愁五情詩十二首 其二情', '四怨三愁五情诗十二首 其二情', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["阿嬌生漢宮，西施住南國。","專房莫相妒，各自有顏色。"]', '["阿嬌生漢宮，西施住南国。","專房莫相妒，各自有顏色。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其二情 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5084c3-3072-4c5c-aa90-7a7f79d4c25c', '四怨三愁五情詩十二首 其三情', '四怨三愁五情诗十二首 其三情', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["蛺蝶空中飛，夭桃庭中春。","見他夫婦好，有女初嫁人。"]', '["蛺蝶空中飞，夭桃庭中春。","见他夫婦好，有女初嫁人。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其三情 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31163e68-55f5-4ddd-986a-51125fd0c01e', '四怨三愁五情詩十二首 其四情', '四怨三愁五情诗十二首 其四情', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["檳榔自無柯，椰葉自無陰。","常羨庭邊竹，生笋高於林。"]', '["檳榔自無柯，椰葉自無陰。","常羨庭邊竹，生笋高於林。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其四情 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('123e0f29-cf42-4247-9563-b98729a7f47e', '四怨三愁五情詩十二首 其五情', '四怨三愁五情诗十二首 其五情', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["野雀空城飢，交交復飛飛。","勿怪官倉粟，官倉無空時。"]', '["野雀空城飢，交交复飞飞。","勿怪官倉粟，官倉無空时。"]', '诗', 'shi', '', NULL, '四怨三愁五情詩十二首 其五情 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d637f8-3328-49e9-ad21-8be289ac07da', '寄劉駕', '寄劉駕', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["一川草色青褭褭，遶屋水聲如在家。","悵望美人不攜手，牆東又發數枝花。"]', '["一川草色青褭褭，遶屋水声如在家。","悵望美人不携手，牆东又發數枝花。"]', '诗', 'shi', '', NULL, '寄劉駕 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c44f9f8e-4770-48ff-bf7e-3a6beed463da', '風人體', '风人體', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["出門行一步，形影便相失。","何況大隄上，驄馬如箭疾。","夜夜如織婦，尋思待成匹。","郎只不在家，在家亦如出。","將金與卜人，譎道遠行吉。","念郎緣底事，不具天與日。"]', '["出门行一步，形影便相失。","何況大隄上，驄马如箭疾。","夜夜如织婦，尋思待成匹。","郎只不在家，在家亦如出。","將金與卜人，譎道远行吉。","念郎緣底事，不具天與日。"]', '诗', 'shi', '', NULL, '風人體 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bce0d41-cefc-48f2-9ed2-bba5bac98e3d', '杏園即席上同年', '杏园即席上同年', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["岐路不在天，十年行不至。","一旦公道開，青雲在平地。","枕上數聲鼓，衡門已如市。","白日探得珠，不待驪龍睡。","怱怱出九衢，僮僕顏色異。","故衣未及換，尚有去年淚。","晴陽照花影，落絮浮野翠。","對酒時忽驚，猶疑夢中事。","自憐孤飛鳥，得接鸞鳳翅。","永懷共濟心，莫起胡越意。"]', '["岐路不在天，十年行不至。","一旦公道开，青云在平地。","枕上數声鼓，衡门已如市。","白日探得珠，不待驪龙睡。","怱怱出九衢，僮僕顏色異。","故衣未及換，尚有去年泪。","晴陽照花影，落絮浮野翠。","对酒时忽驚，猶疑梦中事。","自怜孤飞鸟，得接鸾鳳翅。","永懷共濟心，莫起胡越意。"]', '诗', 'shi', '', NULL, '杏園即席上同年 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0a23085-74ec-4927-8818-d1f994676b5b', '恃寵', '恃寵', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["二月樹色好，昭儀正驕奢。","恐君愛陽豔，斫却園中花。","三十六宮女，髻鬟各如鴉。","君王心所憐，獨自不見瑕。","臺上紅燈盡，未肯下金車。","一笑不得所，塵中悉無家。","飛燕身更輕，何必恃容華。"]', '["二月樹色好，昭儀正驕奢。","恐君愛陽豔，斫却园中花。","三十六宮女，髻鬟各如鴉。","君王心所怜，独自不见瑕。","台上紅灯尽，未肯下金车。","一笑不得所，塵中悉無家。","飞燕身更轻，何必恃容华。"]', '诗', 'shi', '', NULL, '恃寵 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('975ee657-cb12-48c3-85de-721b239af51c', '題女郎廟', '題女郎廟', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["數點煙香出廟門，女娥飛去影中存。","年年嶺上春無主，露泣花愁斷客魂。"]', '["數点煙香出廟门，女娥飞去影中存。","年年嶺上春無主，露泣花愁斷客魂。"]', '诗', 'shi', '', NULL, '題女郎廟 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f4a98b-c036-4ff8-a5aa-5898f75199ed', '四望樓', '四望楼', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["背山見樓影，應合與山齊。","座上日已出，城中未鳴雞。","無限燕趙女，吹笙上金梯。","風起洛陽東，香過洛陽西。","公子長夜醉，不聞子規啼。"]', '["背山见楼影，應合與山齊。","座上日已出，城中未鳴雞。","無限燕趙女，吹笙上金梯。","风起洛陽东，香過洛陽西。","公子长夜醉，不闻子規啼。"]', '诗', 'shi', '', NULL, '四望樓 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6719a43-4c65-4f29-a384-e2399548059f', '築城三首 一', '築城三首 一', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["郎有蘼蕪心，妾有芙蓉質。","不辭嫁與郎，築城無休日。"]', '["郎有蘼蕪心，妾有芙蓉質。","不辞嫁與郎，築城無休日。"]', '诗', 'shi', '', NULL, '築城三首 一 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83dd3758-fcd7-4edb-a8cc-e6d633d9c2f6', '築城三首 二', '築城三首 二', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["嗚嗚啄人鴉，軋軋上城車。","力盡土不盡，得歸亦無家。"]', '["嗚嗚啄人鴉，軋軋上城车。","力尽土不尽，得归亦無家。"]', '诗', 'shi', '', NULL, '築城三首 二 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc6ee0e2-a469-4437-869c-a9fd297327d8', '築城三首 三', '築城三首 三', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["築人非築城，圍秦豈圍我。","不知城上土，化作宮中火。"]', '["築人非築城，圍秦豈圍我。","不知城上土，化作宮中火。"]', '诗', 'shi', '', NULL, '築城三首 三 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff7c5ac-a84c-4b3f-921f-642ce8344708', '奉命齊州推事畢寄本府尚書', '奉命齊州推事畢寄本府尚书', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["越鳥栖不定，孤飛入齊鄉。","日暮天欲雨，那兼羽翎傷。","州民言刺史，蠹物甚於蝗。","受命大執法，草草是行裝。","僕隸皆分散，單車驛路長。","四顧無相識，奔馳若投荒。","重門下長鎖，樹影空過牆。","驅囚遶廊屋，𧥄𧥄如牛羊。","獄吏相對語，簿書堆滿牀。","敲枷打鎖聲，終日在目旁。","既捨三山侶，來餘五斗糧。","忍學空城雀，潛身入官倉。","國中天子令，頭上白日光。","曲木用處多，不如直爲梁。","恐孤食恩地，晝夜心不遑。","仲夏天氣熱，鬢鬚忽成霜。","社鼠不可灌，城狐不易防。","偶於擒縱間，盡得見否臧。","截斷姦吏舌，擘開冤人腸。","明朝向西望，走馬歸汶陽。"]', '["越鸟栖不定，孤飞入齊乡。","日暮天欲雨，那兼羽翎傷。","州民言刺史，蠹物甚於蝗。","受命大執法，草草是行裝。","僕隸皆分散，單车驛路长。","四顧無相識，奔驰若投荒。","重门下长鎖，樹影空過牆。","驱囚遶廊屋，𧥄𧥄如牛羊。","獄吏相对語，簿书堆满牀。","敲枷打鎖声，終日在目旁。","既捨三山侶，来餘五斗糧。","忍学空城雀，潛身入官倉。","国中天子令，头上白日光。","曲木用处多，不如直爲梁。","恐孤食恩地，晝夜心不遑。","仲夏天氣熱，鬢鬚忽成霜。","社鼠不可灌，城狐不易防。","偶於擒縱间，尽得见否臧。","截斷姦吏舌，擘开冤人腸。","明朝向西望，走马归汶陽。"]', '诗', 'shi', '', NULL, '奉命齊州推事畢寄本府尚書 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bbd3ad2-b059-4fb7-9a47-5f2d3203b6d4', '北郭閑思', '北郭闲思', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["山前山後是青草，盡日出門還掩門。","每思骨肉在天畔，來看野翁憐子孫。"]', '["山前山後是青草，尽日出门還掩门。","每思骨肉在天畔，来看野翁怜子孫。"]', '诗', 'shi', '', NULL, '北郭閑思 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd118d8-0ad5-40b2-8545-eef1e5b1b536', '戰城南', '戰城南', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["千金畫陣圖，自爲弓劍苦。","殺盡田野人，將軍猶愛武。","性命換他恩，功成誰作主。","鳳皇樓上人，夜夜長歌舞。"]', '["千金畫陣圖，自爲弓劍苦。","殺尽田野人，將軍猶愛武。","性命換他恩，功成誰作主。","鳳皇楼上人，夜夜长歌舞。"]', '诗', 'shi', '', NULL, '戰城南 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efdedbea-7500-4389-b538-a61fc3b631f5', '自退', '自退', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["寒女面如花，空寂常對影。","況我不嫁容，甘爲瓶墮井。"]', '["寒女面如花，空寂常对影。","況我不嫁容，甘爲瓶墮井。"]', '诗', 'shi', '', NULL, '自退 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a5fd1f2-96d6-45ca-9076-2db177bc3645', '早起', '早起', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["月墮滄浪西，門開樹無影。","此時歸夢闌，立在梧桐井。"]', '["月墮滄浪西，门开樹無影。","此时归梦闌，立在梧桐井。"]', '诗', 'shi', '', NULL, '早起 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e10df934-0d17-43e9-b919-be99d05fb292', '古相送', '古相送', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["行人卜去期，白髮根已出。","執君青松枝，空數別來日。","心如七夕女，生死難再匹。","且願車聲迫，莫使馬行疾。","巫山千丈高，亦恐夢相失。"]', '["行人卜去期，白髮根已出。","執君青松枝，空數別来日。","心如七夕女，生死难再匹。","且願车声迫，莫使马行疾。","巫山千丈高，亦恐梦相失。"]', '诗', 'shi', '', NULL, '古相送 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd229e13-32ec-4068-99a7-22c4475bb0df', '甲第', '甲第', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["遊人未入門，花影出門前。","將軍來此住，十里無荒田。"]', '["游人未入门，花影出门前。","將軍来此住，十里無荒田。"]', '诗', 'shi', '', NULL, '甲第 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a01491-ac75-4879-a39b-30198439af5a', '望不來', '望不来', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["見花憶郎面，常願花色新。","爲郎容貌好，難有相似人。"]', '["见花憶郎面，常願花色新。","爲郎容貌好，难有相似人。"]', '诗', 'shi', '', NULL, '望不來 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39957c11-2ba2-4503-a8f4-7e1382888d1d', '官倉鼠', '官倉鼠', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["官倉老鼠大如斗，見人開倉亦不走。","健兒無糧百姓飢，誰遣朝朝入君口。"]', '["官倉老鼠大如斗，见人开倉亦不走。","健兒無糧百姓飢，誰遣朝朝入君口。"]', '诗', 'shi', '', NULL, '官倉鼠 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf217212-29a8-45fd-b472-9f76c8a74166', '題濮廟', '題濮廟', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["曉祭瑤齋夜扣鐘，鼇頭風起浪重重。","人間直有仙桃種，海上應無肉馬蹤。","赤水夢沈迷象罔，翠華恩斷泣芙蓉。","不知皇帝三宮駐，始向人間著衮龍。"]', '["晓祭瑤斋夜扣鐘，鼇头风起浪重重。","人间直有仙桃種，海上應無肉马蹤。","赤水梦沈迷象罔，翠华恩斷泣芙蓉。","不知皇帝三宮駐，始向人间著衮龙。"]', '诗', 'shi', '', NULL, '題濮廟 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66d4ee21-7a8e-4fc7-a988-c238fdd07add', '偶題', '偶題', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["白玉先生多在市，青牛道士不居山。","但能共得丹田語，正是忙時身亦閑。"]', '["白玉先生多在市，青牛道士不居山。","但能共得丹田語，正是忙时身亦闲。"]', '诗', 'shi', '', NULL, '偶題 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7504f5f2-8425-4a19-aeb9-2ae145df7ae9', '登岳陽樓有懷寄座主相公', '登岳陽楼有懷寄座主相公', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["南登岳陽樓，北眺長安道。","不見昇平里，千山樹如草。","骨肉在南楚，沈憂起常早。","白社愁成空，秋蕪待誰掃。","常聞詩人語，西子不宜老。","賴識丹元君，時來語蓬島。"]', '["南登岳陽楼，北眺长安道。","不见昇平里，千山樹如草。","骨肉在南楚，沈憂起常早。","白社愁成空，秋蕪待誰掃。","常闻诗人語，西子不宜老。","賴識丹元君，时来語蓬島。"]', '诗', 'shi', '', NULL, '登岳陽樓有懷寄座主相公 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a87ff370-52c9-455a-8379-530e0edef59b', '出關', '出关', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["山上黃犢走避人，山下女郎歌滿野。","我獨南征恨此身，更有無成出關者。"]', '["山上黄犢走避人，山下女郎歌满野。","我独南征恨此身，更有無成出关者。"]', '诗', 'shi', '', NULL, '出關 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e4a29e-b113-4803-89fc-8025342c30ef', '將赴天平職書懷寄翰林從兄', '將赴天平職书懷寄翰林從兄', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["居處絕人事，門前雀羅施。","誰遣辟書至，僕隸皆展眉。","匹馬渡河洛，西風飄路岐。","手執王粲筆，閑吟向旌旗。","香晚翠蓮動，吟餘紅燭移。","開口啖酒肉，將何報相知。","況我魏公子，相願不相疑。","豈學官倉鼠，飽食無所爲。","白露霑碧草，芙蓉落清池。","自小不到處，全家忽如歸。","吾宗處清切，立在白玉墀。","方得一侍座，單車又星飛。","願將門底水，永託萬頃陂。"]', '["居处絕人事，门前雀羅施。","誰遣辟书至，僕隸皆展眉。","匹马渡河洛，西风飄路岐。","手執王粲笔，闲吟向旌旗。","香晚翠蓮动，吟餘紅燭移。","开口啖酒肉，將何報相知。","況我魏公子，相願不相疑。","豈学官倉鼠，飽食無所爲。","白露霑碧草，芙蓉落清池。","自小不到处，全家忽如归。","吾宗处清切，立在白玉墀。","方得一侍座，單车又星飞。","願將门底水，永託万頃陂。"]', '诗', 'shi', '', NULL, '將赴天平職書懷寄翰林從兄 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a86077d4-d321-4bff-9003-658421d06acc', '賀雪寄本府尚書', '賀雪寄本府尚书', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["雨雪不順時，陰陽失明晦。","麥根半成土，農夫泣相對。","我公誠訴天，天地忽已泰。","長飆卷白雲，散落羣峰外。","拂砌花影明，交宮鶴翎碎。","宿鳥晨不飛，猶疑月光在。","碧樹香盡發，蠹蟲聲漸退。","有客懷兔園，吟詩遶城內。"]', '["雨雪不順时，陰陽失明晦。","麦根半成土，農夫泣相对。","我公誠訴天，天地忽已泰。","长飆卷白云，散落羣峰外。","拂砌花影明，交宮鹤翎碎。","宿鸟晨不飞，猶疑月光在。","碧樹香尽發，蠹蟲声漸退。","有客懷兔园，吟诗遶城內。"]', '诗', 'shi', '', NULL, '賀雪寄本府尚書 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32b868a8-bad0-4520-b062-fb6a815dd876', '寄嵩陽道人', '寄嵩陽道人', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["三山浮海倚蓬瀛，路入真元險盡平。","華表千年孤鶴語，人間一夢晚蟬鳴。","將龍逐虎神初王，積火焚心氣漸清。","見說嵩陽有仙客，欲持金簡問長生。"]', '["三山浮海倚蓬瀛，路入真元險尽平。","华表千年孤鹤語，人间一梦晚蟬鳴。","將龙逐虎神初王，積火焚心氣漸清。","见说嵩陽有仙客，欲持金簡问长生。"]', '诗', 'shi', '', NULL, '寄嵩陽道人 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09dbbd55-91ec-490c-8be1-10c7f9d326ed', '去不返', '去不返', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["寒女不自知，嫁爲公子妻。","親情未識面，明日便東西。","但得上馬了，一去頭不回。","雙輪如鳥飛，影盡東南街。","九重十二門，一門四扇開。","君從此路去，妾向此路啼。","但得見君面，不辭插荆釵。"]', '["寒女不自知，嫁爲公子妻。","親情未識面，明日便东西。","但得上马了，一去头不回。","雙輪如鸟飞，影尽东南街。","九重十二门，一门四扇开。","君從此路去，妾向此路啼。","但得见君面，不辞插荆釵。"]', '诗', 'shi', '', NULL, '去不返 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d069148-0ce1-4eb6-af19-e7feb6d4fc57', '送進士下第歸南海', '送進士下第归南海', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["數片紅霞映夕陽，攬君衣袂更移觴。","行人莫歎碧雲晚，上國每年春草芳。","雪過藍關寒氣薄，鴈回湘浦怨聲長。","應無惆悵滄波遠，十二玉樓非我鄉。"]', '["數片紅霞映夕陽，攬君衣袂更移觴。","行人莫歎碧云晚，上国每年春草芳。","雪過藍关寒氣薄，鴈回湘浦怨声长。","應無惆悵滄波远，十二玉楼非我乡。"]', '诗', 'shi', '', NULL, '送進士下第歸南海 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77544c22-c1f5-4e3c-b4e3-978cb829a6a8', '送厲圖南下第歸澧州', '送厲圖南下第归澧州', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["當春人盡歸，我獨無歸計。","送君自多感，不是緣下第。","君看山上草，盡有干雲勢。","結根既不然，何必更掩袂。","澧水鱸魚賤，荆門楊柳細。","勿爲陽豔留，此處有月桂。","言畢尊未乾，十二門欲閉。","佇立望不見，登高更流涕。","吟君別我詩，悵望水煙際。"]', '["當春人尽归，我独無归計。","送君自多感，不是緣下第。","君看山上草，尽有干云勢。","結根既不然，何必更掩袂。","澧水鱸鱼賤，荆门楊柳細。","勿爲陽豔留，此处有月桂。","言畢尊未乾，十二门欲閉。","佇立望不见，登高更流涕。","吟君別我诗，悵望水煙際。"]', '诗', 'shi', '', NULL, '送厲圖南下第歸澧州 曹鄴 shi');
